-- Alice's Library -- traduções em português (leitura bilíngue).
-- Gerado por scripts/build-traducoes-sql.mjs a partir de public/alices-library/livros/*.pt.json. Não edite à mão.
-- Rodar DEPOIS de livros.sql e livros_texto.sql, na ordem dos números dos arquivos (00, 01, 02 ... e o último). Pode repetir: é um "upsert".
--
-- IMPORTANTE: o leitor do iPad lê as traduções dos arquivos livros/<slug>.pt.json que vão no app; rodar este SQL
-- NÃO é necessário para a leitura bilíngue funcionar. Ele guarda a mesma tradução no banco (consulta, backup,
-- revisão) e marca em public.livros quais livros têm tradução.

-- parte 3 de 10: 11 livros
begin;

-- george-bernard-shaw_saint-joan (480 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('george-bernard-shaw_saint-joan', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"scenei":"Cena I","sceneii":"Cena II","sceneiii":"Cena III"}$tr$::jsonb, $tr${"afinespringmorningontherivermeusebetween~inthecastleofvaucouleurs~99":"Uma bela manhã de primavera às margens do rio Meuse, entre a Lorena e a Champanhe, no ano de 1429 d.C., no castelo de Vaucouleurs.","captainrobertdebaudricourtamilitarysquir~becausehehasneverbloomed~284":"O capitão Robert de Baudricourt, escudeiro militar, bonito e fisicamente enérgico, mas sem vontade própria, disfarça esse defeito à sua maneira habitual, vociferando terrivelmente contra seu mordomo, um verme pisoteado, de poucas carnes e poucos cabelos, que podia ter qualquer idade entre 18 e 55 anos, sendo o tipo de homem que a idade não consegue murchar porque jamais chegou a florescer.","thetwoareinasunnystonechamberonthefirstf~oodenchestunderthewindow~443":"Os dois estão numa clara sala de pedra no primeiro andar do castelo. A uma mesa de carvalho simples e robusta, sentado numa cadeira que combina com ela, o capitão apresenta o perfil esquerdo. O mordomo está de pé diante dele, do outro lado da mesa, se é que uma postura tão submissa como a sua pode ser chamada de estar de pé. A janela com mainéis, do século XIII, está aberta atrás dele. Perto dela, no canto, há uma torrinha com uma estreita porta em arco que dá para uma escada em caracol, a qual desce até o pátio. Há um banco robusto de quatro pés sob a mesa e uma arca de madeira sob a janela.","robertnoeggsnoeggsthousandthundersmanwha~manwhatdoyoumeanbynoeggs~58":"Robert — Sem ovos! Sem ovos!! Mil trovões, homem, que quer dizer com sem ovos?","stewardsiritisnotmyfaultitistheactofgod~otmyfaultitistheactofgod~39":"Mordomo — Senhor: não é culpa minha. É obra de Deus.","robertblasphemyyoutellmetherearenoeggsan~ndyoublameyourmakerforit~63":"Robert — Blasfêmia. Você me diz que não há ovos e culpa o seu Criador por isso.","stewardsirwhatcanidoicannotlayeggs~whatcanidoicannotlayeggs~34":"Mordomo — Senhor: que posso eu fazer? Não posso pôr ovos.","robertsarcastichayoujestaboutit~arcastichayoujestaboutit~31":"Robert — Sarcástico. Ah! Você zomba disso.","stewardnosirgodknowsweallhavetogowithout~havesirthehenswillnotlay~77":"Mordomo — Não, senhor, Deus sabe que não. Todos nós temos de ficar sem ovos, assim como o senhor. As galinhas não botam.","robertindeedrisingnowlistentomeyou~edrisingnowlistentomeyou~34":"Robert — Ora essa! Levantando-se. Agora ouça-me bem, você.","stewardhumblyyessir~stewardhumblyyessir~19":"Mordomo — Humildemente. Sim, senhor.","robertwhatami~robertwhatami~13":"Robert — O que sou eu?","stewardwhatareyousir~stewardwhatareyousir~20":"Mordomo — O que o senhor é, senhor?","robertcomingathimyeswhatamiamirobertsqui~fvaucouleursoramiacowboy~102":"Robert — Avançando sobre ele. Sim: o que sou eu? Sou Robert, escudeiro de Baudricourt e capitão deste castelo de Vaucouleurs: ou sou um vaqueiro?","stewardohsiryouknowyouareagreatermanhere~anherethanthekinghimself~58":"Mordomo — Oh, senhor, o senhor sabe que é aqui um homem maior do que o próprio rei.","robertpreciselyandnowdoyouknowwhatyouare~ndnowdoyouknowwhatyouare~40":"Robert — Precisamente. E agora, sabe o que você é?","stewardiamnobodysirexceptthatihavethehon~ethehonortobeyoursteward~57":"Mordomo — Não sou ninguém, senhor, a não ser que tenho a honra de ser o seu mordomo.","robertdrivinghimtothewalladjectivebyadje~ehestridesbacktothetable~212":"Robert — Encurralando-o, adjetivo por adjetivo. Você não tem apenas a honra de ser meu mordomo, mas o privilégio de ser o pior, mais incompetente, babão, choramingas, tagarela, balbuciante idiota de mordomo de toda a França. Volta a passos largos para a mesa.","stewardcoweringonthechestyessirtoagreatm~likeyouimustseemlikethat~66":"Mordomo — Encolhido sobre a arca. Sim, senhor: a um grande homem como o senhor devo parecer assim.","robertturningmyfaultisupposeeh~turningmyfaultisupposeeh~30":"Robert — Virando-se. A culpa é minha, suponho. Hein?","stewardcomingtohimdeprecatinglyohsiryoua~stinnocentwordssuchaturn~77":"Mordomo — Aproximando-se dele, em tom de súplica. Oh, senhor: o senhor sempre dá às minhas palavras mais inocentes uma volta tão estranha!","robertiwillgiveyourneckaturnifyoudaretel~rearethatyoucannotlayany~92":"Robert — Vou dar uma volta no seu pescoço se você ousar me dizer, quando eu perguntar quantos ovos há, que não pode pô-los.","stewardprotestingohsirohsir~wardprotestingohsirohsir~27":"Mordomo — Protestando. Oh, senhor, oh, senhor...","robertnonotohsirohsirbutnosirnosirmythre~terdaytoodonotforgetthat~264":"Robert — Não: nada de oh, senhor, oh, senhor, mas sim, não, senhor, não, senhor. Minhas três galinhas da Berbéria e a preta são as melhores poedeiras da Champanhe. E você vem me dizer que não há ovos! Quem os roubou? Diga-me isso antes que eu o ponha a pontapés pelo portão do castelo como mentiroso e vendedor dos meus bens a ladrões. O leite também faltou ontem: não se esqueça disso.","stewarddesperateiknowsiriknowonlytoowell~morrowtherewillbenothing~93":"Mordomo — Desesperado. Eu sei, senhor. Sei só demais. Não há leite: não há ovos: amanhã não haverá nada.","robertnothingyouwillstealtheloteh~hingyouwillstealtheloteh~33":"Robert — Nada! Você vai roubar tudo: hein?","stewardnosirnobodywillstealanythingbutth~aspellonuswearebewitched~69":"Mordomo — Não, senhor: ninguém vai roubar coisa alguma. Mas há um feitiço sobre nós: estamos enfeitiçados.","robertthatstoryisnotgoodenoughformerober~sseatwithanairoffinality~237":"Robert — Essa história não me convence. Robert de Baudricourt queima bruxas e enforca ladrões. Vá. Traga-me quatro dúzias de ovos e dois galões de leite aqui nesta sala antes do meio-dia, ou que o Céu tenha piedade dos seus ossos! Eu lhe ensinarei a me fazer de tolo. Retoma o assento com ar de quem deu a palavra final.","stewardsiritellyoutherearenoeggstherewil~longasthemaidisatthedoor~98":"Intendente — Senhor: digo-lhe que não há ovos. Não haverá — nem que me matem por isso — enquanto A Donzela estiver à porta.","robertthemaidwhatmaidwhatareyoutalkingab~idwhatareyoutalkingabout~43":"Robert — A Donzela! Que donzela? De que está falando?","stewardthegirlfromlorrainesirfromdomremy~omlorrainesirfromdomremy~40":"Intendente — A moça da Lorena, senhor. De Domrémy.","robertrisinginfearfulwraththirtythousand~eragoodhidingisherestill~221":"Robert — Levantando-se numa ira terrível. Trinta mil trovões! Cinquenta mil diabos! Quer dizer que aquela moça, que teve o descaramento de pedir para me ver há dois dias, e que mandei o senhor devolver ao pai com ordens de que lhe desse uma boa sova, ainda está aqui?","stewardihavetoldhertogosirshewont~avetoldhertogosirshewont~33":"Intendente — Mandei-a ir embora, senhor. Ela não vai.","robertididnottellyoutotellhertogoitoldyo~ordersaretheyafraidofher~145":"Robert — Não lhe mandei mandá-la ir embora: mandei pô-la para fora. O senhor tem cinquenta homens de armas e uma dúzia de criados corpulentos para cumprir minhas ordens. Têm medo dela?","stewardsheissopositivesir~tewardsheissopositivesir~25":"Intendente — Ela é tão categórica, senhor.","robertseizinghimbythescruffoftheneckposi~oingtothrowyoudownstairs~82":"Robert — Agarrando-o pelo cangote. Categórica! Agora escute aqui. Vou atirá-lo escada abaixo.","stewardnosirplease~stewardnosirplease~18":"Intendente — Não, senhor. Por favor.","robertwellstopmebybeingpositiveitsquitee~asyanyslutofagirlcandoit~64":"Robert — Pois então me detenha sendo categórico. É facílimo: qualquer moleca desavergonhada consegue.","stewardhanginglimpinhishandssirsiryoucan~ositivethaniambutsoisshe~198":"Intendente — Pendendo mole em suas mãos. Senhor, senhor: não se livra dela atirando-me para fora. Robert tem de deixá-lo cair. Ele se agacha de joelhos no chão, contemplando o amo com resignação. Veja, senhor, o senhor é muito mais categórico do que eu. Mas ela também é.","robertiamstrongerthanyouareyoufool~trongerthanyouareyoufool~34":"Robert — Sou mais forte que você, seu tolo.","stewardnosiritisntthatitsyourstrongchara~girlbutwecannotmakehergo~108":"Intendente — Não, senhor: não é isso: é o seu caráter forte, senhor. Ela é mais fraca que nós: é apenas um fiapo de moça; mas não conseguimos fazê-la ir embora.","robertyouparcelofcursyouareafraidofher~lofcursyouareafraidofher~38":"Robert — Seu bando de cães: vocês têm medo dela.","stewardrisingcautiouslynosirweareafraido~psyoucouldfrightenhersir~135":"Intendente — Levantando-se com cautela. Não, senhor: temos medo do senhor; mas ela nos dá coragem. Ela realmente não parece ter medo de nada. Talvez o senhor pudesse assustá-la, senhor.","robertgrimlyperhapswhereisshenow~imlyperhapswhereisshenow~32":"Robert — Sombrio. Talvez. Onde está ela agora?","stewarddowninthecourtyardsirtalkingtothe~rsexceptwhensheispraying~108":"Intendente — Lá embaixo no pátio, senhor, falando com os soldados como de costume. Vive falando com os soldados, exceto quando está rezando.","robertprayinghayoubelieveshepraysyouidio~lythroughithalloyouthere~164":"Robert — Rezando! Ha! O senhor acredita que ela reza, seu idiota. Conheço o tipo de moça que vive falando com soldados. Vai falar um pouco comigo. Vai à janela e grita ferozmente por ela. Ei, você aí!","agirlsvoicebrightstrongandroughisitmesir~tstrongandroughisitmesir~40":"Voz de Moça — Clara, forte e rude. É comigo, senhor?","robertyesyou~robertyesyou~12":"Robert — Sim, com você.","thevoicebeyoucaptain~thevoicebeyoucaptain~20":"A Voz — O senhor é o capitão?","robertyesdamnyourimpudenceibecaptaincome~wherehesitsmagisterially~176":"Robert — Sim, maldito seja o seu descaramento, eu sou o capitão. Suba aqui. Para os soldados no pátio. Mostrem-lhe o caminho, vocês. E empurrem-na depressa. Deixa a janela e volta ao seu lugar à mesa, onde se senta com ar magistral.","stewardwhisperingshewantstogoandbeasoldi~allyhestealsbehindrobert~129":"Intendente — Sussurrando. Ela quer ir e ser soldado ela mesma. Quer que o senhor lhe dê roupas de soldado. Armadura, senhor! E uma espada! De verdade! Esgueira-se para trás de Robert.","joanappearsintheturretdoorwaysheisanable~ppealingveryhardtoresist~495":"Joan aparece na porta da torre. É uma moça do campo, robusta, de 17 ou 18 anos, decentemente vestida de vermelho, com um rosto incomum: olhos muito afastados e saltados, como ocorre com frequência em pessoas muito imaginativas, um nariz longo e bem-feito de narinas largas, lábio superior curto, boca resoluta mas de lábios cheios e um belo queixo de lutadora. Aproxima-se ansiosa da mesa, encantada por ter enfim penetrado na presença de Baudricourt, e cheia de esperança quanto ao resultado. O cenho franzido dele não a detém nem a assusta minimamente. Sua voz é normalmente uma voz cordial e persuasiva, muito confiante, muito apelativa, muito difícil de resistir.","joanbobbingacurtseygoodmorningcaptainsqu~eareyourordersfrommylord~142":"Joan — Fazendo uma reverência. Bom dia, capitão escudeiro. Capitão: o senhor deve me dar um cavalo e armadura e alguns soldados, e me enviar ao Delfim. Essas são as ordens do meu Senhor.","robertoutragedordersfromyourlordandwhoth~oordersexceptfromtheking~171":"Robert — Ultrajado. Ordens do seu senhor! E quem diabos pode ser o seu senhor? Volte a ele, e diga-lhe que não sou duque nem par às suas ordens: sou escudeiro de Baudricourt; e não recebo ordens senão do rei.","joanreassuringlyyessquirethatisallrightm~tmylordisthekingofheaven~62":"Joan — Tranquilizadora. Sim, escudeiro: está tudo certo. O meu Senhor é o Rei do Céu.","robertwhythegirlsmadtothestewardwhydidnt~tyoutellmesoyoublockhead~63":"Robert — Ora, a moça é louca. Para o intendente. Por que não me disse isso, seu bronco?","stewardsirdonotangerhergiveherwhatshewan~erhergiveherwhatshewants~42":"Intendente — Senhor: não a irrite: dê-lhe o que ela quer.","joanimpatientbutfriendlytheyallsayiammad~dowhathehasputintomymind~127":"Joan — Impaciente, mas amistosa. Todos dizem que sou louca até eu falar com eles, escudeiro. Mas veja que é a vontade de Deus que o senhor faça o que Ele me pôs na mente.","robertitisthewillofgodthatishallsendyoub~ouwhathaveyoutosaytothat~137":"Robert — É a vontade de Deus que eu a mande de volta ao seu pai com ordens de trancá-la a sete chaves e surrá-la até lhe tirar a loucura. O que tem a dizer a isso?","joanyouthinkyouwillsquirebutyouwillfindi~uwouldnotseemebuthereiam~97":"Joan — O senhor acha que fará isso, escudeiro; mas verá que tudo acontece bem diferente. Disse que não me receberia; mas aqui estou.","stewardappealingyessiryouseesir~appealingyessiryouseesir~31":"Intendente — Apelando. Sim, senhor. Está vendo, senhor.","robertholdyourtongueyou~robertholdyourtongueyou~23":"Robert — Cale a boca, você.","stewardabjectlyyessir~stewardabjectlyyessir~21":"Intendente — Abjeto. Sim, senhor.","roberttojoanwithasourlossofconfidencesoy~umingonmyseeingyouareyou~73":"Robert — Para Joan, com amarga perda de confiança. Então está presumindo que eu a receba, é isso?","joansweetlyyessquire~joansweetlyyessquire~20":"Joan — Docemente. Sim, escudeiro.","robertfeelingthathehaslostgroundbringsdo~meiamgoingtoassertmyself~180":"Robert — Sentindo que perdeu terreno, desfere os dois punhos de uma vez sobre a mesa e infla o peito imponentemente para curar a sensação indesejada e familiar demais. Agora escute. Vou me impor.","joanbusilypleasedosquirethehorsewillcost~toraisethesiegeoforleans~283":"Joan — Atarefada. Por favor, imponha-se, escudeiro. O cavalo custará dezesseis francos. É bastante dinheiro; mas posso economizar na armadura. Posso achar a armadura de algum soldado que me sirva bem o bastante: sou muito robusta; e não preciso de armadura bonita feita sob medida como a que o senhor usa. Não vou querer muitos soldados: o Delfim me dará todos de que precisar para levantar o cerco de Orléans.","robertflabbergastedtoraisethesiegeoforle~toraisethesiegeoforleans~43":"Robert — Estupefato. Levantar o cerco de Orléans!","joansimplyyessquirethatiswhatgodissendin~omewithmepollyandjackand~157":"Joan — Com simplicidade. Sim, escudeiro: é isso que Deus me envia para fazer. Três homens bastarão para o senhor mandar comigo, se forem bons homens e gentis comigo. Prometeram vir comigo. Polly e Jack e...","robertpollyyouimpudentbaggagedoyoudareca~depoulengeypollytomyface~80":"Robert — Polly!! Sua atrevida, ousa chamar o escudeiro Bertrand de Poulengey de Polly na minha cara?","joanhisfriendscallhimsosquireididnotknow~nowhehadanyothernamejack~61":"Joan — Os amigos o chamam assim, escudeiro: eu não sabia que ele tinha outro nome. Jack...","robertthatismonsieurjohnofmetzisuppose~nsieurjohnofmetzisuppose~38":"Robert — Esse é Monsieur John de Metz, suponho?","joanyessquirejackwillcomewillinglyheisav~ouhaveonlytogivetheorder~242":"Joan — Sim, escudeiro. Jack virá de boa vontade: é um cavalheiro muito bondoso, e me dá dinheiro para eu dar aos pobres. Creio que John Godsave virá, e Dick, o Arqueiro, e seus criados John de Honecourt e Julian. Não haverá aborrecimento para o senhor, escudeiro: arranjei tudo: o senhor só precisa dar a ordem.","robertcontemplatingherinastuporofamazeme~ofamazementwelliamdamned~55":"Robert — Contemplando-a num estupor de pasmo. Ora, que eu seja condenado!","joanwithmuffledsweetnessnosquiregodisver~edforeverasmyfirsthelper~202":"Joan — Com doçura abafada. Não, escudeiro: Deus é muito misericordioso; e as bem-aventuradas santas Catarina e Margarida, que falam comigo todos os dias, ele boquiaberto, intercederão pelo senhor. Irá para o paraíso; e seu nome será lembrado para sempre como o meu primeiro ajudante.","roberttothestewardstillmuchbotheredbutch~aboutmonsieurdepoulengey~106":"Robert — Para o intendente, ainda muito incomodado, mas mudando de tom ao seguir uma nova pista. É verdade isso sobre Monsieur de Poulengey?","stewardeagerlyyessirandaboutmonsieurdeme~otheybothwanttogowithher~68":"Intendente — Ansioso. Sim, senhor, e sobre Monsieur de Metz também. Ambos querem ir com ela.","robertthoughtfulmfhegoestothewindowandsh~angetoutandwaitintheyard~142":"Robert — Pensativo. Hum! Vai à janela e grita para o pátio. Ei! Vocês aí: mandem Monsieur de Poulengey até mim, por favor. Volta-se para Joan. Fora daqui; e espere no pátio.","joansmilingbrightlyathimrightsquireshego~himrightsquireshegoesout~45":"Joan — Sorrindo radiante para ele. Está bem, escudeiro. Sai.","roberttothestewardgowithheryouyouditheri~ishallhaveheruphereagain~107":"Robert — Para o intendente. Vá com ela, seu imbecil trêmulo. Fique ao alcance da voz; e não a perca de vista. Vou chamá-la aqui de novo.","stewarddosoingodsnamesirthinkofthosehens~bestlayersinchampagneand~67":"Intendente — Faça-o em nome de Deus, senhor. Pense naquelas galinhas, as melhores poedeiras de Champagne; e...","robertthinkofmybootandtakeyourbacksideou~urbacksideoutofreachofit~52":"Robert — Pense na minha bota; e leve o seu traseiro para fora do alcance dela.","thestewardretreatshastilyandfindshimself~akeswayforhimandvanishes~385":"O intendente retira-se às pressas e se vê diante, na porta, de Bertrand de Poulengey, um linfático fidalgo francês de armas, de uns 36 anos mais ou menos, empregado no departamento do preboste-marechal, sonhadoramente distraído, que raramente fala sem que lhe falem, e então com lentidão e teimosia na resposta: em tudo contrastando com o Robert presunçoso, boquirroto, superficialmente enérgico e fundamentalmente sem vontade. O intendente lhe dá passagem e desaparece.","poulengeysalutesandstandsawaitingorders~sandstandsawaitingorders~39":"Poulengey bate continência e fica à espera de ordens.","robertgeniallyitisntservicepollyafriendl~derthetablewithhisinstep~97":"Robert — Genial. Não é serviço, Polly. É uma conversa de amigo. Sente-se. Puxa o banco de debaixo da mesa com o peito do pé.","poulengeyrelaxingcomesintotheroomplacest~blebeginsthefriendlytalk~153":"Poulengey, relaxando, entra na sala; coloca o banco entre a mesa e a janela; e senta-se ruminando. Robert, sentado pela metade na ponta da mesa, começa a conversa de amigo.","robertnowlistentomepollyimusttalktoyouli~musttalktoyoulikeafather~49":"Robert — Agora escute, Polly. Preciso falar com você como um pai.","poulengeylooksupathimgravelyforamomentbu~foramomentbutsaysnothing~52":"Poulengey ergue os olhos para ele, grave, por um momento, mas nada diz.","robertitsaboutthisgirlyouareinterestedin~ofriendspollyhandsoffher~723":"Robert — É sobre essa moça que lhe interessa. Pois bem, eu a vi. Falei com ela. Primeiro, é louca. Isso não importa. Segundo, não é camponesa qualquer. É burguesa. Isso importa bastante. Conheço exatamente a classe dela. O pai veio aqui no ano passado representar a aldeia num processo: é um dos notáveis de lá. Um lavrador. Não um fidalgo lavrador: ganha dinheiro com isso, e vive disso. Ainda assim, não é jornaleiro. Nem artesão. Pode ter um primo advogado, ou na Igreja. Essa gente pode não ter importância social; mas pode dar muito incômodo às autoridades. Isto é, a mim. Ora, sem dúvida lhe parece coisa muito simples levar esta moça, enganando-a até que acredite que a leva ao Delfim. Mas se a meter em apuros, pode me meter numa enrascada sem fim, pois sou o senhor do pai dela e responsável pela proteção dela. Portanto, amigos ou não amigos, Polly, mãos longe dela.","poulengeywithdeliberateimpressivenessish~elfinthatwayasofthisgirl~101":"Poulengey — Com deliberada solenidade. Pensaria tão pouco nela desse modo quanto na própria Santa Virgem.","robertcomingoffthetablebutshesaysyouandj~hedauphinseriouslyareyou~160":"Robert — Descendo da mesa. Mas ela diz que você e Jack e Dick se ofereceram para ir com ela. Para quê? Não vai me dizer que leva a sério a ideia maluca dela de ir ao Delfim, vai?","poulengeyslowlythereissomethingabouthert~ethingitmaybeworthtrying~243":"Poulengey — Devagar. Há algo nela. Alguns lá do corpo de guarda são bastante boca-suja e de mente suja. Mas não houve uma palavra que tivesse algo a ver com ela ser mulher. Pararam de praguejar diante dela. Há algo. Algo. Pode valer a pena tentar.","robertohcomepollypullyourselftogethercom~uchheretreatsdisgustedly~115":"Robert — Ora, vamos, Polly! Recomponha-se. O senso comum nunca foi o seu forte; mas isto é um pouco demais. Recua com desgosto.","poulengeyunmovedwhatisthegoodofcommonsen~thelegitimacyofherownson~446":"Poulengey — Imperturbável. De que serve o senso comum? Se tivéssemos algum senso comum, juntaríamos-nos ao Duque da Borgonha e ao rei inglês. Eles mantêm metade do país, até o Loire. Têm Paris. Têm este castelo: você sabe muito bem que tivemos de entregá-lo ao Duque de Bedford e que só o mantém sob palavra. O Delfim está em Chinon, como um rato num canto, exceto que não quer lutar. Nem sequer sabemos se ele é o Delfim: a mãe diz que não é; e ela deveria saber. Pense nisso! a rainha negando a legitimidade do próprio filho!","robertwellshemarriedherdaughtertotheengl~hkingcanyoublamethewoman~66":"Robert — Bem, ela casou a filha com o rei inglês. Pode-se culpar a mulher?","poulengeyiblamenobodybutthankstohertheda~dwillnotbeabletostopthem~135":"Poulengey — Não culpo ninguém. Mas graças a ela o Delfim está derrotado e liquidado; e é melhor encararmos isso. Os ingleses tomarão Orléans: o Bastardo não conseguirá detê-los.","roberthebeattheenglishtheyearbeforelasta~statmontargisiwaswithhim~61":"Robert — Ele derrotou os ingleses há dois anos em Montargis. Eu estava com ele.","poulengeynomatterhismenarecowednowandhec~aveoursidenowbutamiracle~105":"Poulengey — Não importa: os homens dele agora estão acovardados; e ele não faz milagres. E digo-lhe que nada pode salvar o nosso lado agora senão um milagre.","robertmiraclesareallrightpollytheonlydif~attheydonthappennowadays~84":"Robert — Milagres são muito bons, Polly. A única dificuldade com eles é que hoje em dia não acontecem.","poulengeyiusedtothinksoiamnotsosurenowri~eissomethingaboutthegirl~157":"Poulengey — Eu costumava pensar assim. Já não tenho tanta certeza. Levantando-se e movendo-se ruminando em direção à janela. De qualquer modo, não é hora de deixar pedra sobre pedra sem virar. Há algo nessa moça.","robertohyouthinkthegirlcanworkmiraclesdo~girlcanworkmiraclesdoyou~43":"Robert — Ah! Acha que a moça faz milagres, é?","poulengeyithinkthegirlherselfisabitofami~gamehewanderstotheturret~131":"Poulengey — Acho que a própria moça é um pouco de milagre. Seja como for, é a última carta que nos resta na mão. Melhor jogá-la do que largar o jogo. Vagueia até a torre.","robertwaveringyoureallythinkthat~veringyoureallythinkthat~32":"Robert — Hesitando. Acha mesmo isso?","poulengeyturningisthereanythingelseleftf~hingelseleftforustothink~51":"Poulengey — Voltando-se. Resta-nos mais alguma coisa a pensar?","robertgoingtohimlookherepollyifyouwerein~ofsixteenfrancsforahorse~103":"Robert — Indo até ele. Olhe, Polly. Se estivesse no meu lugar, deixaria uma moça dessas lhe tirar dezesseis francos por um cavalo?","poulengeyiwillpayforthehorse~engeyiwillpayforthehorse~28":"Poulengey — Eu pagarei o cavalo.","robertyouwill~robertyouwill~13":"Robert — Você pagará!","poulengeyyesiwillbackmyopinion~geyyesiwillbackmyopinion~30":"Poulengey — Sim: apoiarei minha opinião.","robertyouwillreallygambleonaforlornhopet~tothetuneofsixteenfrancs~63":"Robert — Vai mesmo apostar numa esperança perdida na quantia de dezesseis francos?","poulengeyitisnotagamble~poulengeyitisnotagamble~23":"Poulengey — Não é uma aposta.","robertwhatelseisit~robertwhatelseisit~18":"Robert — O que mais é?","poulengeyitisacertaintyherwordsandherard~thingodhaveputfireintome~70":"Poulengey — É uma certeza. As palavras dela, e sua ardente fé em Deus puseram fogo em mim.","robertgivinghimupwhewyouareasmadassheis~upwhewyouareasmadassheis~39":"Robert — Desistindo dele. Uf! Você é tão louco quanto ela.","poulengeyobstinatelywewantafewmadpeoplen~ethesaneoneshavelandedus~73":"Poulengey — Obstinado. Precisamos de alguns loucos agora. Veja aonde os sensatos nos levaram!","roberthisirresolutenessnowopenlyswamping~usfoolstillifyoufeelsure~108":"Robert — Sua irresolução, agora abertamente, afogando sua decisão afetada. Vou me sentir um grande tolo. Ainda assim, se você tem certeza...?","poulengeyifeelsureenoughtotakehertochino~rtochinonunlessyoustopme~56":"Poulengey — Tenho certeza bastante para levá-la a Chinon — a menos que você me detenha.","robertthisisnotfairyouareputtingtherespo~ingtheresponsibilityonme~53":"Robert — Isso não é justo. Está pondo a responsabilidade em mim.","poulengeyitisonyouwhicheverwayyoudecide~youwhicheverwayyoudecide~39":"Poulengey — Está em você, decida como decidir.","robertyesthatsjustitwhichwayamitodecidey~httohaveanothertalktoher~184":"Robert — Sim: é justamente isso. Como devo decidir? Você não vê como isto é incômodo para mim. Agarrando-se a uma medida protelatória, com a esperança inconsciente de que Joan decida por ele. Acha que devo ter outra conversa com ela?","poulengeyrisingyeshegoestothewindowandca~stothewindowandcallsjoan~47":"Poulengey — Levantando-se. Sim. Vai à janela e chama. Joan!","joansvoicewillheletusgopolly~svoicewillheletusgopolly~28":"Voz de Joan — Ele vai nos deixar ir, Polly?","poulengeycomeupcomeinturningtorobertshal~ertshallileaveyouwithher~57":"Poulengey — Suba. Entre. Voltando-se para Robert. Devo deixá-lo a sós com ela?","robertnostayhereandbackmeup~ertnostayhereandbackmeup~27":"Robert — Não: fique aqui; e me apoie.","poulengeysitsdownonthechestrobertgoesbac~oancomesinfullofgoodnews~135":"Poulengey senta-se no baú. Robert volta à sua cadeira magistral, mas continua de pé para se inflar de modo mais imponente. Joan entra, cheia de boas notícias.","joanjackwillgohalvesforthehorse~kwillgohalvesforthehorse~31":"Joan — Jack pagará metade do cavalo.","robertwellhesitsdeflated~robertwellhesitsdeflated~24":"Robert — Ora!! Senta-se, desinflado.","poulengeygravelysitdownjoan~lengeygravelysitdownjoan~27":"Poulengey — Grave. Sente-se, Joan.","joancheckedalittleandlookingtorobertmayi~leandlookingtorobertmayi~40":"Joan — Um pouco contida, e olhando para Robert. Posso?","robertdowhatyouaretold~robertdowhatyouaretold~22":"Robert — Faça o que lhe mandam.","joancurtsiesandsitsdownonthestoolbetween~withhismostperemptoryair~95":"Joan faz uma reverência e se senta no banco entre eles. Robert enfrenta sua perplexidade com o ar mais peremptório que tem.","robertwhatisyourname~robertwhatisyourname~20":"Robert — Qual é o seu nome?","joanchattilytheyalwayscallmejennyinlorra~thesoldierscallmethemaid~86":"Joan — Tagarela. Na Lorena sempre me chamam de Jenny. Aqui na França sou Joan. Os soldados me chamam de A Donzela.","robertwhatisyoursurname~robertwhatisyoursurname~23":"Robert — Qual é o seu sobrenome?","joansurnamewhatisthatmyfathersometimesca~gaboutityoumetmyfatherhe~92":"Joan — Sobrenome? O que é isso? Meu pai às vezes se chama d’Arc; mas não sei nada a respeito. O senhor conheceu meu pai. Ele...","robertyesyesirememberyoucomefromdomremyi~mdomremyinlorraineithink~55":"Robert — Sim, sim; lembro-me. Você vem de Domrémy, na Lorena, creio.","joanyesbutwhatdoesitmatterweallspeakfren~itmatterweallspeakfrench~42":"Joan — Sim; mas que importa? todos falamos francês.","robertdontaskquestionsanswerthemhowoldar~nsanswerthemhowoldareyou~44":"Robert — Não faça perguntas: responda-as. Quantos anos tem?","joanseventeensotheytellmeitmightbeninete~tbenineteenidontremember~55":"Joan — Dezessete: é o que me dizem. Pode ser dezenove. Não me lembro.","robertwhatdidyoumeanwhenyousaidthatstcat~garettalkedtoyoueveryday~78":"Robert — O que quis dizer quando disse que Santa Catarina e Santa Margarida falavam com você todos os dias?","joantheydo~joantheydo~10":"Joan — Falam.","robertwhataretheylike~robertwhataretheylike~21":"Robert — Como são elas?","joansuddenlyobstinateiwilltellyounothing~ttheyhavenotgivenmeleave~72":"Joan — De repente obstinada. Não lhe direi nada sobre isso: não me deram licença.","robertbutyouactuallyseethemandtheytalkto~youjustasiamtalkingtoyou~64":"Robert — Mas você realmente as vê; e elas falam com você exatamente como estou falando agora?","joannoitisquitedifferenticannottellyouyo~nottalktomeaboutmyvoices~69":"Joan — Não: é bem diferente. Não posso lhe explicar: o senhor não deve falar comigo sobre minhas vozes.","roberthowdoyoumeanvoices~roberthowdoyoumeanvoices~24":"Robert — Como assim? vozes?","joanihearvoicestellingmewhattodotheycome~ewhattodotheycomefromgod~47":"Joan — Ouço vozes que me dizem o que fazer. Vêm de Deus.","roberttheycomefromyourimagination~ycomefromyourimagination~33":"Robert — Vêm da sua imaginação.","joanofcoursethatishowthemessagesofgodcom~themessagesofgodcometous~45":"Joan — Claro. É assim que as mensagens de Deus chegam até nós.","poulengeycheckmate~poulengeycheckmate~18":"Poulengey — Xeque-mate.","robertnofeartojoansogodsaysyouaretoraise~toraisethesiegeoforleans~57":"Robert — Nem pensar! Para Joan. Então Deus diz que você deve levantar o cerco de Orléans?","joanandtocrownthedauphininrheimscathedra~dauphininrheimscathedral~41":"Joan — E coroar o Delfim na catedral de Reims.","robertgaspingcrownthedgosh~bertgaspingcrownthedgosh~26":"Robert — Arquejando. Coroar o De—! Caramba!","joanandtomaketheenglishleavefrance~aketheenglishleavefrance~34":"Joan — E fazer os ingleses deixarem a França.","robertsarcasticanythingelse~ertsarcasticanythingelse~27":"Robert — Sarcástico. Mais alguma coisa?","joancharmingnotjustatpresentthankyousqui~tatpresentthankyousquire~42":"Joan — Encantadora. Por ora não, obrigada, escudeiro.","robertisupposeyouthinkraisingasiegeisase~ksoldieringisanybodysjob~99":"Robert — Suponho que ache que levantar um cerco é tão fácil quanto enxotar uma vaca de um prado. Acha que ser soldado é ofício de qualquer um?","joanidonotthinkitcanbeverydifficultifgod~anysoldiersareverysimple~118":"Joan — Não acho que possa ser muito difícil se Deus está do seu lado e se o senhor está disposto a pôr a vida na mão Dele. Mas muitos soldados são muito simples.","robertgrimlysimpledidyoueverseeenglishso~eenglishsoldiersfighting~54":"Robert — Sombrio. Simples! Alguma vez viu soldados ingleses lutando?","joantheyareonlymengodmadethemjustlikeusb~andtrytospeakourlanguage~159":"Joan — São apenas homens. Deus os fez iguais a nós; mas deu-lhes o seu próprio país e a sua própria língua; e não é Sua vontade que venham ao nosso país e tentem falar a nossa língua.","robertwhohasbeenputtingsuchnonsenseintoy~stheirlanguagetodowithit~221":"Robert — Quem andou pondo tamanho disparate na sua cabeça? Não sabe que os soldados estão sujeitos ao seu senhor feudal, e que para eles, e para você, tanto faz que ele seja o duque da Borgonha, o rei da Inglaterra ou o rei da França? O que a língua deles tem a ver com isso?","joanidonotunderstandthatabitweareallsubj~ordbutaboutyourdutytogod~279":"Joan — Isso eu não entendo nem um pouco. Estamos todos sujeitos ao Rei do Céu; e Ele nos deu nossos países e nossas línguas, e quis que os guardássemos. Se não fosse assim, seria assassinato matar um inglês em batalha; e o senhor, escudeiro, correria grande perigo do fogo do inferno. Não deve pensar no seu dever para com o senhor feudal, mas no seu dever para com Deus.","poulengeyitsnouserobertshecanchokeyoulik~hokeyoulikethateverytime~54":"Poulengey — Não adianta, Robert: ela pode deixá-lo sem ar assim toda vez.","robertcanshebysaintdennisweshallseetojoa~roftheenglishkingsfather~313":"Robert — Pode, por São Dinis! Veremos. Para Joan. Não estamos falando de Deus: estamos falando de assuntos práticos. Pergunto-lhe de novo, moça, alguma vez viu soldados ingleses lutando? Alguma vez os viu saquear, queimar, transformar o campo num deserto? Não ouviu histórias do Príncipe Negro deles, que era mais negro que o próprio diabo, ou do pai do rei inglês?","joanyoumustnotbeafraidrobert~youmustnotbeafraidrobert~28":"Joan — Não deve ter medo, Robert...","robertdamnyouiamnotafraidandwhogaveyoule~veyouleavetocallmerobert~57":"Robert — Maldição, não tenho medo. E quem lhe deu licença de me chamar de Robert?","joanyouwerecalledsoinchurchinthenameofou~oryourbrothersoranybodys~99":"Joan — Assim o chamaram na igreja em nome de nosso Senhor. Todos os outros nomes são do seu pai ou do seu irmão ou de qualquer um.","roberttcha~roberttcha~10":"Robert — Tchá!","joanlistentomesquireatdomremywehadtoflyt~theyhadnothalfmystrength~182":"Joan — Escute-me, escudeiro. Em Domrémy tivemos de fugir para a aldeia vizinha para escapar dos soldados ingleses. Três deles ficaram para trás, feridos. Cheguei a conhecer bastante bem esses três pobres goddams. Não tinham nem metade da minha força.","robertdoyouknowwhytheyarecalledgoddams~wwhytheyarecalledgoddams~38":"Robert — Sabe por que são chamados de goddams?","joannoeveryonecallsthemgoddams~everyonecallsthemgoddams~30":"Joan — Não. Todos os chamam de goddams.","robertitisbecausetheyarealwayscallingont~irlanguagehowdoyoulikeit~127":"Robert — É porque estão sempre pedindo ao seu Deus que condene suas almas à perdição. É isso que goddam significa na língua deles. Que lhe parece?","joangodwillbemercifultothemandtheywillac~ememberthewickednessidid~452":"Joan — Deus será misericordioso com eles; e agirão como Seus bons filhos quando voltarem ao país que Ele fez para eles, e fez eles para ele. Ouvi as histórias do Príncipe Negro. No momento em que tocou o solo do nosso país, o diabo entrou nele e fez dele um demônio negro. Mas em casa, no lugar que Deus fez para ele, era bom. É sempre assim. Se eu fosse à Inglaterra contra a vontade de Deus para conquistar a Inglaterra, e tentasse viver lá e falar a língua de lá, o diabo entraria em mim; e quando eu fosse velha estremeceria ao lembrar a maldade que fiz.","robertperhapsbutthemoredevilyouwerethebe~hemnortenthousandlikeyou~132":"Robert — Talvez. Mas quanto mais diabo você fosse, melhor poderia lutar. É por isso que os goddams tomarão Orléans. E você não pode detê-los, nem dez mil como você.","joanonethousandlikemecanstopthemtenlikem~lishkingbutgodsfrenchone~619":"Joan — Mil como eu podem detê-los. Dez como eu podem detê-los com Deus do nosso lado. Levanta-se impetuosamente e avança sobre ele, incapaz de ficar sentada quieta por mais tempo. O senhor não entende, escudeiro. Nossos soldados são sempre derrotados porque lutam apenas para salvar a pele; e o caminho mais curto para salvar a pele é fugir. Nossos cavaleiros só pensam no dinheiro que farão em resgates: com eles não é matar ou morrer, mas pagar ou ser pago. Mas eu ensinarei todos a lutar para que a vontade de Deus seja feita na França; e então eles empurrarão os pobres goddams à sua frente como ovelhas. O senhor e Polly viverão para ver o dia em que não haverá um só soldado inglês no solo da França; e lá haverá apenas um rei: não o rei feudal inglês, mas o rei francês de Deus.","roberttopoulengeythismaybeallrotpollybut~imshecanputitintoanybody~194":"Robert — Para Poulengey. Isso pode ser tudo bobagem, Polly; mas as tropas poderiam engolir, embora nada do que dizemos pareça capaz de pôr-lhes alguma garra. Até o Delfim poderia engolir. E se ela puder pôr garra nele, pode pôr em qualquer um.","poulengeyicanseenoharmintryingcanyouandt~eissomethingaboutthegirl~67":"Poulengey — Não vejo mal em tentar. E você? E há algo nessa moça...","robertturningtojoannowlistenyoutomeandde~inbeforeihavetimetothink~80":"Robert — Voltando-se para Joan. Agora escute-me você; e não me interrompa, imploro, antes que eu tenha tempo de pensar.","joanplumpingdownonthestoolagainlikeanobe~dientschoolgirlyessquire~64":"Joan — Sentando-se de novo no banco com um baque, como uma colegial obediente. Sim, escudeiro.","robertyourordersarethatyouaretogotochino~emanandthreeofhisfriends~90":"Robert — Suas ordens são: ir a Chinon sob a escolta deste cavalheiro e de três amigos dele.","joanradiantclaspingherhandsohsquireyourh~cledwithlightlikeasaints~75":"Joan — Radiante, apertando as mãos. Ah, escudeiro! Sua cabeça está toda circundada de luz, como a de um santo.","poulengeyhowisshetogetintotheroyalpresen~ogetintotheroyalpresence~42":"Poulengey — Como ela vai entrar na presença real?","robertwhohaslookedupforhishaloratherappr~tcomewhatmayicandonomore~215":"Robert — Que ergueu os olhos à procura da própria auréola, bastante apreensivo. Não sei: como ela entrou na minha presença? Se o Delfim conseguir mantê-la do lado de fora, é homem melhor do que penso. Levantando-se. Vou enviá-la a Chinon; e ela pode dizer que fui eu que a enviei. Então venha o que vier: não posso fazer mais.","joanandthedressimayhaveasoldiersdressmay~oldiersdressmayntisquire~49":"Joan — E o traje? Posso ter roupa de soldado, não posso, escudeiro?","roberthavewhatyoupleaseiwashmyhandsofit~oupleaseiwashmyhandsofit~39":"Robert — Tenha o que quiser. Lavo as mãos.","joanwildlyexcitedbyhersuccesscomepollysh~esscomepollyshedashesout~50":"Joan — Loucamente excitada com seu sucesso. Venha, Polly. Sai disparada.","robertshakingpoulengeyshandgoodbyeoldman~thereissomethingabouther~120":"Robert — Apertando a mão de Poulengey. Adeus, velho amigo, estou arriscando muito. Poucos outros homens o teriam feito. Mas, como você diz, há algo nela.","poulengeyyesthereissomethingabouthergood~abouthergoodbyehegoesout~52":"Poulengey — Sim: há algo nela. Adeus. Sai.","robertstillverydoubtfulwhetherhehasnotbe~owlycomesbackfromthedoor~136":"Robert, ainda muito em dúvida se não foi feito de tolo por uma fêmea maluca, e ainda por cima uma inferior social, coça a cabeça e volta devagar da porta.","thestewardrunsinwithabasket~stewardrunsinwithabasket~27":"O intendente entra correndo com uma cesta.","stewardsirsir~stewardsirsir~13":"Intendente — Senhor, senhor...","robertwhatnow~robertwhatnow~13":"Robert — O que foi agora?","stewardthehensarelayinglikemadsirfivedoz~glikemadsirfivedozeneggs~46":"Intendente — As galinhas estão pondo feito loucas, senhor. Cinco dúzias de ovos!","robertstiffensconvulsivelycrosseshimself~athlessshedidcomefromgod~120":"Robert — Enrijece-se convulsivamente; faz o sinal da cruz; e forma com os lábios pálidos as palavras. Cristo nos céus! Em voz alta, mas sem fôlego. Ela veio mesmo de Deus.","chinonintouraineanendofthethroneroominth~aboutintheworstoftempers~464":"Chinon, na Touraine. Uma extremidade da sala do trono no castelo, isolada por cortinas para formar uma antecâmara. O Arcebispo de Reims, quase com 50 anos, prelado político e bem nutrido, sem nada de eclesiástico a não ser o porte imponente, e o Lorde Camareiro, Monseigneur de la Trémouille, odre monstruoso e arrogante de homem, esperam pelo Delfim. Há uma porta na parede à direita dos dois homens. É fim de tarde de 8 de março de 1429. O Arcebispo permanece de pé com dignidade, enquanto o Camareiro, à sua esquerda, anda de um lado a outro fumegando, no pior dos humores.","latremouillewhatthedevildoesthedauphinme~standtherelikeastoneidol~124":"La Trémouille — Que diabo o Delfim pretende, nos fazendo esperar assim? Não sei como o senhor tem paciência de ficar aí parado como um ídolo de pedra.","thearchbishopyouseeiamanarchbishopandana~etokeepyouwaitingisitnot~197":"O Arcebispo — Vê, eu sou arcebispo; e um arcebispo é uma espécie de ídolo. Em todo caso, tem de aprender a ficar quieto e a suportar os tolos com paciência. Além disso, meu caro Lorde Camareiro, é privilégio real do Delfim fazê-lo esperar, não é?","latremouilledauphinbedamnedsavingyourrev~knowhowmuchmoneyheowesme~75":"La Trémouille — Delfim que se dane! com perdão de Vossa Reverência. Sabe quanto dinheiro ele me deve?","thearchbishopmuchmorethanheowesmeihaveno~endhimthatiswhatheowesme~135":"O Arcebispo — Muito mais do que me deve, não duvido, porque o senhor é homem muito mais rico. Mas suponho que ele lhe deva tudo o que o senhor podia se dar ao luxo de emprestar. É isso que ele me deve.","latremouilletwentyseventhousandthatwashi~acooltwentyseventhousand~73":"La Trémouille — Vinte e sete mil: foi a última tacada dele. Uns tranquilos vinte e sete mil!","thearchbishopwhatbecomesofitallheneverha~thatiwouldthrowtoacurate~79":"O Arcebispo — Para onde vai tudo isso? Ele nunca tem um traje que eu jogaria a um coadjutor.","latremouillehedinesonachickenorascrapofm~ppearsinthedoorwayatlast~123":"La Trémouille — Janta uma galinha ou um naco de carneiro. Toma emprestado meu último tostão; e não há nada para mostrar. Aparece um pajem na porta. Enfim!","thepagenomylorditisnothismajestymonsieur~sieurderaisisapproaching~59":"O Pajem — Não, meu senhor: não é Sua Majestade. O senhor de Rais se aproxima.","latremouilleyoungbluebeardwhyannouncehim~gbluebeardwhyannouncehim~40":"La Trémouille — O jovem Barba Azul! Por que anunciá-lo?","thepagecaptainlahireiswithhimsomethingha~methinghashappenedithink~55":"O Pajem — O capitão La Hire está com ele. Algo aconteceu, creio.","gillesderaisayoungmanof25verysmartandsel~chbishopthepagewithdraws~416":"Gilles de Rais, rapaz de 25 anos, muito elegante e senhor de si, ostentando a extravagância de uma barbicha encaracolada tingida de azul numa corte de rostos escanhoados, entra. Está decidido a ser agradável, mas lhe falta alegria natural, e não é realmente simpático. De fato, quando desafiar a Igreja, cerca de onze anos depois, será acusado de tentar extrair prazer de horríveis crueldades, e enforcado. Por ora, no entanto, não há sombra de forca sobre ele. Avança alegre até o Arcebispo. O pajem se retira.","bluebeardyourfaithfullambarchbishopgoodd~wwhathashappenedtolahire~80":"Barba Azul — Vosso fiel cordeiro, Arcebispo. Bom dia, meu senhor. Sabeis o que aconteceu a La Hire?","latremouillehehasswornhimselfintoafitper~rnhimselfintoafitperhaps~44":"La Trémouille — Praguejou-se a si mesmo até um ataque, talvez.","bluebeardnojusttheoppositefoulmouthedfra~enhewasatthepointofdeath~159":"Barba Azul — Não: justamente o contrário. Frank Boca Suja, o único homem na Touraine que o superava em pragas, ouviu de um soldado que não devia usar tal linguagem quando estava à beira da morte.","thearchbishopnoratanyotherpointbutwasfou~edfrankonthepointofdeath~70":"O Arcebispo — Nem em nenhum outro momento. Mas Frank Boca Suja estava à beira da morte?","bluebeardyeshehasjustfallenintoawellandb~isfrightenedoutofhiswits~80":"Barba Azul — Sim: acaba de cair num poço e se afogar. La Hire está assustado fora de si.","captainlahirecomesinawardogwithnocourtma~ersandpronouncedcampones~66":"O capitão La Hire entra: um cão de guerra sem maneiras de corte e com marcadas maneiras de acampamento.","bluebeardihavejustbeentellingthechamberl~bishopsaysyouarealostman~90":"Barba Azul — Estive contando ao Camareiro e ao Arcebispo. O Arcebispo diz que sois homem perdido.","lahirestridingpastbluebeardandplantinghi~anangeldressedasasoldier~169":"La Hire — Passando a passos largos por Barba Azul e plantando-se entre o Arcebispo e La Trémouille. Isto não é coisa para brincadeira. É pior do que pensávamos. Não foi um soldado, mas um anjo vestido de soldado.","thearchbishoptheconstablebluebeardexclai~aimingalltogetheranangel~62":"O Arcebispo\nO Condestável\nBarba Azul — Exclamando todos juntos. Um anjo!","lahireyesanangelshehasmadeherwayfromcham~lastedtoeternaldamnation~279":"La Hire — Sim, um anjo. Abriu caminho desde a Champagne com meia dúzia de homens pelo meio de tudo: borgonheses, goddams, desertores, ladrões e sabe Deus quem mais; e nunca toparam com viva alma exceto camponeses. Conheço um deles: de Poulengey. Diz que ela é um anjo. Se algum dia eu proferir outro palavrão, que minha alma seja fulminada à condenação eterna.","thearchbishopaverypiousbeginningcaptain~erypiousbeginningcaptain~39":"O Arcebispo — Um começo muito piedoso, capitão.","bluebeardandlatremouillelaughathimthepag~laughathimthepagereturns~48":"Barba Azul e La Trémouille riem dele. O pajem volta.","thepagehismajesty~thepagehismajesty~17":"O Pajem — Sua Majestade.","theystandperfunctorilyatcourtattentionth~retiretowardsthecurtains~703":"Põem-se de pé, de modo perfunctório, em atitude de corte. O Delfim, de 26 anos, na realidade o rei Carlos VII desde a morte do pai, mas ainda não coroado, entra pelas cortinas com um papel nas mãos. É uma pobre criatura fisicamente; e a moda corrente de se barbear rente e esconder cada fio de cabelo sob o barrete ou o toucado, tanto por mulheres como por homens, faz o pior de sua aparência. Tem olhos pequenos e estreitos, próximos um do outro, um nariz longo e pendente que cai sobre o lábio superior grosso e curto, e a expressão de um jovem cão acostumado a ser chutado, mas incorrigível e irreprimível. Mas não é nem vulgar nem estúpido; e tem um humor atrevido que lhe permite sustentar-se na conversa. Neste momento está excitado, como uma criança com um brinquedo novo. Vem à esquerda do Arcebispo. Barba Azul e La Hire retiram-se em direção às cortinas.","charlesoharchbishopdoyouknowwhatrobertde~sendingmefromvaucouleurs~77":"Carlos — Oh, Arcebispo, sabeis o que Robert de Baudricourt me manda de Vaucouleurs?","thearchbishopcontemptuouslyiamnotinteres~nterestedinthenewesttoys~58":"O Arcebispo — Com desprezo. Não me interesso pelos brinquedos mais novos.","charlesindignantlyitisntatoysulkilyhowev~ywellwithoutyourinterest~78":"Carlos — Indignado. Não é um brinquedo. Emburrado. Seja como for, posso passar muito bem sem vosso interesse.","thearchbishopyourhighnessistakingoffence~offenceveryunnecessarily~57":"O Arcebispo — Vossa Alteza se ofende sem necessidade.","charlesthankyouyouarealwaysreadywithalec~eadywithalecturearentyou~52":"Carlos — Obrigado. Estais sempre pronto com um sermão, não é?","latremouilleroughlyenoughgrumblingwhatha~blingwhathaveyougotthere~53":"La Trémouille — Rudemente. Chega de resmungar. O que tendes aí?","charleswhatisthattoyou~charleswhatisthattoyou~22":"Carlos — Que vos importa?","latremouilleitismybusinesstoknowwhatispa~hemoutsyllablebysyllable~221":"La Trémouille — É meu dever saber o que se passa entre vós e a guarnição de Vaucouleurs. Arranca o papel da mão do Delfim e começa a lê-lo com certa dificuldade, seguindo as palavras com o dedo e soletrando-as sílaba por sílaba.","charlesmortifiedyouallthinkyoucantreatme~vethebloodroyalinmyveins~129":"Carlos — Mortificado. Todos pensais que podeis me tratar como quereis porque vos devo dinheiro, e porque não sirvo para a luta. Mas tenho o sangue real nas veias.","thearchbishopeventhathasbeenquestionedyo~grandsonofcharlesthewise~101":"O Arcebispo — Até isso foi posto em dúvida, Alteza. Mal se reconhece em vós o neto de Carlos, o Sábio.","charlesiwanttohearnomoreofmygrandfatherh~iedandinsultedbyallofyou~158":"Carlos — Não quero ouvir mais nada sobre meu avô. Era tão sábio que gastou todo o estoque de sabedoria da família por cinco gerações, e me deixou o pobre tolo que sou, intimidado e insultado por todos vós.","thearchbishopcontrolyourselfsirtheseoutb~sofpetulancearenotseemly~68":"O Arcebispo — Controlai-vos, senhor. Esses acessos de irritação não são decorosos.","charlesanotherlecturethankyouwhatapityit~ndangelsdontcometoseeyou~101":"Carlos — Outro sermão! Obrigado. Que pena que, sendo vós arcebispo, santos e anjos não venham vos visitar!","thearchbishopwhatdoyoumean~earchbishopwhatdoyoumean~26":"O Arcebispo — Que quereis dizer?","charlesahaaskthatbullytherepointingtolat~repointingtolatremouille~49":"Carlos — Aha! Perguntai àquele valentão ali. Apontando La Trémouille.","latremouillefuriousholdyourtonguedoyouhe~sholdyourtonguedoyouhear~42":"La Trémouille — Furioso. Segurai a língua. Ouvistes?","charlesohihearyouneedntshoutthewholecast~eenglishandbeatthemforme~97":"Carlos — Oh, ouvi. Não precisais gritar. O castelo inteiro pode ouvir. Por que não ides gritar com os ingleses e os derrotar por mim?","latremouilleraisinghisfistyouyoung~leraisinghisfistyouyoung~34":"La Trémouille — Erguendo o punho. Seu jovem...","charlesrunningbehindthearchbishopdontyou~urhandtomeitshightreason~71":"Carlos — Correndo para trás do Arcebispo. Não levanteis a mão contra mim. É alta traição.","lahiresteadydukesteady~lahiresteadydukesteady~22":"La Hire — Calma, Duque! Calma!","thearchbishopresolutelycomecomethiswilln~atleasttrytoruleyourself~169":"O Arcebispo — Resoluto. Vamos, vamos! isto não serve. Meu lorde Camareiro; por favor! por favor! precisamos manter alguma espécie de ordem. Ao Delfim. E vós, senhor: se não podeis governar vosso reino, ao menos tentai governar a vós mesmo.","charlesanotherlecturethankyou~esanotherlecturethankyou~29":"Carlos — Outro sermão! Obrigado.","latremouillehandingthepapertothearchbish~antdistinguishtheletters~131":"La Trémouille — Entregando o papel ao Arcebispo. Aqui: lede a maldita coisa para mim. Ela me mandou o sangue à cabeça: não distingo as letras.","charlescomingbackandpeeringroundlatremou~ifyoulikeicanreadyouknow~98":"Carlos — Voltando e espiando por cima do ombro esquerdo de La Trémouille. Eu leio para vós, se quiserdes. Eu sei ler, sabeis.","latremouillewithintensecontemptnotatalls~anyoumakeitoutarchbishop~111":"La Trémouille — Com intenso desprezo, nada ferido pela alfinetada. Sim: ler é quase tudo para o que prestais. Consegue decifrar, Arcebispo?","thearchbishopishouldhaveexpectedmorecomm~mecrackedcountrylasshere~101":"O Arcebispo — Eu teria esperado mais bom senso de De Baudricourt. Ele está mandando para cá uma camponesa desmiolada...","charlesinterruptingnoheissendingasaintan~etweenbluebeardandlahire~185":"Carlos — Interrompendo. Não: ele manda uma santa: um anjo. E ela vem a mim: a mim, o rei, e não a vós, Arcebispo, santo como sois. Ela reconhece o sangue real, se vós não reconheceis. Pavoneia-se até as cortinas, entre Barba Azul e La Hire.","thearchbishopyoucannotbeallowedtoseethis~lowedtoseethiscrazywench~50":"O Arcebispo — Não se pode permitir que vejais essa moça doida.","charlesturningbutiamthekingandiwill~ingbutiamthekingandiwill~35":"Carlos — Voltando-se. Mas eu sou o rei; e vou vê-la.","latremouillebrutallythenshecannotbeallow~nnotbeallowedtoseeyounow~53":"La Trémouille — Brutalmente. Então ela não pode ser admitida à vossa presença. Pronto!","charlesitellyouiwilliamgoingtoputmyfootd~liamgoingtoputmyfootdown~43":"Carlos — Digo-vos que vou. Vou bater o pé...","bluebeardlaughingathimnaughtywhatwouldyo~ldyourwisegrandfathersay~60":"Barba Azul — Rindo dele. Malcriado! Que diria vosso sábio avô?","charlesthatjustshowsyourignorancebluebea~ousayiwillhavemysainttoo~251":"Carlos — Isso só mostra vossa ignorância, Barba Azul. Meu avô tinha uma santa que flutuava no ar quando rezava, e lhe contava tudo o que ele queria saber. Meu pobre pai tinha duas santas, Marie de Maillé e a Gasca de Avignon. Está em nossa família; e não me importa o que digais: terei minha santa também.","thearchbishopthiscreatureisnotasaintshei~ttedtoyourhighnessscourt~207":"O Arcebispo — Esta criatura não é santa. Nem sequer é mulher respeitável. Não veste roupas de mulher. Veste-se como soldado e cavalga pelo país com soldados. Supondes que tal pessoa possa ser admitida à corte de Vossa Alteza?","lahirestopgoingtothearchbishopdidyousaya~agirlinarmorlikeasoldier~63":"La Hire — Esperai. Indo ao Arcebispo. Dissestes uma moça de armadura, como soldado?","thearchbishopsodebaudricourtdescribesher~ebaudricourtdescribesher~40":"O Arcebispo — Assim De Baudricourt a descreve.","lahirebutbyallthedevilsinhellohgodforgiv~thedfrankdeadforswearing~139":"La Hire — Mas por todos os diabos do inferno... Oh, Deus me perdoe, que estou dizendo?... por Nossa Senhora e todos os santos, deve ser o anjo que feriu de morte Frank Boca Suja por praguejar.","charlestriumphantlyyouseeamiracle~iumphantlyyouseeamiracle~33":"Carlos — Triunfante. Vedes! Um milagre.","lahireshemaystrikethelotofusdeadifwecros~becarefulwhatyouaredoing~92":"La Hire — Ela pode ferir de morte a todos nós se a contrariarmos. Pelo amor do Céu, Arcebispo, tende cuidado com o que fazeis.","thearchbishopseverelyrubbishnobodyhasbee~ndrownedamerecoincidence~158":"O Arcebispo — Severo. Tolice! Ninguém foi ferido de morte. Um canalha bêbado, repreendido cem vezes por praguejar, caiu num poço e se afogou. Mera coincidência.","lahireidonotknowwhatacoincidenceisidokno~hetoldhimhewasgoingtodie~89":"La Hire — Não sei o que é uma coincidência. Sei que o homem está morto, e que ela lhe disse que ia morrer.","thearchbishopweareallgoingtodiecaptain~eareallgoingtodiecaptain~38":"O Arcebispo — Todos nós vamos morrer, capitão.","lahirecrossinghimselfihopenothebacksouto~acksoutoftheconversation~56":"La Hire — Persignando-se. Espero que não. Recua, saindo da conversa.","bluebeardwecaneasilyfindoutwhethersheisa~ewhethershewillfindmeout~126":"Barba Azul — Podemos descobrir facilmente se ela é anjo ou não. Combinemos que, quando ela vier, eu serei o Delfim, e vejamos se ela me descobre.","charlesyesiagreetothatifshecannotfindthe~llhavenothingtodowithher~77":"Carlos — Sim: concordo. Se ela não souber achar o sangue real, não quero nada com ela.","thearchbishopitisforthechurchtomakesaint~hegirlshallnotbeadmitted~141":"O Arcebispo — Cabe à Igreja fazer santos: que De Baudricourt cuide da própria vida e não ouse usurpar a função de seu sacerdote. Digo que a moça não será admitida.","bluebeardbutarchbishop~bluebeardbutarchbishop~22":"Barba Azul — Mas, Arcebispo...","thearchbishopsternlyispeakinthechurchsna~phindoyoudaresaysheshall~74":"O Arcebispo — Severamente. Falo em nome da Igreja. Ao Delfim. Ousais dizer que ela será?","charlesintimidatedbutsulkyohifyoumakeita~nsandbeattheenglishforus~192":"Carlos — Intimidado mas emburrado. Oh, se fazeis disso questão de excomunhão, nada mais tenho a dizer, claro. Mas não lestes o fim da carta. De Baudricourt diz que ela levantará o cerco de Orléans e derrotará os ingleses por nós.","latremouillerot~latremouillerot~15":"La Trémouille — Bobagem!","charleswellwillyousaveorleansforuswithal~foruswithallyourbullying~53":"Carlos — Pois bem, salvareis Orléans para nós, com toda a vossa valentia?","latremouillesavagelydonotthrowthatinmyfa~llbuticannotbeeverywhere~123":"La Trémouille — Ferozmente. Não me atireis isso à cara outra vez: ouvistes? Combati mais do que jamais combatestes ou combatereis. Mas não posso estar em toda parte.","thedauphinwellthatssomething~auphinwellthatssomething~28":"O Delfim — Bem, já é alguma coisa.","bluebeardcomingbetweenthearchbishopandch~ylasscandowhathecannotdo~241":"Barba Azul — Interpondo-se entre o Arcebispo e Carlos. Tendes Jack Dunois à frente de vossas tropas em Orléans: o valente Dunois, o belo Dunois, o maravilhoso e invencível Dunois, o queridinho de todas as damas, o lindo bastardo. É provável que a camponesa possa fazer o que ele não pode?","charleswhydoesntheraisethesiegethen~oesntheraisethesiegethen~35":"Carlos — Por que ele não levanta o cerco, então?","lahirethewindisagainsthim~ahirethewindisagainsthim~25":"La Hire — O vento está contra ele.","bluebeardhowcanthewindhurthimatorleansit~leansitisnotonthechannel~57":"Barba Azul — Como pode o vento prejudicá-lo em Orléans? Não fica no Canal.","lahireitisontheriverloireandtheenglishho~hwhatharmisthereintrying~425":"La Hire — Fica no rio Loire; e os ingleses ocupam a cabeça da ponte. Ele precisa embarcar seus homens através do rio e rio acima, se quiser atacá-los pela retaguarda. Pois bem, não pode, porque sopra um vento dos diabos no sentido contrário. Está cansado de pagar aos padres para rezarem por um vento oeste. O que ele precisa é de um milagre. Dizeis-me que o que a moça fez a Frank Boca Suja não foi milagre. Não importa: acabou com Frank. Se ela mudar o vento para Dunois, isso talvez também não seja milagre; mas pode acabar com os ingleses. Que mal há em tentar?","thearchbishopwhohasreadtheendoftheletter~extraordinarilyimpressed~117":"O Arcebispo — Que leu o fim da carta e ficou mais pensativo. É verdade que De Baudricourt parece extraordinariamente impressionado.","lahiredebaudricourtisablazingassbutheisa~tofthearmywillthinksotoo~113":"La Hire — De Baudricourt é um asno rematado; mas é soldado; e se ele pensa que ela pode derrotar os ingleses, o resto do exército também pensará.","latremouilletothearchbishopwhoishesitati~utsomefreshspunkintothem~143":"La Trémouille — Ao Arcebispo, que hesita. Oh, deixai que façam à sua maneira. Os homens de Dunois entregarão a cidade apesar dele se alguém não lhes puser um pouco de brio novo.","thearchbishopthechurchmustexaminethegirl~esitletherattendthecourt~128":"O Arcebispo — A Igreja deve examinar a moça antes que se faça algo decisivo a respeito dela. Contudo, uma vez que Sua Alteza o deseja, que ela compareça à Corte.","lahireiwillfindherandtellherhegoesout~ndherandtellherhegoesout~37":"La Hire — Vou encontrá-la e dizer-lhe. Sai.","charlescomewithmebluebeardandletusarrang~oesoutthroughthecurtains~114":"Carlos — Vinde comigo, Barba Azul; e arranjemos de modo que ela não saiba quem sou. Fingireis ser eu. Sai pelas cortinas.","bluebeardpretendtobethatthingholymichael~chaelhefollowsthedauphin~59":"Barba Azul — Fingir ser aquela coisa! São Miguel! Segue o Delfim.","latremouilleiwonderwillshepickhimout~iwonderwillshepickhimout~36":"La Trémouille — Será que ela o escolherá!","thearchbishopofcourseshewill~rchbishopofcourseshewill~28":"O Arcebispo — Claro que sim.","latremouillewhyhowisshetoknow~mouillewhyhowisshetoknow~29":"La Trémouille — Por quê? Como saberá?","thearchbishopshewillknowwhateverybodyinc~ebluebeardisgillesderais~157":"O Arcebispo — Saberá o que todos em Chinon sabem: que o Delfim é a figura de aspecto mais mesquinho e pior vestida da Corte, e que o homem de barba azul é Gilles de Rais.","latremouilleineverthoughtofthat~uilleineverthoughtofthat~31":"La Trémouille — Nunca pensei nisso.","thearchbishopyouarenotsoaccustomedtomira~amitispartofmyprofession~71":"O Arcebispo — O senhor não está tão acostumado a milagres como eu. Faz parte de minha profissão.","latremouillepuzzledandalittlescandalized~twouldnotbeamiracleatall~70":"La Trémouille — Perplexo e um pouco escandalizado. Mas isso não seria milagre algum.","thearchbishopcalmlywhynot~hearchbishopcalmlywhynot~25":"O Arcebispo — Calmamente. Por que não?","latremouillewellcomewhatisamiracle~lewellcomewhatisamiracle~34":"La Trémouille — Bem, vejamos; o que é um milagre?","thearchbishopamiraclemyfriendisaneventwh~faiththeyaretruemiracles~235":"O Arcebispo — Um milagre, meu amigo, é um acontecimento que cria fé. Essa é a finalidade e a natureza dos milagres. Podem parecer muito maravilhosos para quem os presencia, e muito simples para quem os realiza. Isso não importa: se confirmam ou criam fé, são verdadeiros milagres.","latremouilleevenwhentheyarefraudsdoyoume~entheyarefraudsdoyoumean~42":"La Trémouille — Mesmo quando são fraudes, quer dizer?","thearchbishopfraudsdeceiveaneventwhichcr~itisnotafraudbutamiracle~97":"O Arcebispo — Fraudes enganam. Um acontecimento que cria fé não engana: portanto não é fraude, mas milagre.","latremouillescratchinghisneckinhisperple~ntunderstandthesematters~156":"La Trémouille — Coçando o pescoço em sua perplexidade. Bem, suponho que, sendo o senhor arcebispo, deve estar certo. Parece-me um tanto suspeito. Mas não sou homem de igreja, e não entendo esses assuntos.","thearchbishopyouarenotachurchmanbutyouar~seemstothemtobehappening~198":"O Arcebispo — O senhor não é homem de igreja; mas é diplomata e soldado. Poderia fazer nossos cidadãos pagarem impostos de guerra, ou nossos soldados sacrificarem a vida, se soubessem o que realmente está acontecendo, em vez do que lhes parece estar acontecendo?","latremouillenobysaintdennisthefatwouldbe~beinthefirebeforesundown~62":"La Trémouille — Não, por São Dinis: a coisa ia ferver antes do pôr do sol.","thearchbishopwoulditnotbequiteeasytotell~teeasytotellthemthetruth~52":"O Arcebispo — Não seria bastante fácil dizer-lhes a verdade?","latremouillemanalivetheywouldntbelieveit~livetheywouldntbelieveit~40":"La Trémouille — Homem de Deus, não acreditariam.","thearchbishopjustsowellthechurchhastorul~ourishtheirfaithbypoetry~163":"O Arcebispo — Exatamente. Pois bem, a Igreja tem de governar os homens para o bem de suas almas, como o senhor tem de governá-los para o bem de seus corpos. Para isso, a Igreja deve fazer como o senhor: nutrir a fé deles com poesia.","latremouillepoetryishouldcallithumbug~oetryishouldcallithumbug~37":"La Trémouille — Poesia! Eu chamaria de embuste.","thearchbishopyouwouldbewrongmyfriendpara~edhimoutsoperhapswillyou~615":"O Arcebispo — Estaria enganado, meu amigo. Parábolas não são mentiras porque descrevem acontecimentos que jamais ocorreram. Milagres não são fraudes porque muitas vezes — não digo sempre — são artifícios muito simples e inocentes pelos quais o sacerdote fortalece a fé de seu rebanho. Quando esta moça escolher o Delfim entre os cortesãos, não será um milagre para mim, porque saberei como foi feito, e minha fé não aumentará. Mas quanto aos outros, se sentirem o arrepio do sobrenatural, e esquecerem seu barro pecador num súbito sentido da glória de Deus, será um milagre, e abençoado. E verá que a própria moça será mais afetada do que qualquer outro. Esquecerá como realmente o escolheu. Talvez o senhor também.","latremouillewelliwishiwerecleverenoughto~oseeitmiracleornomiracle~171":"La Trémouille — Bem, quisera ser esperto o bastante para saber quanto do senhor é arcebispo de Deus e quanto é a mais astuta raposa da Touraine. Vamos, ou perderemos a diversão; e quero ver, milagre ou não milagre.","thearchbishopdetaininghimamomentdonotthi~hesaintsandtheirmiracles~254":"O Arcebispo — Detendo-o um momento. Não pense que sou amante dos caminhos tortos. Um novo espírito se levanta nos homens: estamos na aurora de uma época mais ampla. Se eu fosse um simples monge, e não tivesse de governar homens, buscaria a paz de meu espírito em Aristóteles e Pitágoras antes que nos santos e seus milagres.","latremouilleandwhothedeucewaspythagoras~whothedeucewaspythagoras~39":"La Trémouille — E quem diabos foi Pitágoras?","thearchbishopasagewhoheldthattheearthisr~ndthatitmovesroundthesun~69":"O Arcebispo — Um sábio que sustentava que a terra é redonda e gira em torno do sol.","latremouillewhatanutterfoolcouldntheuseh~rfoolcouldntheusehiseyes~46":"La Trémouille — Que completo tolo! Não podia usar os olhos?","theygoouttogetherthroughthecurtainswhich~osebybehindthearchbishop~659":"Saem juntos pelas cortinas, que logo são puxadas, revelando toda a profundidade da sala do trono com a Corte reunida. À direita há duas Cadeiras de Estado sobre um estrado. Barba Azul está de pé teatralmente no estrado, fazendo de rei, e, como os cortesãos, desfruta a brincadeira de modo bastante evidente. Há um arco com cortina na parede atrás do estrado; mas a porta principal, guardada por homens de armas, fica do outro lado da sala; e um caminho desimpedido é mantido e ladeado pelos cortesãos. Carlos está nesse caminho, no meio da sala. La Hire está à sua direita. O Arcebispo, à esquerda, tomou seu lugar junto ao estrado: La Trémouille do outro lado dele. A Duquesa de la Trémouille, fingindo ser a Rainha, senta-se na cadeira da Consorte, com um grupo de damas de companhia por perto, atrás do Arcebispo.","thechatterofthecourtiersmakessuchanoiset~aranceofthepageatthedoor~87":"A tagarelice dos cortesãos faz tanto barulho que ninguém nota a aparição do pajem à porta.","thepagethedukeofnobodylistensthedukeofth~sjoanthemaidtohismajesty~296":"O Pajem — O Duque de... Ninguém escuta. O Duque de... A tagarelice continua. Indignado por não conseguir ser ouvido, arranca a alabarda do homem de armas mais próximo e bate com ela no chão. A tagarelice cessa; e todos o olham em silêncio. Atenção! Devolve a alabarda ao homem de armas. O Duque de Vendôme apresenta a Sua Majestade Joana, a Donzela.","charlesputtinghisfingeronhislipsshhehide~eringouttoseewhathappens~91":"Carlos — Pondo o dedo nos lábios. Psiu! Esconde-se atrás do cortesão mais próximo, espiando para ver o que acontece.","bluebeardmajesticallyletherapproachtheth~yletherapproachthethrone~44":"Barba Azul — Majestosamente. Que ela se aproxime do trono.","joandressedasasoldierwithherhairbobbedan~oundeagerlyforthedauphin~169":"Joana, vestida de soldado, com os cabelos cortados curtos e caindo espessos em torno do rosto, é conduzida por um nobre tímido e mudo, de quem se desprende para parar e olhar ansiosa em volta à procura do Delfim.","theduchesstothenearestladyinwaitingmydea~dyinwaitingmydearherhair~48":"A Duquesa — À dama de companhia mais próxima. Minha querida! O cabelo dela!","alltheladiesexplodeinuncontrollablelaugh~inuncontrollablelaughter~43":"Todas as damas explodem em riso incontrolável.","bluebeardtryingnottolaughandwavinghishan~rimentsshsshladiesladies~88":"Barba Azul — Tentando não rir e agitando a mão em desaprovação à alegria delas. Psiu, psiu! Senhoras! Senhoras!!","joannotatallembarrassediwearitlikethisbe~amasoldierwherebedauphin~70":"Joana — Nem um pouco embaraçada. Uso assim porque sou soldado. Onde tá o Delfim?","atitterrunsthroughthecourtasshewalkstoth~courtasshewalkstothedais~45":"Um riso abafado percorre a Corte enquanto ela caminha até o estrado.","bluebeardcondescendinglyyouareintheprese~nthepresenceofthedauphin~55":"Barba Azul — Condescendente. Estás na presença do Delfim.","joanlooksathimscepticallyforamomentscann~hingherfundawnsinherface~111":"Joana olha-o com ceticismo por um momento, examinando-o de alto a baixo para ter certeza. Silêncio de morte, todos a observam. A graça desponta em seu rosto.","joancoombluebeardthoucanstnotfoolmewhere~tnotfoolmewherebedauphin~49":"Joana — Vamo, Barba Azul! Tu não me enganas. Onde tá o Delfim?","aroaroflaughterbreaksoutasgilleswithages~ddragsoutcharlesbythearm~221":"Explode uma gargalhada quando Gilles, com um gesto de rendição, junta-se ao riso e salta do estrado ao lado de La Trémouille. Joana, também num largo sorriso, volta-se, percorrendo a fila de cortesãos, e logo dá um mergulho e arrasta Carlos pelo braço.","joanreleasinghimandbobbinghimalittlecurt~ekingsoffrancearecrowned~193":"Joana — Soltando-o e fazendo-lhe uma pequena reverência. Gentil Delfinzinho, fui enviada a ti para expulsar os ingleses de Orléans e da França, e para te coroar rei na catedral de Reims, onde são coroados todos os verdadeiros reis da França.","charlestriumphanttothecourtyouseeallofyo~eisheisstandingbehindher~198":"Carlos — Triunfante, para a Corte. Vedes, todos: ela reconheceu o sangue real. Quem ousa dizer agora que não sou filho de meu pai? A Joana. Mas se quereis que eu seja coroado em Reims deveis falar com o Arcebispo, não comigo. Ali está ele! Está de pé atrás de vós.","joanturningquicklyoverwhelmedwithemotion~ivemeyourblessingwontyou~246":"Joana — Voltando-se depressa, tomada de emoção. Oh, meu senhor! Cai de joelhos diante dele, a cabeça baixa, sem ousar erguer os olhos. Meu senhor: sou só uma pobre moça do campo; e estais cheio da bem-aventurança e da glória do próprio Deus; mas haveis de me tocar com as mãos e dar-me a vossa bênção, não é?","bluebeardwhisperingtolatremouilletheoldf~emouilletheoldfoxblushes~49":"Barba Azul — Cochichando a La Trémouille. A velha raposa enrubesce.","latremouilleanothermiracle~tremouilleanothermiracle~26":"La Trémouille — Outro milagre!","thearchbishoptouchedputtinghishandonherh~youareinlovewithreligion~72":"O Arcebispo — Comovido, pondo a mão na cabeça dela. Criança: estás apaixonada pela religião.","joanstartledlookingupathimamiineverthoug~ofthatisthereanyharminit~66":"Joana — Sobressaltada: erguendo os olhos para ele. Estou? Nunca pensei nisso. Há mal nisso?","thearchbishopthereisnoharminitmychildbut~tmychildbutthereisdanger~53":"O Arcebispo — Não há mal nisso, minha filha. Mas há perigo.","joanrisingwithasunflushofrecklesshappine~erfulthingtobearchbishop~179":"Joana — Levantando-se, com um rubor de sol de felicidade temerária a irradiar-lhe o rosto. Há sempre perigo, exceto no céu. Oh, meu senhor, destes-me tanta força, tanta coragem. Deve ser coisa maravilhosa ser Arcebispo.","thecourtsmilesbroadlyeventittersalittle~roadlyeventittersalittle~39":"A Corte sorri largamente: chega até a rir baixinho.","thearchbishopdrawinghimselfupsensitively~butyourmirthisadeadlysin~131":"O Arcebispo — Empertigando-se, ofendido. Senhores: vossa leviandade é repreendida pela fé desta donzela. Sou, Deus me ajude, de todo indigno; mas vossa alegria é pecado mortal.","theirfacesfalldeadsilence~heirfacesfalldeadsilence~25":"Os rostos se fecham. Silêncio de morte.","bluebeardmylordwewerelaughingathernotaty~erelaughingathernotatyou~42":"Barba Azul — Meu senhor: ríamos dela, não de vós.","thearchbishopwhatnotatmyunworthinessbuta~rshouldbedrownedinhissin~119":"O Arcebispo — O quê? Não de minha indignidade, mas da fé dela! Gilles de Rais: esta donzela profetizou que o blasfemo seria afogado em seu pecado...","joandistressedno~joandistressedno~16":"Joana — Aflita. Não!","thearchbishopsilencingherbyagestureiprop~whentolaughandwhentopray~112":"O Arcebispo — Silenciando-a com um gesto. Profetizo agora que sereis enforcado no vosso, se não aprenderdes quando rir e quando rezar.","bluebeardmylordistandrebukediamsorryican~behangedforasheepasalamb~190":"Barba Azul — Meu senhor: aceito a repreensão. Sinto muito: não posso dizer mais. Mas se profetizais que serei enforcado, nunca poderei resistir à tentação, porque estarei sempre dizendo a mim mesmo que tanto faz ser enforcado por um carneiro como por um cordeiro.","thecourtierstakeheartatthisthereismoreti~thisthereismoretittering~47":"Os cortesãos tomam coragem com isso. Há mais risos abafados.","joanscandalizedyouareanidlefellowbluebea~ncetoanswerthearchbishop~87":"Joana — Escandalizada. Tu és um vadio, Barba Azul; e tens grande atrevimento em responder ao Arcebispo.","lahirewithahugechucklewellsaidlasswellsa~cklewellsaidlasswellsaid~42":"La Hire — Com uma enorme risada. Bem dito, moça! Bem dito!","joanimpatientlytothearchbishopohmylordwi~ayspeaktothedauphinalone~103":"Joana — Impaciente, ao Arcebispo. Oh, meu senhor, mandareis embora todos esses tolos para que eu possa falar a sós com o Delfim?","lahiregoodhumoredlyicantakeahinthesalute~turnsonhisheelandgoesout~65":"La Hire — De bom humor. Sei captar uma deixa. Saúda; gira nos calcanhares; e sai.","thearchbishopcomegentlementhemaidcomeswi~sblessingandmustbeobeyed~69":"O Arcebispo — Vamos, senhores. A Donzela vem com a bênção de Deus, e deve ser obedecida.","thecourtierswithdrawsomethroughthearchot~directlyintheduchesssway~319":"Os cortesãos se retiram, alguns pelo arco, outros pelo lado oposto. O Arcebispo marcha até a porta, seguido pela Duquesa e por La Trémouille. Quando o Arcebispo passa por Joana, ela cai de joelhos e beija fervorosamente a barra de sua veste. Ele sacode a cabeça em instintiva reprovação; recolhe a veste das mãos dela; e sai. Ela fica ajoelhada exatamente no caminho da Duquesa.","theduchesscoldlywillyouallowmetopassplea~llyouallowmetopassplease~42":"A Duquesa — Friamente. Quer ter a bondade de me dar passagem?","joanhastilyrisingandstandingbackbegpardo~backbegpardonmaamiamsure~52":"Joana — Levantando-se depressa e afastando-se. Perdão, senhora, com certeza.","theduchesspassesonjoanstaresafterherthen~thenwhisperstothedauphin~60":"A Duquesa passa. Joana a segue com os olhos; depois cochicha ao Delfim.","joanbethatqueen~joanbethatqueen~15":"Joana — Aquela é a Rainha?","charlesnoshethinkssheis~charlesnoshethinkssheis~23":"Carlos — Não. Ela pensa que é.","joanagainstaringaftertheduchessoooooohhe~isnotwhollycomplimentary~126":"Joana — Seguindo de novo a Duquesa com o olhar. Ooo‑ooo‑ooh! Seu assombro reverente diante da figura da dama magnificamente vestida não é de todo lisonjeiro.","latremouilleverysurlyilltroubleyourhighn~theothershavealreadygone~93":"La Trémouille — Muito carrancudo. Rogo a Vossa Alteza que não zombe de minha esposa. Sai. Os outros já se foram.","joantothedauphinwhobeoldgruffandgrum~phinwhobeoldgruffandgrum~36":"Joana — Ao Delfim. Quem é o velho Rabugento-e-Ranzinza?","charlesheisthedukedelatremouille~eisthedukedelatremouille~32":"Carlos — É o Duque de la Trémouille.","joanwhatbehisjob~joanwhatbehisjob~16":"Joana — Qual é o ofício dele?","charleshepretendstocommandthearmyandwhen~endicancareforhekillshim~77":"Carlos — Finge comandar o exército. E sempre que encontro um amigo de quem gosto, ele o mata.","joanwhydostlethim~joanwhydostlethim~17":"Joana — Por que deixas?","charlespetulantlymovingtothethronesideof~ebulliesmetheyallbullyme~117":"Carlos — Irritado, indo para o lado do trono da sala para escapar do campo magnético dela. Como posso impedir? Ele me intimida. Todos me intimidam.","joanartafraid~joanartafraid~13":"Joana — Tens medo?","charlesyesiamafraiditsnousepreachingtome~atwayandthereisanendofit~563":"Carlos — Sim: tenho medo. De nada adianta me passar sermão. Está muito bem para esses homens grandes com suas armaduras pesadas demais para mim, e suas espadas que mal consigo levantar, e seus músculos e seus gritos e seus maus humores. Eles gostam de lutar: a maior parte faz papel de tolo o tempo todo em que não está lutando; mas eu sou quieto e sensato; e não quero matar gente: só quero ser deixado em paz para me divertir à minha maneira. Nunca pedi para ser rei: empurraram-me isso. De modo que se vais dizer “Filho de São Luís: cinge a espada de teus ancestrais e conduz-nos à vitória”, podes poupar o fôlego para esfriar o mingau; porque não posso fazê-lo. Não sou feito assim; e ponto final.","joantrenchantandmasterfulblethersweareal~ishallputcourageintothee~84":"Joana — Cortante e imperiosa. Bobagem! Todos somos assim no começo. Vou pôr coragem em ti.","charlesbutidontwanttohavecourageputintom~loffightingbutletmealone~192":"Carlos — Mas não quero que ponham coragem em mim. Quero dormir numa cama confortável, e não viver em contínuo terror de ser morto ou ferido. Ponde coragem nos outros, e deixai que se fartem de lutar; mas deixai-me em paz.","joanitsnousecharliethoumustfacewhatgodpu~ihavelookedforwardtothat~165":"Joana — Não adianta, Carlinhos: tens de enfrentar o que Deus põe sobre ti. Se falhares em te fazer rei, serás um mendigo: para que mais prestas? Vamos! Deixa-me ver-te sentado no trono. Esperei por isso.","charleswhatisthegoodofsittingonthethrone~okyourfillatthepoordevil~156":"Carlos — Que adianta sentar no trono quando os outros dão todas as ordens? Seja como for! Senta-se no trono, figura lastimável. Eis o rei para vós! Fartai-vos de olhar o pobre-diabo.","joanthourtnotkingyetladthourtbutdauphinb~eenlookaftertheeproperly~334":"Joana — Tu ainda não és rei, rapaz: és só Delfim. Não te deixes levar pelos que te cercam. Enfeitar-se não enche cabeça oca. Conheço o povo: o povo de verdade, que faz o teu pão; e digo-te que não contam homem algum como rei da França até que o óleo santo seja derramado em seu cabelo, e ele consagrado e coroado na catedral de Reims. E tu precisas de roupas novas, Carlinhos. Por que a Rainha não cuida de ti como se deve?","charlesweretoopoorshewantsallthemoneywec~elfishouldlookuglyanyhow~150":"Carlos — Somos pobres demais. Ela quer todo o dinheiro que podemos poupar para pôr nas próprias costas. Além disso, gosto de vê-la lindamente vestida; e não me importo com o que visto; ficaria feio de qualquer jeito.","joanthereissomegoodintheecharliebutitisn~ebutitisnotyetakingsgood~55":"Joana — Há algum bem em ti, Carlinhos; mas ainda não é bem de rei.","charlesweshallseeiamnotsuchafoolasilooki~atfightingthanatthinking~269":"Carlos — Veremos. Não sou tão tolo quanto pareço. Tenho os olhos abertos; e posso vos dizer que um bom tratado vale dez boas lutas. Esses sujeitos lutadores perdem nos tratados tudo o que ganham nas lutas. Se ao menos pudermos ter um tratado, os ingleses certamente levarão a pior, porque são melhores em lutar do que em pensar.","joaniftheenglishwinitistheythatwillmaket~rayforitwithbothhandstoo~198":"Joana — Se os ingleses vencerem, serão eles que farão o tratado; e então Deus ajude a pobre França! Tens de lutar, Carlinhos, queiras ou não. Irei primeiro para te animar. Devemos tomar a coragem com as duas mãos: sim, e rezar por ela também com as duas mãos.","charlesdescendingfromhisthroneandagaincr~vetodoitatthepropertimes~195":"Carlos — Descendo do trono e atravessando de novo a sala para escapar da urgência dominadora dela. Oh, parai de falar de Deus e de rezar. Não suporto gente que vive rezando. Já não basta ter de fazê-lo nas horas devidas?","joanpityinghimthoupoorchildthouhastnever~eachtheefromthebeginning~85":"Joana — Compadecida dele. Tu, pobre criança, nunca rezaste na vida. Devo ensinar-te desde o começo.","charlesiamnotachildiamagrownmanandafathe~diwillnotbetaughtanymore~67":"Carlos — Não sou criança: sou homem feito e pai; e não serei mais ensinado.","joanayeyouhavealittlesonhethatwillbeloui~iewouldyounotfightforhim~84":"Joana — Sim, tens um filhinho. Aquele que será Luís XI quando morreres. Não lutarias por ele?","charlesnoahorridboyhehatesmehehatesevery~businessandletmemindmine~281":"Carlos — Não: um menino horrível. Ele me odeia. Odeia todo mundo, bichinho egoísta! Não quero ser incomodado com crianças. Não quero ser pai; e não quero ser filho: especialmente filho de São Luís. Não quero ser nenhuma dessas coisas finas de que tendes todos a cabeça cheia: quero ser apenas o que sou. Por que não cuidais da vossa vida e me deixais cuidar da minha?","joanagaincontemptuousmindingyourownbusin~rtbreakwiththeterrorofit~326":"Joana — De novo desdenhosa. Cuidar da própria vida é como cuidar do próprio corpo: é o caminho mais curto para se fazer adoecer. Qual é a minha vida? Ajudar mamãe em casa. Qual é a tua? Mimar cachorrinhos de colo e chupar pirulitos. Chamo isso de imundície. Digo-te que é o negócio de Deus que estamos aqui para fazer: não o nosso. Tenho uma mensagem de Deus para ti; e tens de ouvi-la, ainda que teu coração se parta de terror.","charlesidontwantamessagebutcanyoutellmea~goldoranythingofthatsort~107":"Carlos — Não quero mensagem; mas podeis me dizer algum segredo? Fazeis alguma cura? Podeis transformar chumbo em ouro, ou algo desse gênero?","joanicanturntheeintoakinginrheimscathedr~willtakesomedoingitseems~87":"Joana — Posso transformar-te em rei, na catedral de Reims; e esse é um milagre que vai dar trabalho, ao que parece.","charlesifwegotorheimsandhaveacoronationa~fordthemiamallrightasiam~93":"Carlos — Se formos a Reims e houver uma coroação, Ana vai querer vestidos novos. Não podemos pagá-los. Estou bem como estou.","joanasyouareandwhatisthatlessthanmyfathe~ncetillthoubeconsecrated~118":"Joana — Como estás! E que é isso? Menos que o mais pobre pastor de meu pai. Tu não és dono legítimo de tua própria terra da França até seres consagrado.","charlesbutishallnotbelawfulownerofmyownl~iowemoneyeventobluebeard~161":"Carlos — Mas não serei dono legítimo de minha terra de qualquer modo. A consagração pagará minhas hipotecas? Empenhei meu último acre ao Arcebispo e àquele gordo valentão. Devo dinheiro até a Barba Azul.","joanearnestlycharlieicomefromthelandandh~betraymeandhimthatsentme~608":"Joana — Com fervor. Carlinhos: venho da terra, e ganhei minha força trabalhando na terra; e digo-te que a terra é tua para a governares com justiça e manteres nela a paz de Deus, e não para a empenhares na casa de penhores como uma mulher bêbada empenha a roupa dos filhos. E venho de Deus para te dizer que te ajoelhes na catedral e dês solenemente teu reino a Ele para todo o sempre, e te tornes o maior rei do mundo como Seu mordomo e Seu feitor, Seu soldado e Seu servo. O próprio barro da França se tornará santo: seus soldados serão soldados de Deus: os duques rebeldes serão rebeldes contra Deus: os ingleses cairão de joelhos e te rogarão que os deixes voltar em paz a seus lares legítimos. Serás um pobre Judasinho, e trairás a mim e Aquele que me enviou?","charlestemptedatlastohifionlydare~mptedatlastohifionlydare~33":"Carlos — Tentado, por fim. Oh, se eu ao menos ousasse!","joanishalldaredareanddareagainingodsname~odsnameartfororagainstme~57":"Joana — Eu ousarei, ousarei e tornarei a ousar, em nome de Deus! Estás comigo ou contra mim?","charlesexcitedillriskitiwarnyouishantbea~nceyoulittlebeastwillyou~399":"Carlos — Excitado. Vou arriscar. Aviso-vos que não vou conseguir sustentar; mas vou arriscar. Vereis. Correndo à porta principal e gritando. Olá! Voltem todos. A Joana, enquanto corre de volta ao arco oposto. Cuidai de ficar ao meu lado e não deixar que me intimidem. Pelo arco. Venham, vocês: a Corte inteira. Senta-se na cadeira real enquanto todos se apressam a ocupar os lugares de antes, tagarelando e admirando-se. Agora estou nessa; mas não importa: lá vai! Ao pajem. Peça silêncio, seu bichinho, pode ser?","thepagesnatchingahalberdasbeforeandthump~lyoubesilenttheresilence~138":"O Pajem — Arrebatando uma alabarda como antes e batendo repetidamente com ela. Silêncio para Sua Majestade o Rei. O Rei fala. Peremptório. Vão ficar calados aí? Silêncio.","charlesrisingihavegiventhecommandofthear~hithedescendsfromthedais~101":"Carlos — Levantando-se. Dei o comando do exército à Donzela. A Donzela fará dele o que quiser. Desce do estrado.","generalamazementlahiredelightedslapshiss~highpiecewithhisgauntlet~69":"Assombro geral. La Hire, encantado, bate na coxa de aço com a manopla.","latremouilleturningthreateninglytowardsc~hatisthisicommandthearmy~71":"La Trémouille — Voltando-se ameaçador para Carlos. O que é isto? Eu comando o exército.","joanquicklyputsherhandoncharlessshoulder~asheinstinctivelyrecoils~64":"Joana — Põe depressa a mão no ombro de Carlos, que instintivamente recua. !","charleswithagrotesqueeffortculminatingin~ersinthechamberlainsface~96":"Carlos — Com um esforço grotesco, culminando num gesto exagerado, estala os dedos na cara do Camareiro. !","joanthourtansweredoldgruffandgrumsuddenl~aidwhoisfororleanswithme~134":"Joana — Estás respondido, velho Rabugento-e-Ranzinza. Desembainhando de súbito a espada ao pressentir que seu momento chegou. Quem é por Deus e Sua Donzela? Quem é por Orléans comigo?","lahirecarriedawaydrawingalsoforgodandhis~orgodandhismaidtoorleans~53":"La Hire — Arrebatado, desembainhando também. Por Deus e Sua Donzela! A Orléans!","alltheknightsfollowinghisleadwithenthusi~dwithenthusiasmtoorleans~52":"Todos os Cavaleiros — Seguindo-lhe o exemplo com entusiasmo. A Orléans!","joanradiantfallsonherkneesinthanksgiving~uillewhocollapsescursing~141":"Joana, radiante, cai de joelhos em ação de graças a Deus. Todos se ajoelham, exceto o Arcebispo, que dá sua bênção com um sinal, e La Trémouille, que desaba, praguejando.","orleansmay29th1429dunoisaged26ispacingup~ythelovelinessoftheloire~634":"Orléans, 29 de maio de 1429. Dunois, de 26 anos, anda de um lado para outro num trecho de terreno na margem sul do prateado Loire, de onde se avista longamente o rio nas duas direções. Mandou fincar a lança com um galhardete, que tremula num forte vento leste. O escudo, com sua barra sinistra, está deitado ao lado. Traz na mão o bastão de comando. É bem constituído e carrega a armadura com desenvoltura. A testa larga e o queixo pontudo dão-lhe um rosto de triângulo equilátero, já marcado pelo serviço ativo e pela responsabilidade, com a expressão de um homem bondoso e capaz, sem afetações e sem ilusões tolas. Seu pajem está sentado no chão, os cotovelos nos joelhos, as faces nos punhos, olhando ociosamente a água. É de tarde; e tanto o homem como o rapaz são tocados pela beleza do Loire.","dunoishaltingforamomenttoglanceupatthest~terwillyouneverblowagain~477":"Dunois — Parando um instante para olhar o galhardete ao vento e sacudir a cabeça com cansaço antes de retomar o passeio. Vento oeste, vento oeste, vento oeste. Rameira: constante quando devia ser volúvel, volúvel quando devia ser constante. Vento oeste sobre o prateado Loire: o que rima com Loire? Olha de novo o galhardete e sacode o punho para ele. Mude, maldito, mude, vento inglês, rameira de vento, mude. Oeste, oeste, estou lhe dizendo. Com um rosnado retoma a marcha em silêncio, mas logo recomeça. Vento oeste, vento volúvel, vento teimoso, vento mulheril, vento falso de além-água, nunca mais vai soprar?","thepageboundingtohisfeetseetherethereshe~feetseetherethereshegoes~44":"O Pajem — Pondo-se de pé num salto. Veja! Ali! Lá vai ela!","dunoisstartledfromhisreverieeagerlywhere~ieeagerlywherewhothemaid~50":"Dunois — Sobressaltado de seu devaneio, ansioso. Onde? Quem? A Donzela?","thepagenothekingfisherlikebluelightnings~tningshewentintothatbush~58":"O Pajem — Não: o martim-pescador. Como um relâmpago azul. Entrou naquele arbusto.","dunoisfuriouslydisappointedisthatallyoui~ndtopitchyouintotheriver~89":"Dunois — Furiosamente desapontado. Só isso? Seu jovem idiota dos infernos: tenho vontade de jogá-lo no rio.","thepagenotafraidknowinghismanitlookedfri~luelooktheregoestheother~89":"O Pajem — Sem medo, conhecendo seu homem. Era terrivelmente bonito, aquele clarão azul. Olhe! Lá vai o outro!","dunoisrunningeagerlytotheriverbrimwherew~totheriverbrimwherewhere~44":"Dunois — Correndo ansioso à beira do rio. Onde? Onde?","thepagepointingpassingthereeds~epointingpassingthereeds~30":"O Pajem — Apontando. Passando pelos juncos.","dunoisdelightedisee~dunoisdelightedisee~19":"Dunois — Encantado. Estou vendo.","theyfollowtheflightuntilthebirdtakescove~htuntilthebirdtakescover~41":"Acompanham o voo até que a ave se esconda.","thepageyoublewmeupbecauseyouwerenotintim~intimetoseethemyesterday~59":"O Pajem — O senhor me passou um sermão porque não chegou a tempo de vê-los ontem.","dunoisyouknewiwasexpectingthemaidwhenyou~methingtoyelpfornexttime~94":"Dunois — Você sabia que eu esperava a Donzela quando começou a ganir. Vou lhe dar uma razão para ganir da próxima vez.","thepagearenttheylovelyiwishicouldcatchth~velyiwishicouldcatchthem~42":"O Pajem — Não são lindos? Queria poder apanhá-los.","dunoisletmecatchyoutryingtotrapthemandiw~ikeyouareanabominableboy~120":"Dunois — Deixe-me pegar você tentando prendê-los, e o meto na jaula de ferro por um mês, para lhe ensinar como é uma jaula. Você é um rapaz abominável.","thepagelaughsandsquatsdownasbefore~ghsandsquatsdownasbefore~34":"O Pajem — Ri, e agacha-se como antes. !","dunoispacingbluebirdbluebirdsinceiamfrie~willyougrudgemeawestwind~254":"Dunois — Andando. Pássaro azul, pássaro azul, já que sou teu amigo, muda o vento para mim. Não: não rima. Aquele que por ti pecou: assim é melhor. Mas não faz sentido. Dá com o pajem bem perto. Rapaz abominável! Afasta-se dele. Maria no véu azul, cor de martim-pescador: vais me negar um vento oeste?","asentrysvoicewestwardhaltwhogoesthere~westwardhaltwhogoesthere~37":"Voz de uma Sentinela, ao Oeste — Alto! Quem vem lá?","joansvoicethemaid~joansvoicethemaid~17":"Voz de Joana — A Donzela.","dunoisletherpasshithermaidtome~letherpasshithermaidtome~30":"Dunois — Deixem-na passar. Aqui, Donzela! A mim!","joaninsplendidarmorrushesininablazingrag~cupiedwithjoantonoticeit~130":"Joana, em esplêndida armadura, entra precipitada, num acesso de fúria. O vento cessa; e o galhardete cai frouxo pela lança; mas Dunois está ocupado demais com Joana para notar.","joanbluntlybeyoubastardoforleans~tlybeyoubastardoforleans~32":"Joana — Francamente. Sois o Bastardo de Orléans?","dunoiscoolandsternpointingtohisshieldyou~inisterareyoujoanthemaid~75":"Dunois — Frio e severo, apontando o escudo. Vedes a barra sinistra. Sois Joana, a Donzela?","joansure~joansure~8":"Joana — Sou.","dunoiswhereareyourtroops~dunoiswhereareyourtroops~24":"Dunois — Onde estão vossas tropas?","joanmilesbehindtheyhavecheatedmetheyhave~tothewrongsideoftheriver~73":"Joana — A léguas atrás. Enganaram-me. Trouxeram-me ao lado errado do rio.","dunoisitoldthemto~dunoisitoldthemto~17":"Dunois — Fui eu que mandei.","joanwhydidyoutheenglishareontheotherside~englishareontheotherside~40":"Joana — Por quê? Os ingleses estão do outro lado!","dunoistheenglishareonbothsides~theenglishareonbothsides~30":"Dunois — Os ingleses estão dos dois lados.","joanbutorleansisontheothersidewemustfigh~erehowcanwecrosstheriver~77":"Joana — Mas Orléans está do outro lado. Temos de combater os ingleses lá. Como atravessaremos o rio?","dunoisgrimlythereisabridge~noisgrimlythereisabridge~26":"Dunois — Sombrio. Há uma ponte.","joaningodsnamethenletuscrossthebridgeand~ssthebridgeandfallonthem~50":"Joana — Em nome de Deus, então, atravessemos a ponte e caiamos sobre eles.","dunoisitseemssimplebutitcannotbedone~ssimplebutitcannotbedone~36":"Dunois — Parece simples; mas não pode ser feito.","joanwhosaysso~joanwhosaysso~13":"Joana — Quem diz?","dunoisisaysoandolderandwiserheadsthanmin~nmineareofthesameopinion~60":"Dunois — Eu digo; e cabeças mais velhas e mais sábias que a minha são da mesma opinião.","joanroundlythenyourolderandwiserheadsare~ametoanygeneraloranytown~204":"Joana — Redondamente. Então vossas cabeças mais velhas e mais sábias são cabeças de bagre: fizeram de vós um tolo; e agora querem fazer de mim uma tola também, trazendo-me ao lado errado do rio. Não sabeis que vos trago melhor auxílio do que jamais veio a qualquer general ou cidade?","dunoissmilingpatientlyyourown~ssmilingpatientlyyourown~29":"Dunois — Sorrindo com paciência. O vosso próprio?","joannothehelpandcounselofthekingofheaven~whichisthewaytothebridge~64":"Joana — Não: o auxílio e o conselho do Rei do Céu. Qual é o caminho da ponte?","dunoisyouareimpatientmaid~unoisyouareimpatientmaid~25":"Dunois — Sois impaciente, Donzela.","joanisthisatimeforpatienceourenemyisatou~iwilldeliveryoufromfeari~128":"Joana — É esta hora de paciência? Nosso inimigo está às nossas portas; e aqui ficamos sem fazer nada. Oh, por que não combateis? Ouvi-me: eu vos livrarei do medo. Eu...","dunoislaughingheartilyandwavingheroffnon~endofthebridgethebigones~243":"Dunois — Rindo de coração, afastando-a com a mão. Não, não, minha menina: se me livrásseis do medo eu seria um bom cavaleiro para livro de histórias, mas um péssimo comandante para o exército. Vamos! deixai-me começar a fazer de vós um soldado. Leva-a à beira da água. Vedes aqueles dois fortes neste extremo da ponte? os grandes?","joanyesaretheyoursorthegoddams~saretheyoursorthegoddams~30":"Joana — Sim. São nossos ou dos goddams?","dunoisbequietandlistentomeifiwereineithe~fortstoholdthemagainstus~163":"Dunois — Calai-vos e ouvi-me. Se eu estivesse num daqueles fortes com apenas dez homens, poderia mantê-lo contra um exército. Os ingleses têm mais de dez vezes dez goddams naqueles fortes para os manter contra nós.","joantheycannotholdthemagainstgodgoddidno~ttousiwilltakethoseforts~120":"Joana — Não os podem manter contra Deus. Deus não lhes deu a terra sob aqueles fortes: roubaram-na d’Ele. Ele a deu a nós. Tomarei aqueles fortes.","dunoissinglehanded~dunoissinglehanded~18":"Dunois — Sozinha?","joanourmenwilltakethemiwillleadthem~illtakethemiwillleadthem~35":"Joana — Nossos homens os tomarão. Eu os conduzirei.","dunoisnotamanwillfollowyou~noisnotamanwillfollowyou~26":"Dunois — Nem um homem vos seguirá.","joaniwillnotlookbacktoseewhetheranyoneis~etheranyoneisfollowingme~51":"Joana — Não olharei para trás para ver se alguém me segue.","dunoisrecognizinghermettleandclappingher~inyouyouareinlovewithwar~116":"Dunois — Reconhecendo-lhe o brio e dando-lhe uma palmada cordial no ombro. Bom. Tendes madeira de soldado. Estais apaixonada pela guerra.","joanstartledohandthearchbishopsaidiwasin~idiwasinlovewithreligion~56":"Joana — Sobressaltada. Oh! E o Arcebispo disse que eu estava apaixonada pela religião.","dunoisigodforgivemeamalittleinlovewithwa~ikeawomanwithtwohusbands~120":"Dunois — Eu, Deus me perdoe, estou um pouco apaixonado pela guerra também, a diaba feia! Sou como um homem com duas esposas. Quereis ser como uma mulher com dois maridos?","joanmatteroffactlyiwillnevertakeahusband~swithagreatnoiseandsmoke~362":"Joana — Com naturalidade. Nunca tomarei marido. Um homem em Toul moveu ação contra mim por quebra de promessa; mas nunca lhe prometi nada. Sou soldado: não quero que me tomem por mulher. Não me vestirei de mulher. Não ligo para as coisas de que as mulheres gostam. Elas sonham com amantes e com dinheiro. Eu sonho em comandar uma carga e em pôr os canhões grandes. Vós, soldados, não sabeis usar os canhões grandes: pensais que se ganham batalhas com muito barulho e fumaça.","dunoiswithashrugtruehalfthetimetheartill~moretroublethanitisworth~69":"Dunois — Dando de ombros. É verdade. Metade do tempo a artilharia dá mais trabalho do que vale.","joanayeladbutyoucannotfightstonewallswit~gunsandmuchbiggergunstoo~82":"Joana — Pois é, rapaz; mas não se combate muralha de pedra com cavalos: é preciso canhões, e canhões bem maiores.","dunoisgrinningatherfamiliarityandechoing~llgetoverthestoniestwall~103":"Dunois — Sorrindo da familiaridade dela e repetindo-a. Pois é, moça; mas bom coração e uma escada firme passam pela muralha mais pétrea.","joaniwillbefirstuptheladderwhenwereachth~astardidareyoutofollowme~70":"Joana — Serei a primeira a subir a escada quando chegarmos ao forte, Bastardo. Desafio-vos a me seguir.","dunoisyoumustnotdareastaffofficerjoanonl~tmycalliftheycouldhelpme~202":"Dunois — Não deveis desafiar um oficial de estado-maior, Joana: apenas os oficiais de companhia têm licença para exibições de coragem pessoal. Além disso, deveis saber que vos acolho como santa, não como soldado. Tenho valentões de sobra a meu dispor, se eles pudessem me ajudar.","joaniamnotadaredeviliamaservantofgodmysw~ustdoityoushallnotstopme~247":"Joana — Não sou valentona: sou serva de Deus. Minha espada é sagrada: achei-a atrás do altar na igreja de Santa Catarina, onde Deus a escondeu para mim; e não posso desferir golpe com ela. Meu coração está cheio de coragem, não de ira. Eu conduzirei; e vossos homens seguirão: é tudo o que posso fazer. Mas devo fazê-lo: não me impedireis.","dunoisallingoodtimeourmencannottakethose~glishintherearonthisside~123":"Dunois — No devido tempo. Nossos homens não podem tomar aqueles fortes por uma sortida através da ponte. Têm de vir pela água e atacar os ingleses pela retaguarda, deste lado.","joanhermilitarysenseassertingitselfthenm~emandletyourmencrosstous~89":"Joana — Seu senso militar afirmando-se. Então fazei jangadas e pondes nelas canhões grandes; e deixai vossos homens cruzar até nós.","dunoistheraftsarereadyandthemenareembark~kedbuttheymustwaitforgod~63":"Dunois — As jangadas estão prontas; e os homens embarcados. Mas têm de esperar por Deus.","joanwhatdoyoumeangodiswaitingforthem~umeangodiswaitingforthem~36":"Joana — Que quereis dizer? Deus está esperando por eles.","dunoislethimsendusawindthenmyboatsaredow~eletmetakeyoutothechurch~147":"Dunois — Que Ele nos mande então um vento. Meus barcos estão rio abaixo: não podem subir contra vento e corrente ao mesmo tempo. Temos de esperar até que Deus mude o vento. Vinde: deixai-me levar-vos à igreja.","joannoilovechurchbuttheenglishwillnotyie~rchuntilwehavebeatenthem~134":"Joana — Não. Amo a igreja; mas os ingleses não cederão a orações: nada entendem senão pancadas duras e golpes de espada. Não irei à igreja até que os tenhamos batido.","dunoisyoumustihavebusinessforyouthere~ihavebusinessforyouthere~37":"Dunois — Deveis ir: tenho um serviço para vós lá.","joanwhatbusiness~joanwhatbusiness~16":"Joana — Que serviço?","dunoistoprayforawestwindihaveprayedandih~beyouareyoungandinnocent~127":"Dunois — Rezar por um vento oeste. Eu rezei; e dei dois castiçais de prata; mas minhas preces não foram atendidas. As vossas podem ser: sois jovem e inocente.","joanohyesyouarerightiwillprayiwilltellst~kshowmethewaytothechurch~106":"Joana — Oh sim: tendes razão. Rezarei: direi a Santa Catarina: ela fará Deus me dar um vento oeste. Depressa: mostrai-me o caminho da igreja.","thepagesneezesviolentlyatcha~agesneezesviolentlyatcha~28":"O Pajem — Espirra violentamente. Atchim!!!","joangodblessyouchildcoombastard~blessyouchildcoombastard~31":"Joana — Deus te abençoe, criança! Vamo, Bastardo.","theygooutthepagerisestofollowhepicksupth~chisnowstreamingeastward~121":"Saem. O pajem levanta-se para segui-los. Apanha o escudo e vai pegar também a lança quando nota o galhardete, que agora tremula para leste.","thepagedroppingtheshieldandcallingexcite~neurseigneurmademoiselle~80":"O Pajem — Largando o escudo e chamando-os excitado. Senhor! Senhor! Donzela!","dunoisrunningbackwhatisitthekingfisherhe~kseagerlyforituptheriver~67":"Dunois — Voltando correndo. O que é? O martim-pescador? Procura-o ansioso rio acima.","joanjoiningthemohakingfisherwhere~ngthemohakingfisherwhere~33":"Joana — Juntando-se a eles. Oh, um martim-pescador! Onde?","thepagenothewindthewindthewindpointingto~onthatiswhatmademesneeze~71":"O Pajem — Não: o vento, o vento, o vento apontando o galhardete: foi isso que me fez espirrar.","dunoislookingatthepennonthewindhaschange~ekingsarmyiamyoursoldier~137":"Dunois — Olhando o galhardete. O vento mudou. Persigna-se. Deus falou. Ajoelhando-se e entregando o bastão a Joana. Comandais o exército do rei. Sou vosso soldado.","thepagelookingdowntherivertheboatshavepu~pingupstreamlikeanything~78":"O Pajem — Olhando rio abaixo. Os barcos largaram. Estão subindo o rio a toda velocidade.","dunoisrisingnowforthefortsyoudaredmetofo~redmetofollowdareyoulead~55":"Dunois — Levantando-se. Agora, aos fortes. Desafiastes-me a seguir. Ousais conduzir?","joanburstingintotearsandflingingherarmsr~tontheladderandsayupjoan~158":"Joana — Rompendo em lágrimas e atirando os braços em torno de Dunois, beijando-o nas duas faces. Dunois, caro companheiro de armas, ajudai-me. Meus olhos estão cegos de lágrimas. Pondes meu pé na escada e dizei: “Sobe, Joana.”","dunoisdraggingheroutnevermindthetearsmak~makefortheflashoftheguns~61":"Dunois — Arrastando-a para fora. Não importam as lágrimas: rumo ao clarão dos canhões.","joaninablazeofcourageah~joaninablazeofcourageah~23":"Joana — Num lampejo de coragem. Ah!","dunoisdraggingheralongwithhimforgodandsa~hhimforgodandsaintdennis~49":"Dunois — Arrastando-a consigo. Por Deus e por São Dinis!","thepageshrillythemaidthemaidgodandthemai~terthemmadwithexcitement~118":"O Pajem — Estridente. A Donzela! A Donzela! Deus e a Donzela! Hurra‑a‑a! Apanha o escudo e a lança e sai saltitando atrás deles, louco de excitação."}$tr$::jsonb, 480)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- h-g-wells_the-invisible-man (122 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('h-g-wells_the-invisible-man', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"thestrangemansarrival":"A chegada do homem estranho","mrteddyhenfreysfirstimpressions":"As Primeiras Impressões do Sr. Teddy Henfrey","thethousandandonebottles":"As Mil e Uma Garrafas"}$tr$::jsonb, $tr${"thestrangercameearlyinfebruaryonewintryd~ookuphisquartersintheinn~709":"O forasteiro chegou no começo de fevereiro, num dia de inverno, sob um vento cortante e uma neve açoitada, a última nevada do ano, atravessando o planalto a pé desde a estação ferroviária de Bramblehurst, com uma pequena maleta preta na mão grossamente enluvada. Estava embrulhado da cabeça aos pés, e a aba do chapéu de feltro mole escondia cada centímetro de seu rosto, exceto a ponta brilhante do nariz; a neve se acumulara em seus ombros e no peito e acrescentava uma crista branca à carga que ele levava. Cambaleou para dentro da estalagem Coach and Horses mais morto do que vivo e arremessou a maleta no chão. — Fogo — gritou —, em nome da caridade humana! Um quarto e fogo! — Bateu os pés e sacudiu a neve de si no bar, e seguiu a sra. Hall até a saleta de hóspedes para fechar o trato. E com essa breve apresentação, isso e um par de soberanos atirados sobre a mesa, instalou-se na estalagem.","mrshalllitthefireandlefthimtherewhileshe~themagooddryinthekitchen~780":"A sra. Hall acendeu o fogo e deixou-o ali, enquanto ia preparar-lhe uma refeição com as próprias mãos. Um hóspede em Iping no inverno era uma sorte inaudita, ainda mais um hóspede que não regateava, e ela estava resolvida a mostrar-se digna de sua boa fortuna. Assim que o toucinho estava bem encaminhado, e Millie, a criada fleumática, fora um pouco avivada por algumas expressões de desprezo habilmente escolhidas, carregou a toalha, os pratos e os copos para a saleta e começou a pôr a mesa com o máximo de brilho. Embora o fogo estivesse crepitando com vigor, surpreendeu-se ao ver que o hóspede ainda estava de chapéu e casaco, de costas para ela, olhando pela janela a neve que caía no pátio. As mãos enluvadas estavam cruzadas às costas, e ele parecia perdido em pensamentos. Ela notou que a neve derretida que ainda salpicava os ombros dele pingava no seu tapete. — Posso levar seu chapéu e seu casaco, senhor? — disse. — Para dar-lhes uma boa secada na cozinha?","nohesaidwithoutturning~nohesaidwithoutturning~22":"— Não — disse ele, sem se virar.","shewasnotsureshehadheardhimandwasaboutto~abouttorepeatherquestion~57":"Ela não tinha certeza de que o ouvira e ia repetir a pergunta.","heturnedhisheadandlookedatheroverhisshou~etelyhidhischeeksandface~207":"Ele voltou a cabeça e olhou-a por cima do ombro. — Prefiro ficar com eles — disse com ênfase, e ela reparou que ele usava grandes óculos azuis com protetores laterais e tinha uma costeleta espessa sobre a gola do casaco, que escondia por completo as faces e o rosto.","verywellsirshesaidasyoulikeinabittheroom~nabittheroomwillbewarmer~52":"— Muito bem, senhor — disse ela. — Como quiser. Daqui a pouco a sala estará mais quente.","hemadenoanswerandhadturnedhisfaceawayfro~ohimyourlunchisservedsir~411":"Ele não respondeu e virara de novo o rosto para o outro lado, e a sra. Hall, sentindo que suas tentativas de conversa eram inoportunas, dispôs o resto das coisas da mesa num staccato rápido e saiu num átimo da sala. Quando voltou, ele ainda estava ali parado, como um homem de pedra, as costas curvadas, a gola levantada, a aba do chapéu pingando e baixada, escondendo por completo o rosto e as orelhas. Ela pousou os ovos e o toucinho com considerável ênfase e disse, ou antes gritou, para ele: — Seu almoço está servido, senhor.","thankyouhesaidatthesametimeanddidnotstir~thacertaineagerquickness~128":"— Obrigado — disse ele ao mesmo tempo, e não se mexeu até que ela estivesse fechando a porta. Então girou nos calcanhares e aproximou-se da mesa com certa pressa ansiosa.","asshewentbehindthebartothekitchenshehear~ycarrieditintotheparlour~534":"Quando ela passou por trás do balcão em direção à cozinha, ouviu um som que se repetia a intervalos regulares. Tchic, tchic, tchic, fazia ele, o som de uma colher sendo batida depressa numa tigela. — Aquela menina! — disse ela. — Pois é! Esqueci completamente. É por ela ser tão lenta! — E, enquanto ela própria acabava de misturar a mostarda, deu a Millie algumas punhaladas verbais por sua excessiva lentidão. Ela cozinhara o presunto e os ovos, pusera a mesa e fizera tudo, enquanto Millie (ajuda, essa!) só conseguira atrasar a mostarda. E com um hóspede novo, que queria ficar! Então encheu o mostardeiro e, colocando-o com certa imponência numa bandeja de chá preta e dourada, levou-o à saleta.","sherappedandenteredpromptlyasshedidsoher~voicethatbrookednodenial~423":"Ela bateu à porta e entrou prontamente. Ao fazê-lo, o hóspede moveu-se depressa, de modo que ela só entreviu um objeto branco desaparecendo atrás da mesa. Parecia que ele estava apanhando algo do chão. Ela depositou o pote de mostarda na mesa e então reparou que o sobretudo e o chapéu tinham sido tirados e postos sobre uma cadeira diante do fogo, e que um par de botas molhadas ameaçava de ferrugem o guarda-fogo de aço. Foi até essas coisas resoluta. “Suponho que agora posso levá-las para secar”, disse, em voz que não admitia recusa.","leavethehatsaidhervisitorinamuffledvoice~assittingandlookingather~102":"“Deixe o chapéu”, disse o hóspede, com voz abafada, e, virando-se, ela viu que ele erguera a cabeça e estava sentado olhando para ela.","foramomentshestoodgapingathimtoosurprise~athimtoosurprisedtospeak~48":"Por um momento ficou de boca aberta diante dele, surpresa demais para falar.","heheldawhiteclothitwasaserviettehehadbro~hatforamomentshewasrigid~696":"Ele segurava um pano branco — era um guardanapo que trouxera consigo — sobre a parte inferior do rosto, de modo que a boca e o queixo ficavam completamente escondidos, e esse era o motivo da voz abafada. Mas não foi isso que sobressaltou a Sra. Hall. Foi o fato de que toda a sua testa, acima dos óculos azuis, estava coberta por uma atadura branca, e outra lhe cobria as orelhas, não deixando um fragmento do rosto exposto, exceto o nariz rosado e pontudo. Estava vivo, rosado e lustroso, exatamente como no primeiro momento. Usava uma jaqueta de veludo marrom-escuro, com um colarinho alto e preto, forrado de linho, levantado em torno do pescoço. O cabelo preto e espesso, escapando como podia por baixo e entre as ataduras cruzadas, projetava-se em curiosas caudas e pontas, dando-lhe a aparência mais estranha que se pode conceber. Aquela cabeça abafada e enfaixada era tão diferente do que ela esperava que, por um instante, ficou rígida.","hedidnotremovetheserviettebutremainedhol~ctlythroughthewhitecloth~180":"Ele não retirou o guardanapo, mas continuou segurando-o, como ela via agora, com uma mão enluvada de marrom, e fitando-a com seus inescrutáveis óculos azuis. “Deixe o chapéu”, disse, falando com muita nitidez através do pano branco.","hernervesbegantorecoverfromtheshocktheyh~andshestoppedembarrassed~138":"Os nervos dela começaram a se recuperar do choque que haviam recebido. Pôs o chapéu na cadeira outra vez, junto ao fogo. “Eu não sabia, senhor”, começou, “que...”, e parou, embaraçada.","thankyouhesaiddrilyglancingfromhertothed~thedoorandthenatheragain~60":"“Obrigado”, disse ele secamente, olhando dela para a porta e depois para ela de novo.","illhavethemnicelydriedsiratonceshesaidan~utwithnowwhenshegotthere~401":"“Vou deixá-las bem secas, senhor, agora mesmo”, disse ela, e levou as roupas dele para fora do quarto. Lançou outro olhar à cabeça envolta em branco e aos óculos azuis ao sair pela porta; mas o guardanapo ainda estava diante do rosto dele. Estremeceu um pouco ao fechar a porta atrás de si, e o rosto era eloquente em sua surpresa e perplexidade. “Nunca vi”, sussurrou. “Pronto!” Foi bem de mansinho até a cozinha e, ao chegar, estava preocupada demais para perguntar a Millie o que ela estava fazendo de trapalhada agora.","thevisitorsatandlistenedtoherretreatingf~rairtothetableandhismeal~388":"O hóspede ficou sentado, ouvindo os passos dela se afastarem. Lançou um olhar interrogativo à janela antes de retirar o guardanapo e retomar a refeição. Deu uma garfada, olhou desconfiado para a janela, deu outra, depois se levantou e, com o guardanapo na mão, atravessou o quarto e baixou a cortina até o alto da musselina branca que obscurecia as vidraças de baixo. Isso deixou o quarto em penumbra. Feito isso, voltou com ar mais folgado à mesa e à refeição.","thepoorsoulshadanaccidentoranoprationors~andagesdidgivemetobesure~96":"“Coitado, deve ter sofrido um acidente ou uma operação ou coisa assim”, disse a Sra. Hall. “Que susto aquelas ataduras me deram, na verdade!”","sheputonsomemorecoalunfoldedtheclothesho~shismouthwashurttoomaybe~266":"Pôs mais carvão, desdobrou o cavalete e estendeu nele o casaco do viajante. “E aqueles óculos! Ora, mais parecia um escafandro do que um homem de verdade!” Pendurou o cachecol dele numa ponta do cavalete. “E segurando aquele lenço na boca o tempo todo. Falando através dele!… Talvez a boca também estivesse machucada — pode ser.”","sheturnedroundasonewhosuddenlyremembersb~udonethemtatersyetmillie~110":"Virou-se, como quem de repente se lembra. “Deus do céu!”, disse, mudando de assunto de supetão; “ainda não terminou aquelas batatas, Millie?”","whenmrshallwenttoclearawaythestrangerslu~lestheyhadlackedhitherto~579":"Quando a Sra. Hall foi retirar o almoço do desconhecido, sua ideia de que a boca dele devia também ter sido cortada ou desfigurada no acidente que supunha ele ter sofrido foi confirmada, pois ele fumava cachimbo e, durante todo o tempo em que ela esteve no quarto, jamais afrouxou o cachecol de seda que enrolara na parte inferior do rosto para levar a piteira aos lábios. Contudo não era esquecimento, pois ela viu que ele olhava para o cachimbo enquanto este se apagava em brasa. Ele estava sentado no canto, de costas para a cortina da janela, e falava agora, depois de ter comido e bebido e de estar confortavelmente aquecido, com menos agressiva brevidade que antes. O reflexo do fogo emprestava uma espécie de animação vermelha aos seus grandes óculos, que até então lhes faltara.","ihavesomeluggagehesaidatbramblehurststat~nwithatrapwhowouldgoover~268":"“Tenho alguma bagagem”, disse ele, “na estação de Bramblehurst”, e perguntou-lhe como poderia mandar buscá-la. Inclinou a cabeça enfaixada, com muita polidez, em agradecimento à explicação dela. “Amanhã?”, disse. “Não há entrega mais rápida?”, e pareceu bastante desapontado quando ela respondeu: “Não”. Tinha certeza? Nenhum homem com carroça que fosse até lá?","mrshallnothingloathansweredhisquestionsa~rhappeninamomentdontthey~273":"A Sra. Hall, de bom grado, respondeu às perguntas e desenvolveu uma conversa. “É uma estrada íngreme pelas colinas, senhor”, disse em resposta à pergunta sobre a carroça; e então, aproveitando uma brecha, disse: “Foi lá que uma carruagem virou, faz mais de um ano. Um cavalheiro morto, além do cocheiro. Acidentes, senhor, acontecem num instante, não é?”","butthevisitorwasnottobedrawnsoeasilythey~ghhisimpenetrableglasses~110":"Mas o hóspede não se deixaria levar tão facilmente. “Acontecem”, disse através do cachecol, observando-a calmamente por seus óculos impenetráveis.","buttheytakelongenoughtogetwelldonttheyth~ivenmeadreadofascythesir~197":"“Mas levam um bom tempo pra sarar, não é?… Teve o filho da minha irmã, o Tom, que cortou o braço com uma foice, caiu em cima dela no campo de feno, e, Deus me livre! passou três meses amarrado, senhor. O senhor mal acreditaria. Me deu verdadeiro pavor de foice, senhor.”","icanquiteunderstandthatsaidthevisitor~rstandthatsaidthevisitor~37":"“Compreendo perfeitamente”, disse o hóspede.","hewasafraidonetimethathedhavetohaveanopr~noprationhewasthatbadsir~60":"“Uma hora ele temeu que fosse precisar de uma operação — estava tão mal, senhor.”","thevisitorlaughedabruptlyabarkofalaughth~illinhismouthwashehesaid~84":"O hóspede riu de repente, um latido de riso que pareceu morder e matar na boca. “É mesmo?”, disse.","hewassirandnolaughingmattertothemashadth~aymakesoboldastosayitsir~174":"“Estava, senhor. E não era motivo de riso pra quem cuidava dele, como eu — minha irmã tão ocupada com os pequenos. Havia ataduras pra pôr, senhor, e ataduras pra tirar. De modo que, se me permite a ousadia de dizer, senhor...”","willyougetmesomematchessaidthevisitorqui~quiteabruptlymypipeisout~61":"“A senhora me traria uns fósforos?”, disse o hóspede, bem abruptamente. “Meu cachimbo apagou.”","mrshallwaspulledupsuddenlyitwascertainly~ignsshewentforthematches~150":"A Sra. Hall foi detida de súbito. Era certamente rude da parte dele, depois de ela lhe contar tudo o que fizera. Ficou um momento ofegante diante dele e lembrou-se dos dois soberanos. Foi buscar os fósforos.","thankshesaidconciselyassheputthemdownand~hottimeofitthatafternoon~288":"“Obrigado”, disse ele concisamente, quando ela os pôs na mesa, e virou-lhe o ombro e tornou a olhar pela janela. Era desencorajador demais. Evidentemente ele era sensível no tocante a operações e ataduras. Ela não “se permitiu a ousadia de dizer”, afinal. Mas o jeito dele de lhe dar um corte a irritara, e Millie passou um mau bocado naquela tarde.","thevisitorremainedintheparlouruntilfouro~hefirelightperhapsdozing~203":"O hóspede permaneceu na sala até as quatro horas, sem dar o fantasma de uma desculpa para uma intrusão. Na maior parte do tempo ficou bem quieto; parecia que ficava sentado na escuridão crescente fumando à luz do fogo — talvez cochilando.","onceortwiceacuriouslistenermighthavehear~rcreakedashesatdownagain~172":"Uma ou duas vezes um ouvinte curioso o teria ouvido mexendo no carvão, e por cinco minutos foi audível andando pela sala. Parecia falar sozinho. Depois a poltrona rangeu quando ele se sentou outra vez.","atfouroclockwhenitwasfairlydarkandmrshal~woutsidewasfallingfaster~232":"Às quatro horas, quando já estava bastante escuro e a Sra. Hall juntava coragem para entrar e perguntar ao hóspede se aceitava um chá, Teddy Henfrey, o consertador de relógios, entrou no bar. “Minha nossa! Sra. Hall”, disse ele, “mas este tempo é terrível pra botinas finas!” A neve lá fora caía mais depressa.","mrshallagreedandthennoticedhehadhisbagwi~ontdonuthinbutpointatsix~194":"A Sra. Hall concordou e então reparou que ele trazia a sua maleta. “Já que o senhor está aqui, seu Teddy”, disse ela, “eu ficaria contente se desse uma olhadinha no velho relógio da sala. Anda, e bate bem e forte; mas o ponteiro das horas não faz outra coisa senão marcar seis.”","andleadingthewayshewentacrosstotheparlou~rdoorandrappedandentered~64":"E, guiando-o, atravessou até a porta da sala, bateu e entrou.","hervisitorshesawassheopenedthedoorwassea~sshefanciedhadtrickedher~848":"O hóspede, viu ela ao abrir a porta, estava sentado na poltrona diante do fogo, cochilando, ao que parecia, com a cabeça enfaixada pendendo para um lado. A única luz no aposento era o brilho vermelho do fogo — que acendia os olhos dele como sinais ferroviários de perigo, mas deixava o rosto baixo na escuridão — e os escassos vestígios do dia que entravam pela porta aberta. Tudo era rubro, sombrio e indistinto para ela, ainda mais por ter acabado de acender o lampião do bar, e seus olhos estarem ofuscados. Mas por um segundo pareceu-lhe que o homem que via tinha uma enorme boca escancarada — uma boca vasta e inacreditável que engolia toda a parte inferior do rosto. Foi a sensação de um instante: a cabeça envolta em branco, os monstruosos olhos esbugalhados e esse bocejo imenso por baixo. Então ele se mexeu, ergueu-se de um salto na poltrona, levou a mão ao rosto. Ela abriu a porta de par em par, de modo que o aposento ficou mais claro, e viu-o com mais nitidez, o cachecol erguido até o rosto exatamente como o vira segurar o guardanapo antes. As sombras, imaginou, a haviam enganado.","wouldyoumindsirthismanacomingtolookatthe~ingfromthemomentaryshock~86":"“O senhor se importaria, senhor, deste homem vir olhar o relógio, senhor?”, disse ela, recobrando-se do choque momentâneo.","lookattheclockhesaidstaringroundinadrows~gmorefullyawakecertainly~106":"“Olhar o relógio?”, disse ele, olhando em redor de modo sonolento e falando por cima da mão, e depois, despertando mais plenamente: “certamente”.","mrshallwentawaytogetalampandheroseandstr~sonhewashesaystakenaback~148":"A Sra. Hall foi buscar um lampião, e ele se ergueu e espreguiçou-se. Veio então a luz, e o Sr. Teddy Henfrey, entrando, deparou com aquela figura enfaixada. Ficou, diz ele, “desconcertado”.","goodafternoonsaidthestrangerregardinghim~rkspectacleslikealobster~101":"“Boa tarde”, disse o desconhecido, observando-o — como diz o Sr. Henfrey, com um vívido senso dos óculos escuros — “como uma lagosta”.","ihopesaidmrhenfreythatitsnointrusion~enfreythatitsnointrusion~36":"“Espero”, disse o Sr. Henfrey, “que não seja intromissão.”","nonewhateversaidthestrangerthoughiunders~bemineformyownprivateuse~112":"“De modo algum”, disse o desconhecido. “Embora, pelo que entendo”, disse voltando-se para a Sra. Hall, “esta sala deva ser realmente minha, para meu uso particular.”","ithoughtsirsaidmrshallyoudprefertheclock~rshallyoudprefertheclock~40":"“Pensei, senhor”, disse a Sra. Hall, “que o senhor preferiria o relógio...”","certainlysaidthestrangercertainlybutasar~etobealoneandundisturbed~71":"“Certamente”, disse o desconhecido, “certamente — mas, via de regra, gosto de ficar só e sem ser incomodado.","butimreallygladtohavetheclockseentohesai~illtheclockmendingisover~342":"“Mas fico realmente contente em ter o relógio consertado”, disse, vendo certa hesitação nas maneiras do Sr. Henfrey. “Muito contente.” O Sr. Henfrey tivera a intenção de pedir desculpas e retirar-se, mas essa antecipação o tranquilizou. O desconhecido virou-se de costas para a lareira e pôs as mãos atrás. “E daqui a pouco”, disse, “quando o conserto do relógio terminar, creio que gostaria de tomar um chá. Mas não antes de terminar o conserto do relógio.”","mrshallwasabouttoleavetheroomshemadenoco~nthatistheearliesthesaid~321":"A Sra. Hall ia deixar o aposento — dessa vez não fez avanços de conversa, pois não queria levar um corte diante do Sr. Henfrey — quando o hóspede lhe perguntou se tomara alguma providência sobre os seus caixotes em Bramblehurst. Ela disse que mencionara o assunto ao carteiro, e que o carreteiro poderia trazê-los no dia seguinte. “A senhora tem certeza de que é o mais cedo possível?”, disse ele.","shewascertainwithamarkedcoldness~rtainwithamarkedcoldness~32":"Ela tinha certeza, com marcada frieza.","ishouldexplainheaddedwhatiwasreallytooco~experimentalinvestigator~96":"“Devo explicar”, acrescentou, “o que estava realmente frio e cansado demais para fazer antes, que sou um investigador experimental.”","indeedsirsaidmrshallmuchimpressed~saidmrshallmuchimpressed~33":"“É mesmo, senhor”, disse a Sra. Hall, muito impressionada.","andmybaggagecontainsapparatusandapplianc~nsapparatusandappliances~42":"“E minha bagagem contém aparelhos e instrumentos.”","veryusefulthingsindeedtheyaresirsaidmrsh~eedtheyaresirsaidmrshall~43":"“Coisas muito úteis, de fato, senhor”, disse a Sra. Hall.","andimverynaturallyanxioustogetonwithmyin~ustogetonwithmyinquiries~47":"“E estou, muito naturalmente, ansioso para prosseguir com minhas pesquisas.”","ofcoursesir~ofcoursesir~11":"“É claro, senhor.”","myreasonforcomingtoipingheproceededwitha~ditiontomyworkanaccident~147":"“Minha razão para vir a Iping”, prosseguiu, com certa deliberação de maneiras, “foi… o desejo de solidão. Não desejo ser perturbado em meu trabalho. Além do meu trabalho, um acidente...”","ithoughtasmuchsaidmrshalltoherself~muchsaidmrshalltoherself~34":"“Foi o que pensei”, disse a Sra. Hall a si mesma.","necessitatesacertainretirementmyeyesares~thingsshouldbeunderstood~301":"“...exige certo retiro. Meus olhos — são às vezes tão fracos e doloridos que tenho de me fechar no escuro por horas a fio. Trancar-me. Às vezes — de vez em quando. Não agora, certamente. Nessas ocasiões, a mais leve perturbação, a entrada de um estranho no quarto, é para mim fonte de excruciante aborrecimento — convém que essas coisas sejam entendidas.”","certainlysirsaidmrshallandifimightmakeso~fimightmakesoboldastoask~51":"“Certamente, senhor”, disse a Sra. Hall. “E se eu puder me permitir a ousadia de perguntar...”","thatithinkisallsaidthestrangerwiththatqu~mpathyforabetteroccasion~144":"“Isso, penso, é tudo”, disse o desconhecido, com aquele ar tranquilamente irresistível de encerramento que podia assumir à vontade. A Sra. Hall reservou sua pergunta e sua compaixão para melhor ocasião.","aftermrshallhadlefttheroomheremainedstan~verycoldforthetimeofyear~994":"Depois que a Sra. Hall deixou o aposento, ele permaneceu de pé diante do fogo, olhando fixo, como diz o Sr. Henfrey, para o conserto do relógio. O Sr. Henfrey não só tirou os ponteiros e o mostrador do relógio, como extraiu o mecanismo; e procurou trabalhar da maneira mais lenta, quieta e despretensiosa possível. Trabalhava com o lampião perto de si, e o quebra-luz verde lançava uma luz brilhante sobre as suas mãos, a caixa e as engrenagens, deixando o resto do aposento nas sombras. Quando erguia os olhos, manchas coloridas nadavam diante deles. Sendo por constituição de natureza curiosa, tirara o mecanismo — providência bastante desnecessária — com a ideia de retardar a partida e talvez entabular conversa com o desconhecido. Mas o desconhecido ficava ali, perfeitamente calado e imóvel. Tão imóvel que isso passou a irritar os nervos de Henfrey. Sentiu-se sozinho no aposento e ergueu os olhos, e ali, cinzenta e difusa, estava a cabeça enfaixada e as enormes lentes azuis a fitá-lo fixamente, com uma névoa de manchas verdes a flutuar diante delas. Era tão sobrenatural para Henfrey que por um minuto ficaram a se encarar sem expressão. Então Henfrey baixou os olhos de novo. Situação desconfortabilíssima! Alguém gostaria de dizer alguma coisa. Deveria observar que o tempo estava muito frio para a época do ano?","helookedupasiftotakeaimwiththatintroduct~oryshottheweatherhebegan~64":"Ergueu os olhos como se fosse fazer pontaria com esse tiro introdutório. “O tempo...”, começou.","whydontyoufinishandgosaidtherigidfiguree~xleyouresimplyhumbugging~144":"“Por que não termina e vai embora?”, disse a figura rígida, evidentemente num estado de raiva dolorosamente reprimida. “Tudo o que tem a fazer é fixar o ponteiro das horas no eixo. O senhor está apenas enrolando...”","certainlysironeminutemoreioverlookedandm~mrhenfreyfinishedandwent~63":"“Certamente, senhor — só mais um minuto. Eu me descuidei...” e o Sr. Henfrey terminou e foi embora.","buthewentfeelingexcessivelyannoyeddamnit~ustdoaclockattimessurely~134":"Mas foi sentindo-se excessivamente aborrecido. “Com mil diabos!”, disse o Sr. Henfrey consigo mesmo, caminhando pesadamente pela aldeia através da neve que derretia; “um homem tem de consertar um relógio de vez em quando, ora essa.”","andagaincantamanlookatyouugly~aincantamanlookatyouugly~29":"E de novo: “Um homem não pode nem olhar pra você? — Feio!”","andyetagainseeminglynotifthepolicewaswan~bemorewroppedandbandaged~81":"E mais uma vez: “Pelo visto não. Se a polícia estivesse atrás de você, não poderia andar mais embrulhado e enfaixado.”","atgleesonscornerhesawhallwhohadrecentlym~ngowdoteddyhesaidpassing~295":"Na esquina do Gleeson, viu Hall, que casara recentemente com a dona da hospedaria do estranho, no Coach and Horses, e que agora conduzia a carroça de Iping, quando alguém precisava, até o entroncamento de Sidderbridge, vindo ao seu encontro na volta de lá. Hall evidentemente estivera “parando um pouquinho” em Sidderbridge, a julgar por seu modo de guiar. “Como vai, Teddy?”, disse, passando.","yougotarumunuphomesaidteddy~gotarumunuphomesaidteddy~27":"“Você tem um tipo esquisito lá em casa!”, disse Teddy.","hallverysociablypulledupwhatsthatheasked~pulledupwhatsthatheasked~40":"Hall, muito sociável, parou. “O que é?”, perguntou.","rumlookingcustomerstoppingatthecoachandh~ndhorsessaidteddymysakes~61":"“Um freguês de aspecto esquisito hospedado no Coach and Horses”, disse Teddy. “Minha nossa!”","andheproceededtogivehallavividdescriptio~heaintevengivenanamehall~237":"E passou a dar a Hall uma vívida descrição do seu grotesco hóspede. “Parece um pouco um disfarce, não parece? Eu gostaria de ver o rosto de um homem se o tivesse hospedado em minha casa”, disse Henfrey. “Mas as mulheres são tão confiantes — quando se trata de estranhos. Ele alugou os seus quartos e nem sequer deu um nome, Hall.”","youdontsaysosaidhallwhowasamanofsluggish~anofsluggishapprehension~52":"“Não diga!”, disse Hall, que era homem de entendimento lento.","yessaidteddybytheweekwhateverheisyoucant~twontbestonesinboxeshall~140":"“Digo”, disse Teddy. “Por semana. Seja lá o que for, não se livra dele em menos de uma semana. E tem um monte de bagagem chegando amanhã, segundo diz. Vamos torcer pra não ser pedra em caixote, Hall.”","hetoldhallhowhisauntathastingshadbeenswi~llisposeimustseeboutthis~156":"Contou a Hall como sua tia em Hastings fora lograda por um estranho com malas vazias. Ao todo, deixou Hall vagamente desconfiado. “Anda, minha velha”, disse Hall. “Acho que tenho de ver isso aí.”","teddytrudgedonhiswaywithhismindconsidera~mindconsiderablyrelieved~51":"Teddy prosseguiu seu caminho com o espírito consideravelmente aliviado.","insteadofseeingboutithoweverhallonhisret~luggagewhenitcamenextday~749":"Em vez de “ver isso aí”, porém, Hall, ao chegar, foi severamente repreendido pela mulher pelo tempo que passara em Sidderbridge, e suas perguntas mansas foram respondidas com aspereza e de modo fora de propósito. Mas a semente de suspeita que Teddy plantara germinou na cabeça do Sr. Hall apesar desses desestímulos. “Vocês, mulheres, não sabem tudo”, disse o Sr. Hall, resolvido a apurar mais sobre a personalidade do hóspede na primeira oportunidade possível. E depois que o desconhecido foi para a cama, o que fez por volta das nove e meia, o Sr. Hall entrou muito agressivamente na sala e olhou com muita atenção para os móveis da mulher, só para mostrar que o desconhecido não era o senhor ali, e examinou de perto e um tanto desdenhosamente uma folha de cálculos matemáticos que o desconhecido deixara. Ao se recolher para a noite, instruiu a Sra. Hall a examinar com muito cuidado a bagagem do desconhecido quando chegasse no dia seguinte.","youmindyourownbusinesshallsaidmrshalland~aidmrshallandillmindmine~51":"“Cuide da sua vida, Hall”, disse a Sra. Hall, “que eu cuido da minha.”","shewasallthemoreinclinedtosnapathallbeca~doverandwenttosleepagain~355":"Estava tanto mais inclinada a ralhar com Hall porque o desconhecido era sem dúvida uma espécie de estranho extraordinariamente estranho, e ela de modo algum estava tranquila a respeito dele em seu íntimo. No meio da noite acordou sonhando com enormes cabeças brancas como nabos, que vinham se arrastando atrás dela, na ponta de pescoços intermináveis, e com vastos olhos negros. Mas, sendo mulher sensata, dominou seus terrores, virou-se e tornou a adormecer.","soitwasthatonthetwentyninthdayoffebruary~ivebeenwaitinglongenough~741":"Foi assim que, no dia vinte e nove de fevereiro, no início do degelo, essa pessoa singular caiu do infinito na aldeia de Iping. No dia seguinte a bagagem dele chegou pela lama — e que bagagem notável era. Havia de fato uns dois baús, como um homem racional poderia precisar, mas além disso havia uma caixa de livros — livros grandes e gordos, alguns dos quais apenas numa caligrafia incompreensível — e uma dúzia ou mais de engradados, caixas e estojos, contendo objetos embalados em palha, que, segundo parecia a Hall, ao puxar a palha com curiosidade casual, eram garrafas de vidro. O desconhecido, abafado em chapéu, casaco, luvas e cachecol, saiu impaciente ao encontro da carroça de Fearenside, enquanto Hall batia um papinho de fofoca antes de ajudar a trazê-los para dentro. Saiu sem reparar no cão de Fearenside, que farejava as pernas de Hall com espírito diletante. “Venham com essas caixas”, disse. “Já esperei o bastante.”","andhecamedownthestepstowardsthetailofthe~ayhandsonthesmallercrate~75":"E desceu os degraus em direção à traseira da carroça como se fosse pôr as mãos no engradado menor.","nosoonerhadfearensidesdogcaughtsightofhi~iedownandsnatchedhiswhip~251":"Assim que o cão de Fearenside o viu, porém, começou a eriçar o pelo e a rosnar ferozmente, e quando ele desceu correndo os degraus, deu um pulo indeciso e depois saltou direto na mão dele. “Ui!”, gritou Hall, pulando para trás, pois não era herói com cães, e Fearenside berrou: “Deite!”, e agarrou o chicote.","theysawthedogsteethhadslippedthehandhear~rpetedstairstohisbedroom~503":"Viram os dentes do cão escorregarem da mão, ouviram um chute, viram o cão executar um salto de flanco e cravar-se na perna do desconhecido, e ouviram o rasgar das calças. Então a ponta mais fina do chicote de Fearenside alcançou a propriedade dele, e o cão, ganindo de desalento, recuou para debaixo das rodas da carroça. Foi tudo questão de meio minuto veloz. Ninguém falou, todos gritaram. O desconhecido olhou rapidamente para a luva rasgada e para a perna, fez menção de se abaixar para esta, depois virou-se e subiu correndo os degraus para dentro da estalagem. Ouviram-no atravessar de cabeça o corredor e subir a escada sem tapete até o quarto.","youbruteyousaidfearensideclimbingoffthew~saidfearensideyoudbetter~132":"“Seu bruto!”, disse Fearenside, descendo da carroça com o chicote na mão, enquanto o cão o observava por entre a roda. “Venha cá”, disse Fearenside — “é melhor.”","hallhadstoodgapinghewuzbitsaidhallidbett~ecarriersdarghesaidbiten~129":"Hall ficara parado de boca aberta. “Ele foi mordido”, disse Hall. “É melhor eu ir ver ele”, e foi trotando atrás do desconhecido. Encontrou a Sra. Hall no corredor. “O cachorro do carreteiro”, disse, “mordeu ele.”","hewentstraightupstairsandthestrangersdoo~llysympatheticturnofmind~134":"Subiu direto a escada e, estando a porta do desconhecido entreaberta, empurrou-a e ia entrando sem cerimônia, por ser de natureza solidária.","theblindwasdownandtheroomdimhecaughtagli~atitmightbethathehadseen~409":"A cortina estava baixada e o quarto na penumbra. Entreviu uma coisa singularíssima, o que parecia um braço sem mão acenando em sua direção, e um rosto de três enormes manchas indeterminadas sobre branco, muito semelhante ao rosto de um amor-perfeito pálido. Então foi atingido violentamente no peito, arremessado para trás, e a porta foi batida na sua cara e trancada. Foi tão rápido que não lhe deu tempo de observar. Um agitar de formas indecifráveis, um golpe e um solavanco. Ali ficou ele no pequeno patamar escuro, perguntando-se o que poderia ser aquilo que vira.","acoupleofminutesafterherejoinedthelittle~debitenforthenandsoforth~417":"Dois minutos depois juntou-se ao pequeno grupo que se formara em frente ao Coach and Horses. Ali estava Fearenside contando tudo de novo pela segunda vez; ali estava a Sra. Hall dizendo que o cão dele não tinha nada que morder os hóspedes dela; ali estava Huxter, o comerciante geral do outro lado da rua, interrogativo; e Sandy Wadgers, da forja, judicial; além de mulheres e crianças, todos dizendo tolices: “Não deixava ele me morder, isso eu sei”; “Num é direito ter cachorro desses”; “Mas por que foi que ele mordeu?”, e assim por diante.","mrhallstaringatthemfromthestepsandlisten~dtoexpresshisimpressions~177":"O Sr. Hall, olhando-os dos degraus e escutando, achou incrível ter visto algo tão notável acontecer lá em cima. Além disso, seu vocabulário era limitado demais para exprimir suas impressões.","hedontwantnohelphesayshesaidinanswertohi~erbeatakinofhisluggagein~84":"“Ele diz que não quer ajuda”, disse em resposta à pergunta da mulher. “É melhor a gente ir levando a bagagem dele pra dentro.”","heoughttohaveitcauterisedatoncesaidmrhux~ciallyifitsatallinflamed~71":"“Devia cauterizar isso imediatamente”, disse o Sr. Huxter; “especialmente se estiver inflamado.”","idshootenthatswhatiddosaidaladyinthegrou~tiddosaidaladyinthegroup~41":"“Eu dava um tiro nele, é o que eu fazia”, disse uma senhora do grupo.","suddenlythedogbegangrowlingagain~thedogbegangrowlingagain~32":"De repente o cão começou a rosnar de novo.","comealongcriedanangryvoiceinthedoorwayan~sandgloveshadbeenchanged~230":"“Venham logo”, gritou uma voz irada na porta, e ali estava o desconhecido abafado, com a gola levantada e a aba do chapéu abaixada. “Quanto mais cedo trouxerem essas coisas, mais contente ficarei.” Afirma um espectador anônimo que as calças e as luvas dele haviam sido trocadas.","wasyouhurtsirsaidfearensideimraresorryth~ensideimraresorrythedarg~45":"“O senhor se machucou, senhor?”, disse Fearenside. “Sinto muitíssimo que o cão...”","notabitsaidthestrangerneverbroketheskinh~inhurryupwiththosethings~61":"“Nem um pouco”, disse o desconhecido. “Não rompeu a pele. Depressa com essas coisas.”","hethensworetohimselfsomrhallasserts~tohimselfsomrhallasserts~35":"Em seguida praguejou consigo mesmo, assegura o Sr. Hall.","directlythefirstcratewasinaccordancewith~dacarefullypackedbalance~902":"Logo que o primeiro engradado foi, conforme as instruções dele, levado para a sala, o desconhecido lançou-se sobre ele com extraordinária avidez e começou a desembalá-lo, espalhando a palha com completo desprezo pelo tapete da Sra. Hall. E dele começou a tirar garrafas — garrafinhas gordas contendo pós, garrafas pequenas e esguias contendo líquidos coloridos e brancos, garrafas azuis caneladas com o rótulo “Veneno”, garrafas de corpo redondo e gargalo fino, grandes garrafas de vidro verde, grandes garrafas de vidro branco, garrafas com tampas de vidro e rótulos foscos, garrafas com rolhas finas, garrafas com batoques, garrafas com tampas de madeira, garrafas de vinho, garrafas de azeite de salada — pondo-as em fileiras no aparador, na cornija da lareira, na mesa sob a janela, em volta no chão, na estante — em toda parte. A botica de Bramblehurst não poderia ostentar metade de tantas. Era todo um espetáculo. Engradado após engradado rendeu garrafas, até que os seis ficaram vazios e a mesa alta de palha; as únicas coisas que saíram desses engradados além das garrafas foram uma porção de tubos de ensaio e uma balança cuidadosamente embalada.","anddirectlythecrateswereunpackedthestran~ggagethathadgoneupstairs~204":"E logo que os engradados foram desembalados, o desconhecido foi à janela e pôs-se a trabalhar, sem se preocupar minimamente com a desordem de palha, com o fogo que se apagara, com a caixa de livros lá fora, nem com os baús e outras bagagens que haviam subido.","whenmrshalltookhisdinnerintohimhewasalre~loorwhenheanticipatedher~527":"Quando a Sra. Hall lhe levou o jantar, ele já estava tão absorto no trabalho, despejando gotinhas das garrafas em tubos de ensaio, que não a ouviu até que ela varresse a maior parte da palha e pusesse a bandeja na mesa, com alguma ênfase talvez, vendo o estado em que o chão se achava. Então ele virou meio a cabeça e imediatamente a desviou de novo. Mas ela viu que ele tirara os óculos; estavam ao lado dele na mesa, e pareceu-lhe que as órbitas dele eram extraordinariamente fundas. Ele pôs os óculos de novo, e depois virou-se e encarou-a. Ela ia queixar-se da palha no chão quando ele se antecipou.","iwishyouwouldntcomeinwithoutknockinghesa~medsocharacteristicofhim~104":"“Gostaria que a senhora não entrasse sem bater”, disse no tom de anormal exasperação que parecia tão característico dele.","iknockedbutseemingly~iknockedbutseemingly~20":"“Eu bati, mas pelo visto...”","perhapsyoudidbutinmyinvestigationsmyreal~thejarofadoorimustaskyou~125":"“Talvez tenha batido. Mas em minhas pesquisas — minhas pesquisas realmente muito urgentes e necessárias — a mais leve perturbação, o solavanco de uma porta… devo pedir-lhe...”","certainlysiryoucanturnthelockifyourelike~relikethatyouknowanytime~58":"“Certamente, senhor. O senhor pode passar a chave se é assim, sabe. A qualquer hora.”","averygoodideasaidthestranger~ygoodideasaidthestranger~28":"“Uma ótima ideia”, disse o desconhecido.","thisstrorsirifimightmakesoboldastoremark~ightmakesoboldastoremark~40":"“Esta palha, senhor, se me permite a ousadia de observar...”","dontifthestrawmakestroubleputitdowninthe~dssuspiciouslylikecurses~88":"“Não. Se a palha dá trabalho, ponha na conta.” E murmurou para ela palavras suspeitosamente parecidas com pragas.","hewassooddstandingtheresoaggressiveandex~toknowsirwhatyouconsider~178":"Era tão esquisito, ali parado, tão agressivo e explosivo, garrafa numa mão e tubo de ensaio na outra, que a Sra. Hall ficou bastante alarmada. Mas era mulher resoluta. “Nesse caso, gostaria de saber, senhor, o que o senhor considera...”","ashillingputdownashillingsurelyashilling~ngsurelyashillingsenough~47":"“Um xelim — ponha um xelim. Decerto um xelim basta?”","sobeitsaidmrshalltakingupthetableclothan~ifyouresatisfiedofcourse~96":"“Que seja”, disse a Sra. Hall, apanhando a toalha de mesa e começando a estendê-la sobre a mesa. “Se o senhor está satisfeito, é claro...”","heturnedandsatdownwithhiscoatcollartowar~thhiscoatcollartowardher~44":"Ele virou-se e sentou, com a gola do casaco voltada para ela.","alltheafternoonheworkedwiththedoorlocked~listenednotcaringtoknock~311":"A tarde toda trabalhou com a porta trancada e, como atesta a Sra. Hall, na maior parte do tempo em silêncio. Mas uma vez houve um estrondo e um tinir de garrafas batendo umas nas outras como se a mesa tivesse sido atingida, e o estilhaço de uma garrafa arremessada com violência, e depois um rápido andar de um lado a outro do quarto. Temendo que “algo estivesse errado”, foi à porta e escutou, sem querer bater.","icantgoonhewasravingicantgoonthreehundre~cepatienceindeedfoolfool~141":"“Não posso continuar”, ele delirava. “Não posso continuar. Trezentos mil, quatrocentos mil! A imensa multidão! Enganado! Pode levar a minha vida inteira!… Paciência! Paciência, pois sim!… Tolo! tolo!”","therewasanoiseofhobnailsonthebricksinthe~hestrangerhadresumedwork~238":"Houve um ruído de tachas de botas sobre os tijolos do bar, e a Sra. Hall teve de deixar, muito a contragosto, o resto do solilóquio. Quando voltou, o quarto estava silencioso outra vez, salvo pela leve crepitação da cadeira dele e o ocasional tilintar de uma garrafa. Tudo passara; o desconhecido retomara o trabalho.","whenshetookinhisteashesawbrokenglassinth~edshecalledattentiontoit~140":"Quando lhe levou o chá, viu vidro quebrado no canto do quarto, sob o espelho côncavo, e uma mancha dourada que fora limpa com descuido. Chamou a atenção para isso.","putitdowninthebillsnappedhervisitorforgo~theexercisebookbeforehim~142":"“Ponha na conta”, retrucou o hóspede, ríspido. “Pelo amor de Deus, não me amole. Se há dano, ponha na conta”, e continuou a marcar uma lista no caderno diante de si.","illtellyousomethingsaidfearensidemysteri~tlebeershopofipinghanger~111":"“Vou lhe contar uma coisa”, disse Fearenside, misteriosamente. Era fim de tarde, e estavam na pequena cervejaria de Iping Hanger.","wellsaidteddyhenfrey~wellsaidteddyhenfrey~20":"“E então?”, disse Teddy Henfrey.","thischapyourespeakingofwhatmydogbitwellh~tellyouhesasblackasmyhat~218":"“Esse sujeito de quem você fala, que o meu cão mordeu. Pois bem — ele é preto. Pelo menos as pernas. Vi pelo rasgo das calças e pelo rasgo da luva. Você esperaria que aparecesse um tipo de rosado, não é? Pois bem — não apareceu nada disso. Só negrume. Digo-lhe que ele é preto como o meu chapéu.”","mysakessaidhenfreyitsarummycasealtogethe~hyhisnoseisaspinkaspaint~66":"“Minha nossa!”, disse Henfrey. “É um caso esquisito de qualquer jeito. Ora, o nariz dele é rosa como tinta!”","thatstruesaidfearensideiknowsthatanditel~withhorsesasanyonecansee~255":"“É verdade”, disse Fearenside. “Isso eu sei. E vou lhe dizer o que estou pensando. Esse homem é um malhado, Teddy. Preto aqui e branco ali — em manchas. E tem vergonha disso. É uma espécie de mestiço, e a cor saiu em manchas em vez de se misturar. Já ouvi falar de coisas assim. E é o jeito comum com os cavalos, como qualquer um pode ver.”"}$tr$::jsonb, 122)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- h-g-wells_the-island-of-doctor-moreau (67 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('h-g-wells_the-island-of-doctor-moreau', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"inthedingeyoftheladyvain":"No bote do Lady Vain","themanwhowasgoingnowhere":"O Homem que Não Ia a Lugar Nenhum","thestrangeface":"O Rosto Estranho"}$tr$::jsonb, $tr${"idonotproposetoaddanythingtowhathasalrea~rtioniwasoneofthefourmen~535":"Não pretendo acrescentar nada ao que já foi escrito sobre a perda do Lady Vain. Como todos sabem, ele colidiu com um casco à deriva dez dias depois de partir de Callao. O escaler, com sete tripulantes, foi recolhido dezoito dias depois pela canhoneira de Sua Majestade Myrtle, e a história de suas terríveis privações tornou-se quase tão conhecida quanto o caso, muito mais horrível, da Medusa. Mas tenho de acrescentar à história publicada do Lady Vain outra, possivelmente tão horrível e bem mais estranha. Até agora supôs-se que os quatro homens que estavam no bote perecessem, mas isso é incorreto. Tenho a melhor das provas para esta afirmação: eu era um dos quatro homens.","butinthefirstplaceimuststatethattherenev~wardshimbuthenevercameup~388":"Mas, em primeiro lugar, devo declarar que nunca houve quatro homens no bote: o número era três. Constans, que foi “visto pelo capitão saltando para o escaler”, felizmente para nós e infelizmente para ele, não chegou até nós. Desceu do emaranhado de cordas sob os estais do gurupés despedaçado, uma cordinha qualquer prendeu-lhe o calcanhar quando se soltou, e ele ficou por um instante pendurado de cabeça para baixo, depois caiu e bateu num cadernal ou numa verga que flutuava na água. Remamos em sua direção, mas ele nunca voltou à tona.","isayluckilyforushedidnotreachusandimight~ortsturdymanwithastammer~585":"Digo que foi felizmente para nós que ele não nos alcançou, e quase poderia dizer que foi felizmente para ele também; pois tínhamos conosco apenas um pequeno barril de água e alguns biscoitos de bordo encharcados, tão súbito fora o alarme, tão despreparado estava o navio para qualquer desastre. Pensamos que o pessoal da lancha estaria mais bem provido (embora, ao que parece, não estivesse) e tentamos chamá-los. Não podem ter-nos ouvido, e na manhã seguinte, quando a garoa se dissipou — o que só aconteceu depois do meio-dia —, não vimos nenhum sinal deles. Não conseguíamos ficar de pé para olhar em volta, por causa do balanço do bote. Os outros dois homens que haviam escapado até ali comigo eram um chamado Helmar, passageiro como eu, e um marinheiro cujo nome não sei, homem baixo e robusto, que gaguejava.","wedriftedfamishingandafterourwaterhadcom~kthesailorcameroundtohim~905":"Derivamos famintos e, depois de acabada a água, atormentados por uma sede intolerável, durante oito dias ao todo. Depois do segundo dia o mar acalmou-se lentamente até ficar liso como vidro. É de todo impossível ao leitor comum imaginar aqueles oito dias. Ele não tem, felizmente para si, nada na memória com que imaginá-los. Depois do primeiro dia, falávamos pouco um com o outro e ficávamos deitados em nossos lugares no bote, fitando o horizonte ou observando, com olhos que a cada dia ficavam maiores e mais encovados, a miséria e a fraqueza que dominavam nossos companheiros. O sol tornou-se impiedoso. A água acabou no quarto dia, e já pensávamos coisas estranhas e as dizíamos com os olhos; mas foi, creio, só no sexto que Helmar deu voz ao que todos pensávamos. Lembro que nossas vozes eram secas e finas, de modo que nos inclinávamos uns para os outros e poupávamos as palavras. Resisti com todas as forças; era antes a favor de afundar o bote e perecermos juntos entre os tubarões que nos seguiam; mas, quando Helmar disse que, se a proposta dele fosse aceita, teríamos o que beber, o marinheiro se passou para o lado dele.","iwouldnotdrawlotshoweverandinthenightthe~nlylikeathingfromwithout~634":"Eu não quis, porém, tirar a sorte, e à noite o marinheiro sussurrou a Helmar várias vezes, e eu me sentei na proa com a faca de bolso na mão, embora duvide de que tivesse forças para lutar; e de manhã concordei com a proposta de Helmar, e lançamos moedas de meio pêni para achar o escolhido. A sorte caiu sobre o marinheiro; mas ele era o mais forte de nós e não quis se submeter, e atacou Helmar com as mãos. Atracaram-se e quase se puseram de pé. Arrastei-me pelo bote até eles, pretendendo ajudar Helmar agarrando a perna do marinheiro; mas o marinheiro tropeçou com o balanço do bote, e os dois caíram sobre a borda e rolaram juntos para o mar. Afundaram como pedras. Lembro-me de ter rido disso, e de ter me perguntado por que ria. O riso me apanhou de repente, como algo vindo de fora.","ilayacrossoneofthethwartsforiknownothowl~alittletocatchmeinmybody~511":"Fiquei deitado atravessado sobre uma das talhas do bote, não sei por quanto tempo, pensando que, se tivesse forças, beberia água do mar e enlouqueceria para morrer depressa. E mesmo ali deitado vi, sem mais interesse do que se fosse uma pintura, uma vela subir em minha direção por sobre o horizonte. Minha mente devia estar divagando, e no entanto lembro-me de tudo o que aconteceu, com toda a nitidez. Lembro como minha cabeça balançava com as ondas, e como o horizonte, com a vela acima dele, dançava para cima e para baixo; mas lembro igualmente bem que tinha a convicção de estar morto, e que pensei que piada era eles chegarem tarde por tão pouco para me apanhar ainda em meu corpo.","foranendlessperiodasitseemedtomeilaywith~tweenmyteethandthatisall~666":"Por um período que me pareceu interminável, fiquei com a cabeça apoiada na talha, observando a escuna (era um navio pequeno, de aparelho de escuna a vante e a ré) emergir do mar. Ela seguia bordejando em um compasso cada vez mais largo, pois navegava de proa contra o vento. Nunca me ocorreu tentar chamar a atenção, e não me recordo de nada com clareza depois de avistar o costado dela, até me ver numa pequena cabine a ré. Há uma vaga e tênue lembrança de ser içado até a escada de bordo, e de um rosto grande e redondo, coberto de sardas e emoldurado por cabelos ruivos, que me fitava por cima da amurada. Tive também a impressão desconexa de um rosto escuro, de olhos extraordinários, bem junto ao meu; mas julguei que fosse um pesadelo, até o reencontrar. Creio recordar que me derramaram algum líquido por entre os dentes; e é só isso.","thecabininwhichifoundmyselfwassmallandra~squestionhowdoyoufeelnow~398":"A cabine em que me encontrei era pequena e bastante desarrumada. Um homem relativamente jovem, de cabelos cor de linho, bigode eriçado cor de palha e lábio inferior caído, estava sentado segurando meu pulso. Por um minuto nos encaramos sem falar. Tinha olhos cinzentos e aquosos, estranhamente vazios de expressão. Então, bem em cima de nós, soou um barulho como o de uma cama de ferro sendo arrastada, e o rosnado baixo e furioso de algum animal grande. Ao mesmo tempo o homem falou. Repetiu a pergunta: “Como se sente agora?”","ithinkisaidifeltallrighticouldnotrecolle~voicewasinaccessibletome~119":"Acho que disse que me sentia bem. Não conseguia lembrar como fora parar ali. Ele deve ter visto a pergunta em meu rosto, pois minha voz me era inacessível.","youwerepickedupinaboatstarvingthenameont~spotsofbloodonthegunwale~96":"“Recolheram o senhor num bote, morrendo de fome. O nome no bote era Lady Vain, e havia manchas de sangue na borda.”","atthesametimemyeyecaughtmyhandsothinthat~essoftheboatcamebacktome~121":"Nesse instante meu olhar deu com a minha mão, tão magra que parecia uma bolsa de pele suja cheia de ossos soltos, e toda a história do bote me voltou.","havesomeofthissaidheandgavemeadoseofsome~seofsomescarletstufficed~56":"“Tome um pouco disto”, disse ele, e me deu uma dose de um líquido escarlate, gelado.","ittastedlikebloodandmademefeelstronger~oodandmademefeelstronger~38":"Tinha gosto de sangue e me deixou mais forte.","youwereinlucksaidhetogetpickedupbyashipw~ationwiththeghostofalisp~113":"“O senhor teve sorte”, disse ele, “de ser recolhido por um navio com um médico a bordo.” Falava com uma articulação babosa, com um fantasma de ceceio.","whatshipisthisisaidslowlyhoarsefrommylon~yhoarsefrommylongsilence~48":"“Que navio é este?”, perguntei devagar, rouco de tão longo silêncio.","itsalittletraderfromaricaandcallaoinever~hecertainlyactsaccording~342":"“É um pequeno cargueiro de Arica e Callao. Nunca perguntei de onde ela veio, a princípio — da terra dos tolos de nascença, suponho. Eu mesmo sou passageiro, de Arica. O burro idiota que é dono dela — e também capitão, chamado Davies — perdeu a licença, ou coisa assim. Conhece o tipo — chama a coisa de Ipecacuanha, entre todos os nomes tolos e infernais; embora, quando há muito mar e nenhum vento, ela de fato faça jus ao nome.”","thenthenoiseoverheadbeganagainasnarlingg~venforsakenidiottodesist~130":"(Então o barulho lá em cima recomeçou, um rosnado furioso e a voz de um ser humano juntos. Depois outra voz, mandando algum “idiota abandonado por Deus” parar.)","youwerenearlydeadsaidmyinterlocutoritwas~iblefornearlythirtyhours~155":"“O senhor estava quase morto”, disse meu interlocutor. “Foi por um triz, realmente. Mas já pus alguma coisa em seu corpo. Reparou que o braço está dolorido? Injeções. O senhor ficou inconsciente por quase trinta horas.”","ithoughtslowlyiwasdistractednowbytheyelp~igibleforsolidfoodiasked~87":"Pensei devagar. (Agora me distraía o ganido de vários cães.) “Posso comer comida sólida?”, perguntei.","thankstomehesaidevennowthemuttonisboilin~vennowthemuttonisboiling~41":"“Graças a mim”, disse ele. “Agora mesmo o carneiro está fervendo.”","yesisaidwithassuranceicouldeatsomemutton~ranceicouldeatsomemutton~40":"“Sim”, disse eu com firmeza; “eu comeria um pouco de carneiro.”","butsaidhewithamomentaryhesitationyouknow~ertainsuspicioninhiseyes~142":"“Mas”, disse ele, com uma hesitação momentânea, “o senhor sabe, estou morrendo de vontade de ouvir como veio parar sozinho naquele bote. Maldito uivo!” Julguei perceber certa desconfiança em seus olhos.","hesuddenlyleftthecabinandiheardhiminviol~ogsandreturnedtothecabin~224":"Ele saiu de repente da cabine, e ouvi-o numa violenta discussão com alguém, que me pareceu responder-lhe em algaravia. A coisa soou como se terminasse em pancadaria, mas nisso achei que meus ouvidos se enganavam. Depois ele gritou com os cães e voltou à cabine.","wellsaidheinthedoorwayyouwerejustbeginni~erejustbeginningtotellme~50":"“Bem?”, disse da porta. “O senhor estava começando a me contar.”","itoldhimmynameedwardprendickandhowihadta~ycomfortableindependence~110":"Disse-lhe meu nome, Edward Prendick, e como me dedicara à história natural para aliviar o tédio de minha confortável independência.","heseemedinterestedinthisivedonesomescien~ongoontellmeabouttheboat~191":"Ele pareceu interessado. “Eu mesmo estudei um pouco de ciência. Fiz minha biologia no University College — tirando o ovário da minhoca e a rádula do caracol, e tudo isso. Meu Deus! Faz dez anos. Mas continue! continue! conte-me do bote.”","hewasevidentlysatisfiedwiththefranknesso~llshetoldmesomeanecdotes~409":"Estava evidentemente satisfeito com a franqueza de minha história, que contei em frases bastante concisas, pois me sentia horrivelmente fraco; e quando terminei, ele voltou de imediato ao assunto da história natural e de seus próprios estudos biológicos. Começou a me interrogar de perto sobre a Tottenham Court Road e a Gower Street. “O Caplatzi ainda prospera? Que loja era aquela!” Evidentemente fora um estudante de medicina bem comum, e derivou sem cerimônia para o tema dos music halls. Contou-me algumas anedotas.","leftitallhesaidtenyearsagohowjollyitallu~ewhathesdonetoyourmutton~189":"“Larguei tudo”, disse ele, “faz dez anos. Como era divertido tudo aquilo! Mas fiz papel de jovem asno — esgotei-me antes dos vinte e um. Ouso dizer que agora tudo é diferente. Mas preciso ir ver aquele asno do cozinheiro e o que fez com o seu carneiro.”","thegrowlingoverheadwasrenewedsosuddenlya~hebeastthathadtroubledme~242":"O rosnado lá em cima recomeçou, tão de repente e com tanta fúria selvagem que me assustou. “O que é isso?”, gritei atrás dele, mas a porta já se fechara. Ele voltou com o carneiro cozido, e fiquei tão excitado com o cheiro apetitoso que esqueci o barulho da fera que me perturbara.","afteradayofalternatesleepandfeedingiwass~tthatithadtolandhimfirst~588":"Depois de um dia alternando sono e comida, eu já estava recuperado o bastante para ir do beliche até a escotilha e ver os mares verdes tentando acompanhar nosso passo. Julguei que a escuna corria com o vento pela popa. Montgomery — esse era o nome do homem de cabelos cor de linho — entrou outra vez quando eu estava ali, e pedi-lhe roupas. Emprestou-me algumas peças de brim dele, pois as que eu usara no bote haviam sido jogadas ao mar. Ficavam-me bastante largas, pois ele era grande e de membros longos. Disse-me displicente que o capitão estava três quartos bêbado em sua cabine. Enquanto me vestia, comecei a fazer-lhe perguntas sobre o destino do navio. Disse que o navio ia para o Havaí, mas que antes tinha de deixá-lo em terra.","wheresaidi~wheresaidi~10":"“Onde?”, perguntei.","itsanislandwhereilivesofarasiknowithasnt~arasiknowithasntgotaname~48":"“Numa ilha, onde moro. Pelo que sei, não tem nome.”","hestaredatmewithhisnetherlipdroppingandl~thediscretiontoasknomore~149":"Ele me encarou com o lábio inferior caído, e pareceu de súbito tão obstinadamente estúpido que me veio à cabeça que desejava fugir às minhas perguntas. Tive a discrição de não perguntar mais.","weleftthecabinandfoundamanatthecompanion~urnedwithanimalswiftness~437":"Saímos da cabine e encontramos um homem no tombadilho a nos obstruir o caminho. Estava parado na escada, de costas para nós, espiando por cima da borda da escotilha. Era, pude ver, um homem disforme, baixo, largo e desajeitado, de costas tortas, pescoço peludo e cabeça afundada entre os ombros. Vestia sarja azul-escura e tinha cabelos pretos peculiarmente grossos e ásperos. Ouvi os cães invisíveis rosnarem furiosamente e, de imediato, ele recuou de repente — esbarrando na mão que estendi para afastá-lo de mim. Virou-se com rapidez animal.","insomeindefinablewaytheblackfacethusflas~lowofexcitementinhisface~341":"De algum modo indefinível, o rosto negro assim lançado sobre mim chocou-me profundamente. Era singularmente deformado. A parte inferior da face projetava-se, formando algo vagamente sugestivo de um focinho, e a enorme boca entreaberta mostrava dentes brancos tão grandes quanto jamais vi em boca humana. Os olhos eram injetados de sangue nas bordas, com mal um filete de branco em torno das pupilas castanho-esverdeadas. Havia um estranho brilho de excitação em seu rosto.","confoundyousaidmontgomerywhythedevildont~vildontyougetoutoftheway~57":"“Com mil diabos!”, disse Montgomery. “Por que raios não sai do caminho?”","theblackfacedmanstartedasidewithoutaword~tetoneyourplaceisforward~198":"O homem de rosto escuro afastou-se sem uma palavra. Continuei subindo a escada, olhando-o instintivamente enquanto o fazia. Montgomery ficou um momento ao pé dela. “O senhor não tem nada que fazer aqui, bem sabe”, disse em tom deliberado. “O seu lugar é a vante.”","theblackfacedmancoweredtheywonthavemefor~rhoarsequalityinhisvoice~90":"O homem de rosto escuro encolheu-se. “Eles... não me querem a vante.” Falava devagar, com uma qualidade estranha e rouca na voz.","wonthaveyouforwardsaidmontgomeryinamenac~andfollowedmeuptheladder~150":"“Não o querem a vante!”, disse Montgomery, em voz ameaçadora. “Mas eu lhe digo que vá!” Estava a ponto de dizer mais alguma coisa, mas então ergueu os olhos para mim de repente e subiu a escada atrás de mim.","ihadpausedhalfwaythroughthehatchwaylooki~asionpassedmyimagination~549":"Eu havia parado a meio caminho da escotilha, olhando para trás, ainda assombrado além da medida com a grotesca fealdade daquela criatura de rosto escuro. Nunca vira antes rosto tão repulsivo e extraordinário, e no entanto — se a contradição é crível — experimentei ao mesmo tempo uma estranha sensação de que, de algum modo, já encontrara exatamente aqueles traços e gestos que agora me espantavam. Mais tarde ocorreu-me que provavelmente o vira quando fui içado a bordo; e ainda assim isso mal satisfazia minha suspeita de um conhecimento anterior. Mas como alguém podia ter posto os olhos em rosto tão singular e esquecido a ocasião precisa, escapava à minha imaginação.","montgomerysmovementtofollowmereleasedmya~ndsilentsailoratthewheel~655":"O movimento de Montgomery para me seguir libertou minha atenção, e voltei-me e olhei em redor o convés corrido da pequena escuna. Já estava meio preparado, pelos sons que ouvira, para o que via. Decerto jamais contemplei convés tão sujo. Estava juncado de pedaços de cenoura, fiapos de verdura e imundície indescritível. Presos por correntes ao mastro grande, havia vários cães de caça sinistros, que agora começavam a pular e a ladrar para mim, e junto ao mastro de mezena uma enorme puma estava espremida numa pequena jaula de ferro, pequena demais até para lhe permitir virar-se. Mais adiante, sob a amurada de estibordo, havia umas grandes gaiolas com vários coelhos, e uma lhama solitária estava comprimida numa mera caixa de jaula a vante. Os cães estavam amordaçados com correias de couro. O único ser humano no convés era um marinheiro macilento e silencioso ao leme.","thepatchedanddirtyspankersweretensebefor~unsavourylengthoftheship~356":"As gáveas remendadas e sujas estavam tesas ao vento, e lá no alto o pequeno navio parecia levar todas as velas que possuía. O céu estava limpo, o sol a meio caminho do poente; longas ondas, coroadas de espuma pela brisa, corriam conosco. Passamos pelo timoneiro até a balaustrada da popa e vimos a água vir espumando sob o painel de popa e as bolhas dançarem e sumirem na esteira. Voltei-me e examinei o comprimento pouco asseado do navio.","isthisanoceanmenageriesaidi~hisanoceanmenageriesaidi~27":"“Isto é um zoológico oceânico?”, perguntei.","lookslikeitsaidmontgomery~ookslikeitsaidmontgomery~25":"“Parece que sim”, disse Montgomery.","whatarethesebeastsformerchandisecuriosdo~msomewhereinthesouthseas~99":"“Para que servem estas bestas? Mercadoria, curiosidades? O capitão pensa em vendê-las em algum lugar dos Mares do Sul?”","itlookslikeitdoesntitsaidmontgomeryandtu~urnedtowardsthewakeagain~63":"“Parece, não é?”, disse Montgomery, e voltou-se de novo para a esteira.","suddenlyweheardayelpandavolleyoffuriousb~yorforwardsuponhisvictim~693":"De repente ouvimos um ganido e uma saraivada de blasfêmias furiosas vindas da escotilha do tombadilho, e o homem deformado de rosto escuro subiu apressado. Foi seguido de imediato por um homem pesado, de cabelos ruivos e boné branco. À vista do primeiro, os cães de caça, que a essa altura já tinham se cansado de ladrar para mim, ficaram furiosamente excitados, uivando e saltando contra as correntes. O negro hesitou diante deles, e isso deu ao ruivo tempo de alcançá-lo e desferir-lhe um tremendo golpe entre as omoplatas. O pobre-diabo caiu como um boi abatido e rolou na sujeira entre os cães furiosamente excitados. Foi sorte para ele que estivessem amordaçados. O ruivo soltou um berro de exultação e ficou ali cambaleando, e, a meu ver, em sério perigo de cair de costas pela escotilha ou para a frente sobre a vítima.","sosoonasthesecondmanhadappearedmontgomer~anlaughedasatisfiedlaugh~671":"Assim que o segundo homem apareceu, Montgomery avançara. “Calma aí!”, gritou, em tom de reprovação. Dois marinheiros apareceram no castelo de proa. O homem de rosto escuro, uivando com uma voz singular, rolava sob as patas dos cães. Ninguém tentou ajudá-lo. Os brutos faziam o possível para atormentá-lo, enfiando os focinhos nele. Houve uma rápida dança de seus corpos ágeis, de pelagem cinzenta e malhada, sobre a figura prostrada e desajeitada. Os marinheiros a vante gritavam como se fosse um esporte admirável. Montgomery soltou uma exclamação irada e foi andando a passos largos pelo convés, e eu o segui. O homem de rosto escuro levantou-se aos tropeções e cambaleou para a frente, indo debruçar-se na amurada junto aos ovéns do mastro grande, onde ficou, ofegante, lançando olhares ferozes por cima do ombro para os cães. O ruivo deu uma risada satisfeita.","lookherecaptainsaidmontgomerywithhislisp~heredhairedmanthiswontdo~102":"“Escute, capitão”, disse Montgomery, com o ceceio um pouco acentuado, agarrando os cotovelos do ruivo, “isto não pode ser!”","istoodbehindmontgomerythecaptaincamehalf~oraminuteblastedsawbones~183":"Fiquei atrás de Montgomery. O capitão virou-se meio de lado e o encarou com os olhos baços e solenes de um bêbado. “O que num pode sê?”, disse, e acrescentou, depois de olhar sonolento para o rosto de Montgomery por um minuto: “Maldito açougueiro!”","withasuddenmovementheshookhisarmsfreeand~dfistsintohissidepockets~106":"Com um movimento brusco soltou os braços e, depois de duas tentativas frustradas, enfiou os punhos sardentos nos bolsos laterais.","thatmansapassengersaidmontgomeryidadvise~youtokeepyourhandsoffhim~64":"“Aquele homem é passageiro”, disse Montgomery. “Aconselho-o a ficar com as mãos longe dele.”","gotohellsaidthecaptainloudlyhesuddenlytu~atilikeonmyownshiphesaid~98":"“Vá pro inferno!”, disse o capitão, em voz alta. De repente virou-se e cambaleou em direção à amurada. “Faço o que quero no meu próprio navio”, disse.","ithinkmontgomerymighthavelefthimthenseei~dthecaptaintothebulwarks~118":"Creio que Montgomery poderia tê-lo deixado ali, vendo que o bruto estava bêbado; mas apenas empalideceu um tom e seguiu o capitão até a amurada.","lookyouherecaptainhesaidthatmanofmineisn~zedeversincehecameaboard~91":"“Escute bem, capitão”, disse ele; “aquele meu homem não deve ser maltratado. Tem sido atormentado desde que subiu a bordo.”","foraminutealcoholicfumeskeptthecaptainsp~allheconsiderednecessary~90":"Por um minuto, os eflúvios do álcool deixaram o capitão sem fala. “Maldito açougueiro!” foi tudo o que julgou necessário.","icouldseethatmontgomeryhadoneofthoseslow~officiouslyyoulldonogood~219":"Pude ver que Montgomery tinha um desses temperamentos lentos e pertinazes que se aquecem dia após dia até o rubro-branco e nunca mais esfriam até o perdão; e vi também que aquela briga vinha crescendo havia algum tempo. “O homem está bêbado”, disse eu, talvez com excesso de zelo; “o senhor não vai conseguir nada.”","montgomerygaveanuglytwisttohisdroppingli~sassaultinghispassengers~102":"Montgomery deu uma torção feia ao lábio caído. “Está sempre bêbado. Acha que isso desculpa ele agredir os passageiros?”","myshipbeganthecaptainwavinghishandunstea~taincleanrespectablecrew~156":"“Meu navio”, começou o capitão, agitando a mão vacilante em direção às jaulas, “era um navio limpo. Olhe só agora!” Certamente estava longe de ser limpo. “Tripulação”, prosseguiu o capitão, “tripulação limpa, respeitável.”","youagreedtotakethebeasts~youagreedtotakethebeasts~24":"“O senhor concordou em levar os bichos.”","iwishidneverseteyesonyourinfernalislandw~ledamnedshipbelongstoyou~193":"“Quisera nunca ter posto os olhos nessa sua ilha infernal. Pra que diabos — quer bichos numa ilha dessas? E aquele seu homem — achei que era um homem. É um lunático; e não tinha nada que andar a ré. Pensa que o maldito navio inteiro é seu?”","yoursailorsbegantohazethepoordevilassoon~evilassoonashecameaboard~54":"“Seus marinheiros começaram a atormentar o pobre-diabo assim que ele subiu a bordo.”","thatsjustwhatheishesadevilanuglydevilmym~cantstandhimnoryoueither~99":"“É isso mesmo que ele é — um diabo! um diabo feio! Meus homens não o suportam. Eu não o suporto. Nenhum de nós o suporta. Nem o senhor!”","montgomeryturnedawayyouleavethatmanalone~dnoddinghisheadashespoke~75":"Montgomery virou-se. “Deixe aquele homem em paz, em todo caso”, disse, balançando a cabeça ao falar.","butthecaptainmeanttoquarrelnowheraisedhi~ddevilandasillysawbonesa~356":"Mas o capitão agora queria briga. Levantou a voz. “Se ele vier a esta ponta do navio outra vez, eu lhe arranco as tripas, estou lhe dizendo. Arranco suas malditas tripas! Quem é o senhor pra me dizer o que devo fazer? Estou lhe dizendo que sou o capitão deste navio — capitão e dono. Aqui a lei sou eu, estou lhe dizendo — a lei e os profetas. Combinei levar um homem e seu criado de ida e volta de Arica e trazer uns animais. Nunca combinei carregar um diabo louco e um açougueiro idiota, um...”","wellnevermindwhathecalledmontgomeryisawt~oughtthedownpouronmyself~239":"Bem, não importa como chamou Montgomery. Vi este dar um passo à frente e interpus-me. “Ele está bêbado”, disse eu. O capitão começou um insulto ainda mais sujo que o anterior. “Cale a boca!”, disse eu, voltando-me bruscamente para ele, pois vira perigo no rosto branco de Montgomery. Com isso, trouxe a chuva torrencial para cima de mim.","howeveriwasgladtoavertwhatwasuncommonlyn~tanyrateipreventedafight~531":"Seja como for, fiquei contente de evitar o que esteve extraordinariamente perto de uma briga, mesmo ao preço da má vontade do capitão bêbado. Não creio ter ouvido jamais tanta linguagem vil em fluxo contínuo dos lábios de um homem, embora eu tenha frequentado companhias excêntricas bastante. Achei parte daquilo difícil de suportar, embora seja homem de gênio brando; mas, decerto, quando mandei o capitão “calar a boca”, esquecera que não passava de um pedaço de destroço humano, cortado de meus recursos e com a passagem por pagar; um mero dependente casual da generosidade, ou da empresa especulativa, do navio. Ele me lembrou disso com considerável vigor; mas, em todo caso, impedi uma luta."}$tr$::jsonb, 67)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- h-g-wells_the-time-machine (115 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('h-g-wells_the-time-machine', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"chapteri":"Capítulo I","chapterii":"Capítulo II","chapteriii":"Capítulo III"}$tr$::jsonb, $tr${"thetimetravellerforsoitwillbeconvenientt~thoughtitandhisfecundity~597":"O Viajante do Tempo (pois assim será conveniente referir-se a ele) expunha-nos um assunto recôndito. Seus olhos cinzentos brilhavam e cintilavam, e seu rosto, geralmente pálido, estava corado e animado. O fogo ardia vivamente, e o suave fulgor das lâmpadas incandescentes, nos lírios de prata, apanhava as bolhas que cintilavam e passavam em nossas taças. Nossas poltronas, sendo patentes dele, abraçavam-nos e acariciavam-nos em vez de se submeterem a que nos sentássemos nelas, e havia aquela atmosfera luxuosa de depois do jantar em que o pensamento vagueia, graciosamente livre das peias da precisão. E ele nos expôs a questão assim — marcando os pontos com um indicador magro — enquanto nos sentávamos, a admirar preguiçosamente seu fervor diante daquele novo paradoxo (como o julgávamos) e sua fecundidade.","youmustfollowmecarefullyishallhavetocont~sfoundedonamisconception~159":"“Precisam acompanhar-me com atenção. Terei de contestar uma ou duas ideias quase universalmente aceitas. A geometria, por exemplo, que lhes ensinaram na escola, funda-se num equívoco.”","isnotthatratheralargethingtoexpectustobe~ntativepersonwithredhair~88":"“Não é um pouco demais esperar que comecemos por aí?”, disse Filby, pessoa argumentadora e de cabelos ruivos.","idonotmeantoaskyoutoacceptanythingwithou~hingsaremereabstractions~246":"“Não pretendo pedir que aceitem coisa alguma sem fundamento razoável. Logo admitirão tudo o que preciso de vocês. Sabem, naturalmente, que uma linha matemática, uma linha de espessura nula, não tem existência real. Isso lhes ensinaram? Tampouco tem um plano matemático. Essas coisas são meras abstrações.”","thatisallrightsaidthepsychologist~rightsaidthepsychologist~33":"“Até aí tudo bem”, disse o Psicólogo.","norhavingonlylengthbreadthandthicknessca~nacubehavearealexistence~64":"“Nem, tendo apenas comprimento, largura e espessura, pode um cubo ter existência real.”","thereiobjectsaidfilbyofcourseasolidbodym~odymayexistallrealthings~60":"“Aí eu discordo”, disse Filby. “É claro que um corpo sólido pode existir. Todas as coisas reais...”","somostpeoplethinkbutwaitamomentcananinst~aninstantaneouscubeexist~58":"“É o que a maioria pensa. Mas esperem um momento. Pode um cubo instantâneo existir?”","dontfollowyousaidfilby~dontfollowyousaidfilby~22":"“Não o acompanho”, disse Filby.","canacubethatdoesnotlastforanytimeatallha~eatallhavearealexistence~56":"“Pode um cubo que não dura tempo algum ter existência real?”","filbybecamepensiveclearlythetimetravelle~inningtotheendofourlives~519":"Filby ficou pensativo. “Evidentemente”, prosseguiu o Viajante do Tempo, “todo corpo real deve ter extensão em quatro direções: deve ter Comprimento, Largura, Espessura e... Duração. Mas por uma enfermidade natural da carne, que lhes explicarei em um momento, tendemos a ignorar esse fato. Existem realmente quatro dimensões, três que chamamos os três planos do Espaço, e uma quarta, o Tempo. Há, contudo, uma tendência a traçar uma distinção irreal entre as três primeiras dimensões e a última, porque acontece que nossa consciência se move de modo intermitente numa só direção ao longo desta, do começo ao fim de nossas vidas.”","thatsaidaveryyoungmanmakingspasmodiceffo~elampthatveryclearindeed~90":"“Isso”, disse um rapaz muito jovem, fazendo esforços espasmódicos para reacender o charuto na lâmpada; “isso... muito claro, de fato.”","nowitisveryremarkablethatthisissoextensi~aboutthisfourthdimension~466":"“Ora, é muito notável que isso seja tão amplamente ignorado”, continuou o Viajante do Tempo, com um leve acréscimo de bom humor. “É realmente isso o que se entende por Quarta Dimensão, embora algumas pessoas que falam da Quarta Dimensão não saibam que é isso que querem dizer. É apenas outra maneira de encarar o Tempo. Não há diferença entre o Tempo e qualquer das três dimensões do Espaço, exceto que nossa consciência se move ao longo dele. Mas algumas pessoas tolas pegaram a ideia pelo lado errado. Todos vocês já ouviram o que elas têm a dizer sobre essa Quarta Dimensão?”","ihavenotsaidtheprovincialmayor~otsaidtheprovincialmayor~30":"“Eu não”, disse o Prefeito da província.","itissimplythisthatspaceasourmathematicia~perspectiveofthethingsee~663":"“É simplesmente isto. Que o Espaço, como o apresentam nossos matemáticos, é descrito como tendo três dimensões, que se podem chamar Comprimento, Largura e Espessura, e é sempre definível por referência a três planos, cada um em ângulo reto com os outros. Mas alguns filósofos vêm perguntando por que precisamente três dimensões — por que não outra direção em ângulo reto com as três outras? — e chegaram a tentar construir uma geometria de Quatro Dimensões. O professor Simon Newcomb expunha isso à Sociedade Matemática de Nova York há apenas um mês, mais ou menos. Sabem como, numa superfície plana, que tem apenas duas dimensões, podemos representar a figura de um sólido de três dimensões; do mesmo modo, eles pensam que, por modelos de três dimensões, poderiam representar um de quatro — se conseguissem dominar a perspectiva da coisa. Entendem?”","ithinksomurmuredtheprovincialmayorandkni~inaquitetransitorymanner~196":"“Acho que sim”, murmurou o Prefeito da Província; e, franzindo o cenho, mergulhou num estado introspectivo, os lábios se movendo como os de quem repete palavras místicas. “Sim, acho que agora estou vendo”, disse ao cabo de algum tempo, animando-se de maneira bastante passageira.","wellidonotmindtellingyouihavebeenatworku~fixedandunalterablething~339":"“Pois bem, não me importo de dizer que venho trabalhando nesta geometria de Quatro Dimensões há algum tempo. Alguns de meus resultados são curiosos. Por exemplo, aqui está o retrato de um homem aos oito anos, outro aos quinze, outro aos dezessete, outro aos vinte e três, e assim por diante. Todos estes são evidentemente seções, por assim dizer, representações Tridimensionais do seu ser Quadridimensional, que é uma coisa fixa e inalterável.","scientificpeopleproceededthetimetravelle~wasalongthetimedimension~488":"“Os cientistas”, prosseguiu o Viajante do Tempo, depois da pausa necessária para a devida assimilação disso, “sabem muito bem que o Tempo é apenas uma espécie de Espaço. Eis um diagrama científico popular, um registro do tempo. Esta linha que traço com o dedo mostra o movimento do barômetro. Ontem estava tão alto, ontem à noite caiu, depois esta manhã subiu de novo, e assim suavemente para cima até aqui. Decerto o mercúrio não traçou esta linha em nenhuma das dimensões do Espaço geralmente reconhecidas? Mas certamente traçou tal linha, e essa linha, portanto, devemos concluir que se deu ao longo da Dimensão do Tempo.”","butsaidthemedicalmanstaringhardatacoalin~heotherdimensionsofspace~208":"“Mas”, disse o Médico, fitando duramente um carvão no fogo, “se o Tempo é realmente apenas uma quarta dimensão do Espaço, por que é, e por que sempre foi, considerado algo diferente? E por que não podemos nos mover no Tempo como nos movemos nas outras dimensões do Espaço?”","thetimetravellersmiledareyousurewecanmov~gravitationlimitsusthere~202":"O Viajante do Tempo sorriu. “Tem certeza de que podemos nos mover livremente no Espaço? Para a direita e para a esquerda podemos ir, para trás e para a frente com bastante liberdade, e os homens sempre o fizeram. Admito que nos movemos livremente em duas dimensões. Mas e quanto a para cima e para baixo? A gravitação nos limita aí.”","notexactlysaidthemedicalmanthereareballo~dicalmanthereareballoons~43":"“Não exatamente”, disse o Médico. “Existem os balões.”","butbeforetheballoonssaveforspasmodicjump~reedomofverticalmovement~106":"“Mas antes dos balões, salvo por saltos espasmódicos e as irregularidades da superfície, o homem não tinha liberdade de movimento vertical.”","stilltheycouldmovealittleupanddownsaidth~anddownsaidthemedicalman~51":"“Ainda assim podiam se mover um pouco para cima e para baixo”, disse o Médico.","easierfareasierdownthanup~asierfareasierdownthanup~25":"“Mais fácil, muito mais fácil para baixo do que para cima.”","andyoucannotmoveatallintimeyoucannotgeta~awayfromthepresentmoment~63":"“E o senhor não pode se mover de modo algum no Tempo, não pode escapar do momento presente.”","mydearsirthatisjustwhereyouarewrongthati~lesabovetheearthssurface~323":"“Meu caro senhor, é justamente aí que o senhor se engana. É justamente aí que o mundo inteiro se enganou. Estamos sempre nos afastando do momento presente. Nossas existências mentais, que são imateriais e não têm dimensões, passam ao longo da Dimensão do Tempo com velocidade uniforme do berço ao túmulo. Assim como viajaríamos para baixo se começássemos nossa existência a oitenta quilômetros acima da superfície da terra.”","butthegreatdifficultyisthisinterruptedth~youcannotmoveaboutintime~117":"“Mas a grande dificuldade é esta”, interrompeu o Psicólogo. “O senhor pode se mover em todas as direções do Espaço, mas não pode se mover no Tempo.”","thatisthegermofmygreatdiscoverybutyouare~boutandtraveltheotherway~534":"“Esse é o germe da minha grande descoberta. Mas o senhor se engana ao dizer que não podemos nos mover no Tempo. Por exemplo, se estou recordando um incidente com muita vivacidade, volto ao instante em que ocorreu: fico distraído, como se diz. Salto para trás por um momento. Claro que não temos meios de permanecer lá atrás por qualquer duração de Tempo, assim como um selvagem ou um animal não tem meios de permanecer a dois metros acima do chão. Mas o homem civilizado está em melhor situação que o selvagem a esse respeito. Pode subir contra a gravitação num balão, e por que não esperaria que, por fim, possa deter ou acelerar sua deriva ao longo da Dimensão do Tempo, ou até virar-se e viajar no outro sentido?”","ohthisbeganfilbyisall~ohthisbeganfilbyisall~21":"“Oh, isso”, começou Filby, “é tudo...”","whynotsaidthetimetraveller~ynotsaidthetimetraveller~26":"“Por que não?”, disse o Viajante do Tempo.","itsagainstreasonsaidfilby~tsagainstreasonsaidfilby~25":"“É contra a razão”, disse Filby.","whatreasonsaidthetimetraveller~asonsaidthetimetraveller~30":"“Que razão?”, disse o Viajante do Tempo.","youcanshowblackiswhitebyargumentsaidfilb~utyouwillneverconvinceme~66":"“O senhor pode mostrar por argumentos que o preto é branco”, disse Filby, “mas nunca me convencerá.”","possiblynotsaidthetimetravellerbutnowyou~davagueinklingofamachine~142":"“Possivelmente não”, disse o Viajante do Tempo. “Mas agora começa a ver o objetivo de minhas investigações sobre a geometria de Quatro Dimensões. Há muito tempo tive uma vaga ideia de uma máquina...”","totravelthroughtimeexclaimedtheveryyoung~exclaimedtheveryyoungman~43":"“Para viajar através do Tempo!”, exclamou o Rapaz Muito Jovem.","thatshalltravelindifferentlyinanydirecti~imeasthedriverdetermines~77":"“Que viaje indiferentemente em qualquer direção do Espaço e do Tempo, conforme o condutor determine.”","filbycontentedhimselfwithlaughter~entedhimselfwithlaughter~33":"Filby contentou-se com o riso.","butihaveexperimentalverificationsaidthet~tionsaidthetimetraveller~52":"“Mas eu tenho verificação experimental”, disse o Viajante do Tempo.","itwouldberemarkablyconvenientforthehisto~tleofhastingsforinstance~145":"“Seria notavelmente conveniente para o historiador”, sugeriu o Psicólogo. “Poder-se-ia viajar para trás e verificar o relato aceito da Batalha de Hastings, por exemplo!”","dontyouthinkyouwouldattractattentionsaid~toleranceforanachronisms~99":"“Não acha que chamaria a atenção?”, disse o Médico. “Nossos ancestrais não tinham grande tolerância com anacronismos.”","onemightgetonesgreekfromtheverylipsofhom~totheveryyoungmanthought~72":"“Poder-se-ia aprender o grego dos próprios lábios de Homero e Platão”, pensou o Rapaz Muito Jovem.","inwhichcasetheywouldcertainlyploughyoufo~shaveimprovedgreeksomuch~92":"“Caso em que certamente o reprovariam no Little-go. Os eruditos alemães melhoraram tanto o grego.”","thenthereisthefuturesaidtheveryyoungmanj~tinterestandhurryonahead~118":"“E há ainda o futuro”, disse o Rapaz Muito Jovem. “Pensem só! Poder-se-ia investir todo o dinheiro, deixá-lo acumular juros e correr adiante!”","todiscoverasocietysaidierectedonastrictl~strictlycommunisticbasis~57":"“Para descobrir uma sociedade”, disse eu, “erigida sobre uma base estritamente comunista.”","ofallthewildextravaganttheoriesbeganthep~riesbeganthepsychologist~51":"“De todas as teorias extravagantes e desvairadas!”, começou o Psicólogo.","yessoitseemedtomeandsoinevertalkedofitun~dsoinevertalkedofituntil~43":"“Sim, assim me pareceu, e por isso nunca falei disso até que...”","experimentalverificationcriediyouaregoin~iyouaregoingtoverifythat~53":"“Verificação experimental!”, exclamei. “O senhor vai verificar isso?”","theexperimentcriedfilbywhowasgettingbrai~ywhowasgettingbrainweary~46":"“O experimento!”, gritou Filby, que estava ficando cansado de pensar.","letsseeyourexperimentanyhowsaidthepsycho~houghitsallhumbugyouknow~71":"“Vejamos seu experimento de qualquer modo”, disse o Psicólogo, “embora seja tudo uma farsa, sabe.”","thetimetravellersmiledroundatusthenstill~ngpassagetohislaboratory~182":"O Viajante do Tempo sorriu para todos nós. Depois, ainda sorrindo levemente, e com as mãos enfiadas fundo nos bolsos das calças, saiu lentamente da sala, e ouvimos suas pantufas arrastando-se pelo longo corredor até o laboratório.","thepsychologistlookedatusiwonderwhathesg~kedatusiwonderwhathesgot~42":"O Psicólogo olhou para nós. “Que será que ele tem?”","somesleightofhandtrickorothersaidthemedi~dfilbysanecdotecollapsed~181":"“Algum truque de prestidigitação ou outro”, disse o Médico, e Filby tentou nos contar sobre um ilusionista que vira em Burslem; mas antes que terminasse o prefácio o Viajante do Tempo voltou, e a anedota de Filby desmoronou.","thethingthetimetravellerheldinhishandwas~onusundertheseconditions~1086":"A coisa que o Viajante do Tempo segurava na mão era uma armação metálica reluzente, pouco maior que um pequeno relógio, e muito delicadamente feita. Havia marfim nela, e alguma substância cristalina transparente. E agora devo ser explícito, pois o que se segue — a menos que sua explicação seja aceita — é absolutamente inexplicável. Ele pegou uma das pequenas mesas octogonais que estavam espalhadas pela sala e a pôs diante do fogo, com duas pernas sobre o tapete da lareira. Sobre essa mesa colocou o mecanismo. Depois puxou uma cadeira e sentou-se. O único outro objeto sobre a mesa era um pequeno lampião com quebra-luz, cuja luz brilhante caía sobre o modelo. Havia também talvez uma dúzia de velas em torno, duas em castiçais de latão sobre a cornija e várias em arandelas, de modo que a sala estava brilhantemente iluminada. Sentei-me numa poltrona baixa, a mais próxima do fogo, e puxei-a para a frente, de modo a ficar quase entre o Viajante do Tempo e a lareira. Filby sentou-se atrás dele, olhando por cima de seu ombro. O Médico e o Prefeito da Província o observavam de perfil, pela direita, o Psicólogo pela esquerda. O Rapaz Muito Jovem estava de pé atrás do Psicólogo. Estávamos todos alertas. Parece-me incrível que qualquer espécie de truque, por mais sutilmente concebido e habilmente executado, pudesse ter sido pregado em nós nessas condições.","thetimetravellerlookedatusandthenattheme~mwellsaidthepsychologist~70":"O Viajante do Tempo olhou para nós, e depois para o mecanismo. “Então?”, disse o Psicólogo.","thislittleaffairsaidthetimetravellerrest~iteleverandhereisanother~353":"“Esta pequena engenhoca”, disse o Viajante do Tempo, apoiando os cotovelos na mesa e juntando as mãos acima do aparelho, “é apenas um modelo. É o meu plano de uma máquina para viajar através do tempo. Notarão que parece singularmente torta, e que há uma estranha aparência cintilante nesta barra, como se fosse de algum modo irreal.” Apontou a peça com o dedo. “Aqui também há uma pequena alavanca branca, e aqui outra.”","themedicalmangotupoutofhischairandpeered~itsbeautifullymadehesaid~76":"O Médico levantou-se da cadeira e espiou dentro da coisa. “É lindamente feita”, disse.","ittooktwoyearstomakeretortedthetimetrave~delandthenbetoldimaquack~483":"“Levou dois anos para fazer”, retrucou o Viajante do Tempo. Depois, quando todos imitamos a ação do Médico, disse: “Agora quero que entendam claramente que esta alavanca, quando empurrada, faz a máquina deslizar para o futuro, e esta outra inverte o movimento. Este selim representa o assento de um viajante do tempo. Daqui a pouco vou apertar a alavanca, e lá se vai a máquina. Vai desvanecer, passar para o Tempo futuro e desaparecer. Examinem bem a coisa. Olhem também a mesa, e convençam-se de que não há trapaça. Não quero desperdiçar este modelo e depois ouvir que sou um charlatão.”","therewasaminutespauseperhapsthepsycholog~orthelampthetablewasbare~653":"Houve talvez um minuto de pausa. O Psicólogo pareceu prestes a falar comigo, mas mudou de ideia. Então o Viajante do Tempo estendeu o dedo em direção à alavanca. “Não”, disse de repente. “Empreste-me sua mão.” E, voltando-se para o Psicólogo, tomou a mão dele na sua e mandou que estendesse o indicador. De modo que foi o próprio Psicólogo quem enviou o modelo de Máquina do Tempo em sua interminável viagem. Todos vimos a alavanca girar. Estou absolutamente certo de que não houve trapaça. Houve um sopro de vento, e a chama do lampião deu um salto. Uma das velas sobre a cornija foi apagada, e a pequena máquina de repente girou, tornou-se indistinta, foi vista como um fantasma por um segundo talvez, como um redemoinho de latão e marfim fracamente cintilante; e sumiu — desvaneceu! Salvo o lampião, a mesa estava vazia.","everyonewassilentforaminutethenfilbysaid~thenfilbysaidhewasdamned~51":"Todos ficaram em silêncio por um minuto. Então Filby disse que estava pasmo.","thepsychologistrecoveredfromhisstuporand~cktousbegantofillhispipe~231":"O Psicólogo recobrou-se do estupor e olhou de repente debaixo da mesa. Ante isso, o Viajante do Tempo riu alegremente. “Então?”, disse, numa reminiscência do Psicólogo. Depois, levantando-se, foi ao pote de tabaco sobre a cornija e, de costas para nós, começou a encher o cachimbo.","westaredateachotherlookheresaidthemedica~hinehastravelledintotime~124":"Encaramo-nos. “Escute”, disse o Médico, “o senhor fala sério sobre isto? Acredita realmente que aquela máquina viajou no tempo?”","certainlysaidthetimetravellerstoopingtol~veajourneyonmyownaccount~326":"“Certamente”, disse o Viajante do Tempo, curvando-se para acender uma tira de papel no fogo. Depois virou-se, acendendo o cachimbo, para olhar o rosto do Psicólogo. (O Psicólogo, para mostrar que não estava desequilibrado, serviu-se de um charuto e tentou acendê-lo sem cortar a ponta.) “Mais ainda, tenho uma grande máquina quase pronta ali dentro” — indicou o laboratório — “e quando estiver montada pretendo fazer uma viagem por minha conta.”","youmeantosaythatthatmachinehastravelledi~edintothefuturesaidfilby~61":"“Quer dizer que aquela máquina viajou para o futuro?”, disse Filby.","intothefutureorthepastidontforcertainkno~idontforcertainknowwhich~46":"“Para o futuro ou para o passado — não sei ao certo qual.”","afteranintervalthepsychologisthadaninspi~fithasgoneanywherehesaid~96":"Após um intervalo, o Psicólogo teve uma inspiração. “Deve ter ido para o passado, se é que foi a algum lugar”, disse.","whysaidthetimetraveller~whysaidthetimetraveller~23":"“Por quê?”, disse o Viajante do Tempo.","becauseipresumethatithasnotmovedinspacea~travelledthroughthistime~136":"“Porque presumo que não se moveu no espaço, e se viajasse para o futuro ainda estaria aqui todo este tempo, já que teria de viajar através deste tempo.”","butisaidifittravelledintothepastitwouldh~sdaybeforethatandsoforth~144":"“Mas”, disse eu, “se viajasse para o passado, teria sido visível quando entramos pela primeira vez nesta sala; e na quinta-feira passada, quando estivemos aqui; e na quinta-feira anterior; e assim por diante!”","seriousobjectionsremarkedtheprovincialma~gtowardsthetimetraveller~96":"“Objeções sérias”, observou o Prefeito da Província, com ar de imparcialidade, voltando-se para o Viajante do Tempo.","notabitsaidthetimetravellerandtothepsych~uknowdilutedpresentation~130":"“Nem um pouco”, disse o Viajante do Tempo, e, ao Psicólogo: “O senhor pensa. Pode explicar isso. É apresentação abaixo do limiar, sabe, apresentação diluída.”","ofcoursesaidthepsychologistandreassuredu~beenyouseehesaidlaughing~558":"“Claro”, disse o Psicólogo, e tranquilizou-nos. “É um ponto simples de psicologia. Eu devia ter pensado nisso. É bem claro, e ajuda deliciosamente o paradoxo. Não podemos vê-la, nem apreciar esta máquina, assim como não podemos ver o raio de uma roda girando, ou uma bala voando pelo ar. Se ela viaja através do tempo cinquenta ou cem vezes mais depressa do que nós, se atravessa um minuto enquanto nós atravessamos um segundo, a impressão que cria será, claro, apenas um cinquentavo ou um centésimo da que causaria se não viajasse no tempo. Isso é bem claro.” Passou a mão pelo espaço em que estivera a máquina. “Veem?”, disse, rindo.","wesatandstaredatthevacanttableforaminute~eduswhatwethoughtofitall~91":"Ficamos sentados fitando a mesa vazia por um minuto ou pouco mais. Então o Viajante do Tempo nos perguntou o que achávamos de tudo aquilo.","itsoundsplausibleenoughtonightsaidthemed~ecommonsenseofthemorning~100":"“Parece bastante plausível esta noite”, disse o Médico; “mas espere até amanhã. Espere o bom senso da manhã.”","wouldyouliketoseethetimemachineitselfask~okatitquartzitseemedtobe~606":"“Gostariam de ver a própria Máquina do Tempo?”, perguntou o Viajante do Tempo. E com isso, tomando o lampião na mão, guiou-nos pelo longo corredor ventoso até o laboratório. Lembro-me vivamente da luz bruxuleante, de sua estranha cabeça larga em silhueta, da dança das sombras, de como todos o seguimos, intrigados mas incrédulos, e de como ali no laboratório contemplamos uma edição maior do pequeno mecanismo que tínhamos visto desaparecer diante de nossos olhos. Partes eram de níquel, partes de marfim, partes certamente tinham sido limadas ou serradas em cristal de rocha. A coisa estava de modo geral completa, mas as barras cristalinas retorcidas jaziam inacabadas sobre a bancada ao lado de algumas folhas de desenhos, e peguei uma para olhá-la melhor. Parecia ser quartzo.","lookheresaidthemedicalmanareyouperfectly~youshoweduslastchristmas~98":"“Escute”, disse o Médico, “o senhor está perfeitamente sério? Ou é um truque — como aquele fantasma que nos mostrou no último Natal?”","uponthatmachinesaidthetimetravellerholdi~nevermoreseriousinmylife~113":"“Com aquela máquina”, disse o Viajante do Tempo, erguendo o lampião, “pretendo explorar o tempo. Está claro? Nunca falei tão a sério em minha vida.”","noneofusquiteknewhowtotakeit~ofusquiteknewhowtotakeit~28":"Nenhum de nós soube bem como tomar aquilo.","icaughtfilbyseyeovertheshoulderofthemedi~nandhewinkedatmesolemnly~69":"Cruzei o olhar com o de Filby por cima do ombro do Médico, e ele piscou-me solenemente.","ithinkthatatthattimenoneofusquitebelieve~wasdonehecouldnotexplain~1272":"Creio que, naquela época, nenhum de nós acreditava de fato na Máquina do Tempo. O fato é que o Viajante do Tempo era um desses homens inteligentes demais para serem acreditados: nunca se tinha a sensação de enxergá-lo por inteiro; suspeitava-se sempre de alguma sutil reserva, alguma engenhosidade emboscada, por trás de sua lúcida franqueza. Se Filby tivesse mostrado o modelo e explicado o assunto nas palavras do Viajante do Tempo, teríamos demonstrado muito menos ceticismo. Pois teríamos percebido seus motivos; um açougueiro entenderia Filby. Mas o Viajante do Tempo tinha mais que um toque de capricho entre seus elementos, e desconfiávamos dele. Coisas que, nas mãos de um homem menos inteligente, teriam parecido uma estrutura sólida, pareciam truques nas dele. É um erro fazer as coisas com facilidade demais. As pessoas sérias que o levavam a sério nunca se sentiam bem seguras de seu comportamento; de algum modo percebiam que confiar-lhe sua reputação de discernimento era como mobiliar um quarto de crianças com porcelana de casca de ovo. Assim, não creio que algum de nós tenha falado muito sobre viagem no tempo no intervalo entre aquela quinta-feira e a seguinte, embora suas estranhas potencialidades corressem, sem dúvida, pela cabeça da maioria: sua plausibilidade, isto é, sua incredibilidade prática, as curiosas possibilidades de anacronismo e de total confusão que sugeria. De minha parte, eu estava particularmente preocupado com o truque do modelo. Disso me lembro de discutir com o Médico, que encontrei na sexta-feira na Sociedade Linneana. Disse que vira coisa semelhante em Tübingen, e deu considerável ênfase ao apagar da vela. Mas como o truque era feito, não soube explicar.","thenextthursdayiwentagaintorichmondisupp~pposewedbetterhavedinner~333":"Na quinta-feira seguinte fui outra vez a Richmond — suponho que eu era um dos convidados mais assíduos do Viajante do Tempo — e, chegando tarde, encontrei quatro ou cinco homens já reunidos em sua sala de estar. O Médico estava de pé diante do fogo, com uma folha de papel numa mão e o relógio na outra. Olhei em volta à procura do Viajante do Tempo, e — “São sete e meia agora”, disse o Médico. “Suponho que é melhor jantarmos?”","wheressaidinamingourhost~wheressaidinamingourhost~24":"“Onde está...?”, disse eu, nomeando nosso anfitrião.","youvejustcomeitsratheroddhesunavoidablyd~yshellexplainwhenhecomes~129":"“O senhor acabou de chegar? É bastante estranho. Foi retido inevitavelmente. Pede-me neste bilhete que comece o jantar às sete se ele não tiver voltado. Diz que explicará quando vier.”","itseemsapitytoletthedinnerspoilsaidtheed~uponthedoctorrangthebell~98":"“Seria pena deixar o jantar estragar”, disse o Editor de um conhecido jornal diário; e então o Doutor tocou a campainha.","thepsychologistwastheonlypersonbesidesth~efulturnedtowardsthedoor~800":"O Psicólogo era a única pessoa além do Doutor e de mim que comparecera ao jantar anterior. Os outros homens eram Blank, o Editor já mencionado, um certo jornalista, e outro — um homem quieto e tímido, de barba — que eu não conhecia e que, até onde alcançou minha observação, nunca abriu a boca a noite inteira. Houve alguma especulação à mesa sobre a ausência do Viajante do Tempo, e sugeri viagem no tempo, em espírito meio jocoso. O Editor quis que lhe explicassem aquilo, e o Psicólogo ofereceu-se para fazer um relato truncado do “engenhoso paradoxo e truque” a que assistíramos naquele dia, oito dias antes. Estava no meio da exposição quando a porta do corredor se abriu devagar e sem ruído. Eu estava de frente para a porta e vi primeiro. “Olá!”, disse. “Finalmente!” E a porta se abriu mais, e o Viajante do Tempo estava diante de nós. Dei um grito de surpresa. “Santo Deus! homem, o que aconteceu?”, exclamou o Médico, que o viu em seguida. E a mesa inteira voltou-se para a porta.","hewasinanamazingplighthiscoatwasdustyand~lenceexpectinghimtospeak~459":"Estava num estado assombroso. O casaco estava empoeirado e sujo, e manchado de verde ao longo das mangas; os cabelos desordenados e, a meu ver, mais grisalhos — ou de poeira e sujeira ou porque a cor realmente desbotara. O rosto estava de uma palidez medonha; o queixo tinha um corte marrom — um corte meio cicatrizado; a expressão era macilenta e contraída, como de intenso sofrimento. Por um momento hesitou à porta, como se tivesse sido ofuscado pela luz. Depois entrou na sala. Caminhava com exatamente o tipo de claudicação que vi em vagabundos de pés feridos. Encaramo-lo em silêncio, esperando que falasse.","hesaidnotawordbutcamepainfullytothetable~nimstarvingforabitofmeat~735":"Não disse palavra, mas veio penosamente até a mesa e fez um gesto em direção ao vinho. O Editor encheu uma taça de champanhe e empurrou-a para ele. Ele a esvaziou, e pareceu fazer-lhe bem: pois olhou em volta da mesa, e o fantasma de seu velho sorriso tremulou em seu rosto. “Que diabo andou fazendo, homem?”, disse o Doutor. O Viajante do Tempo não pareceu ouvir. “Não deixem que eu os perturbe”, disse, com certa articulação hesitante. “Estou bem.” Parou, estendeu a taça para mais e a bebeu de um trago. “Está bom”, disse. Os olhos ficaram mais brilhantes e uma tênue cor veio-lhe às faces. Seu olhar passou por nossos rostos com certa aprovação surda e depois percorreu a sala quente e confortável. Então falou de novo, ainda como que tateando o caminho entre as palavras. “Vou me lavar e me vestir, e depois desço e explico as coisas… Guardem-me um pouco daquele carneiro. Estou morrendo de fome por um pedaço de carne.”","helookedacrossattheeditorwhowasararevisi~funnybeallrightinaminute~149":"Olhou para o Editor, que era visita rara, e esperou que estivesse bem. O Editor começou uma pergunta. “Conto daqui a pouco”, disse o Viajante do Tempo. “Estou... esquisito! Passa num minuto.”","heputdownhisglassandwalkedtowardsthestai~cktothebrightdinnertable~480":"Pôs a taça sobre a mesa e caminhou em direção à porta da escada. Notei de novo a sua claudicação e o som macio e abafado de seus passos e, levantando-me em meu lugar, vi os pés dele ao sair. Não tinha nada neles a não ser um par de meias esfarrapadas e manchadas de sangue. Então a porta fechou-se atrás dele. Tive meio ímpeto de segui-lo, até lembrar como ele detestava qualquer alvoroço a seu respeito. Por um minuto, talvez, minha mente ficou a vaguear. Então, “Comportamento Notável de um Eminente Cientista”, ouvi o Editor dizer, pensando (como de costume) em manchetes. E isso trouxe minha atenção de volta à mesa de jantar iluminada.","whatsthegamesaidthejournalisthashebeendo~lsehadnoticedhislameness~223":"“Qual é o jogo?”, disse o Jornalista. “Andou fazendo o Mendigo Amador? Não acompanho.” Encontrei o olhar do Psicólogo e li em seu rosto a minha própria interpretação. Pensei no Viajante do Tempo subindo penosamente a escada, mancando. Não creio que mais alguém tivesse notado a claudicação dele.","thefirsttorecovercompletelyfromthissurpr~echangethathadstartledme~1129":"O primeiro a se recuperar inteiramente da surpresa foi o Médico, que tocou a campainha — o Viajante do Tempo detestava ter criados esperando durante o jantar — pedindo um prato quente. Ante isso o Editor voltou-se para a faca e o garfo com um grunhido, e o Homem Silencioso o imitou. O jantar foi retomado. A conversa foi exclamativa por algum tempo, com lacunas de pasmo; e então o Editor tornou-se fervoroso em sua curiosidade. “Será que nosso amigo complementa a modesta renda com uma varrição de ruas? Ou tem suas fases de Nabucodonosor?”, indagou. “Tenho certeza de que é esta história da Máquina do Tempo”, disse eu, e retomei o relato do Psicólogo sobre nosso encontro anterior. Os novos convidados eram francamente incrédulos. O Editor levantou objeções. “Que história era essa de viagem no tempo? Um homem não poderia cobrir-se de pó rolando num paradoxo, poderia?” E então, à medida que a ideia lhe calava, recorreu à caricatura. Não tinham escovas de roupa no Futuro? O Jornalista também não acreditava a preço nenhum, e juntou-se ao Editor na tarefa fácil de cobrir de ridículo a coisa toda. Ambos eram o novo tipo de jornalista — rapazes muito alegres e irreverentes. “Nosso Correspondente Especial no Dia Depois de Amanhã informa”, dizia o Jornalista — ou antes, gritava — quando o Viajante do Tempo voltou. Estava vestido com roupas comuns de noite, e nada senão o aspecto macilento restava da mudança que me assustara.","isaysaidtheeditorhilariouslythesechapshe~whatwillyoutakeforthelot~148":"“Escute”, disse o Editor, hilário, “estes sujeitos aqui dizem que o senhor andou viajando para o meio da semana que vem! Conte-nos tudo sobre o pequeno Rosebery, quer? Quanto quer pelo lote?”","thetimetravellercametotheplacereservedfo~ostickaforkintomeatagain~141":"O Viajante do Tempo veio ao lugar reservado para ele sem uma palavra. Sorriu calmamente, ao seu velho modo. “Onde está meu carneiro?”, disse. “Que regalo é espetar um garfo em carne de novo!”","storycriedtheeditor~storycriedtheeditor~19":"“História!”, gritou o Editor.","storybedamnedsaidthetimetravelleriwantso~arteriesthanksandthesalt~115":"“História, o diabo!”, disse o Viajante do Tempo. “Quero algo para comer. Não direi uma palavra até pôr um pouco de peptona nas artérias. Obrigado. E o sal.”","onewordsaidihaveyoubeentimetravelling~aveyoubeentimetravelling~37":"“Uma palavra”, disse eu. “O senhor viajou no tempo?”","yessaidthetimetravellerwithhismouthfulln~smouthfullnoddinghishead~53":"“Sim”, disse o Viajante do Tempo, de boca cheia, acenando com a cabeça.","idgiveashillingalineforaverbatimnotesaid~ewayintotheadjoiningroom~934":"“Daria um xelim por linha de uma nota literal”, disse o Editor. O Viajante do Tempo empurrou a taça em direção ao Homem Silencioso e a fez soar com a unha; ante o que o Homem Silencioso, que estivera a fitar-lhe o rosto, teve um sobressalto convulsivo e serviu-lhe vinho. O resto do jantar foi desconfortável. De minha parte, perguntas súbitas não paravam de subir-me aos lábios, e ouso dizer que o mesmo se dava com os outros. O Jornalista tentou aliviar a tensão contando anedotas sobre Hettie Potter. O Viajante do Tempo dedicou a atenção ao jantar e exibiu o apetite de um vagabundo. O Médico fumava um cigarro e observava o Viajante do Tempo por entre os cílios. O Homem Silencioso parecia ainda mais desajeitado que de costume e bebia champanhe com regularidade e determinação, por puro nervosismo. Por fim o Viajante do Tempo afastou o prato e olhou em torno de nós. “Suponho que devo pedir desculpas”, disse. “Estava simplesmente faminto. Tive um tempo assombroso.” Estendeu a mão para um charuto e cortou a ponta. “Mas venham para a sala de fumar. É uma história longa demais para contar sobre pratos gordurosos.” E tocando a campainha de passagem, guiou-nos à sala contígua.","youhavetoldblankanddashandchoseaboutthem~dnamingthethreenewguests~107":"“Contou a Blank, a Dash e a Chose sobre a máquina?”, disse-me, recostando-se em sua poltrona e nomeando os três novos convidados.","butthethingsamereparadoxsaidtheeditor~mereparadoxsaidtheeditor~37":"“Mas a coisa é um mero paradoxo”, disse o Editor.","icantarguetonightidontmindtellingyouthes~ointerruptionsisitagreed~428":"“Não posso discutir esta noite. Não me importo de lhes contar a história, mas não posso discutir. Vou”, prosseguiu, “contar-lhes a história do que me aconteceu, se quiserem, mas devem abster-se de interrupções. Quero contá-la. Muito. A maior parte vai soar como mentira. Que seja! É verdade — cada palavra, mesmo assim. Eu estava em meu laboratório às quatro horas, e desde então… vivi oito dias… dias como nenhum ser humano jamais viveu! Estou quase exausto, mas não dormirei até lhes ter contado tudo isto. Depois irei para a cama. Mas sem interrupções! Combinado?”","agreedsaidtheeditorandtherestofusechoeda~yatthetimetravellersface~744":"“Combinado”, disse o Editor, e o resto de nós ecoou: “Combinado”. E com isso o Viajante do Tempo começou sua história tal como a expus. Recostou-se na cadeira a princípio, e falou como homem cansado. Depois ficou mais animado. Ao escrevê-la sinto com excessiva agudeza a inadequação da pena e da tinta — e, acima de tudo, a minha própria inadequação — para exprimir sua qualidade. Lê-se, suponho, com atenção bastante; mas não se pode ver o rosto branco e sincero do narrador no círculo brilhante do pequeno lampião, nem ouvir a entonação de sua voz. Não se pode saber como sua expressão acompanhava as voltas da narrativa! A maioria de nós, ouvintes, estava na sombra, pois as velas da sala de fumar não haviam sido acesas, e só o rosto do Jornalista e as pernas do Homem Silencioso, dos joelhos para baixo, estavam iluminados. A princípio olhávamos de vez em quando uns para os outros. Passado algum tempo, deixamos de fazê-lo e olhamos apenas para o rosto do Viajante do Tempo.","itoldsomeofyoulastthursdayoftheprinciple~itwasnearlyhalfpastthree~1017":"“Falei a alguns de vocês, na quinta-feira passada, dos princípios da Máquina do Tempo, e mostrei-lhes a coisa em si, ainda incompleta, na oficina. Aí está ela agora, um pouco gasta da viagem, é verdade; uma das barras de marfim está rachada e um trilho de latão, entortado; mas o resto está bastante sólido. Eu esperava terminá-la na sexta-feira, mas na sexta, quando a montagem estava quase concluída, descobri que uma das barras de níquel era exatamente uma polegada curta demais, e tive de mandar refazê-la; de modo que a coisa só ficou pronta esta manhã. Foi às dez horas de hoje que a primeira de todas as Máquinas do Tempo iniciou a sua carreira. Dei-lhe uma última batidinha, verifiquei de novo todos os parafusos, pus mais uma gota de óleo na haste de quartzo e sentei-me no selim. Suponho que um suicida que encosta uma pistola à própria cabeça sente o mesmo espanto diante do que virá a seguir que eu senti então. Tomei a alavanca de partida numa das mãos e a de parada na outra, empurrei a primeira e quase imediatamente a segunda. Tive a impressão de cambalear; senti a sensação de pesadelo de quem cai; e, olhando em torno, vi o laboratório exatamente como antes. Teria acontecido alguma coisa? Por um instante suspeitei que meu intelecto me havia enganado. Então reparei no relógio. Um momento antes, ao que parecia, ele marcava um minuto ou pouco mais depois das dez; agora eram quase três e meia!","idrewabreathsetmyteethgrippedthestarting~sednessdescendedonmymind~575":"“Respirei fundo, cerrei os dentes, agarrei a alavanca de partida com as duas mãos e parti com um baque. O laboratório ficou enevoado e escureceu. A sra. Watchett entrou e caminhou, aparentemente sem me ver, em direção à porta do jardim. Suponho que ela levou um minuto, mais ou menos, para atravessar o aposento, mas para mim pareceu disparar pela sala como um foguete. Empurrei a alavanca até a posição extrema. A noite veio como quem apaga uma lâmpada e, num instante, veio o dia seguinte. O laboratório foi se tornando tênue e nebuloso, depois mais tênue, e cada vez mais tênue. A noite do dia seguinte chegou negra, depois o dia outra vez, a noite outra vez, o dia outra vez, cada vez mais depressa. Um murmúrio turbilhonante encheu-me os ouvidos, e uma estranha e muda confusão desceu sobre o meu espírito.","iamafraidicannotconveythepeculiarsensati~ircleflickeringintheblue~1147":"“Temo não conseguir transmitir as sensações peculiares de viajar no tempo. São excessivamente desagradáveis. Há uma impressão exatamente igual à que se tem numa montanha-russa — a de um movimento impotente e precipitado! Senti também o mesmo horrível pressentimento de uma colisão iminente. À medida que eu ganhava velocidade, a noite sucedia o dia como o bater de uma asa negra. A vaga sugestão do laboratório pareceu logo se desprender de mim, e vi o sol saltando velozmente pelo céu, transpondo-o a cada minuto, e cada minuto marcando um dia. Supus que o laboratório havia sido destruído e que eu me achava ao ar livre. Tive uma impressão confusa de andaimes, mas já ia depressa demais para perceber coisas em movimento. O mais lento caracol que já rastejou passava disparado por mim. A cintilante sucessão de trevas e luz era excessivamente dolorosa para os olhos. Então, nas escuridões intermitentes, vi a lua girando velozmente por suas fases, de nova a cheia, e entrevi de relance as estrelas em seu círculo. Logo, à medida que eu avançava, ainda ganhando velocidade, a palpitação da noite e do dia fundiu-se numa só penumbra contínua e cinzenta; o céu assumiu uma maravilhosa profundeza de azul, uma esplêndida cor luminosa como a do primeiro crepúsculo; o sol, aos solavancos, tornou-se uma faixa de fogo, um arco brilhante no espaço; a lua, uma faixa mais pálida e flutuante; e das estrelas nada pude ver, a não ser, de quando em quando, um círculo mais brilhante tremeluzindo no azul.","thelandscapewasmistyandvagueiwasstillont~brightbriefgreenofspring~626":"“A paisagem era nebulosa e vaga. Eu ainda estava na encosta em que esta casa se ergue hoje, e o morro elevava-se acima de mim, cinzento e esmaecido. Vi árvores crescendo e mudando como baforadas de vapor, ora marrons, ora verdes; cresciam, espalhavam-se, estremeciam e desapareciam. Vi imensos edifícios erguerem-se, fracos e belos, e passarem como sonhos. Toda a superfície da terra parecia mudada — derretendo-se e fluindo diante dos meus olhos. Os ponteirinhos nos mostradores que registravam a minha velocidade giravam cada vez mais depressa. Logo notei que a faixa do sol oscilava para cima e para baixo, de solstício a solstício, em um minuto ou menos, e que, por conseguinte, minha marcha era de mais de um ano por minuto; e, minuto a minuto, a neve branca varria o mundo, e sumia, e era seguida pelo verde vivo e breve da primavera.","theunpleasantsensationsofthestartwereles~dtothebusinessofstopping~945":"“As sensações desagradáveis da partida foram ficando menos pungentes. Acabaram por se fundir numa espécie de exaltação histérica. Reparei, de fato, num balanço desajeitado da máquina, que não consegui explicar. Mas meu espírito estava confuso demais para dar-lhe atenção, de modo que, com uma espécie de loucura crescendo em mim, lancei-me ao futuro. A princípio mal pensei em parar, mal pensei em qualquer coisa que não fossem essas novas sensações. Mas logo uma nova série de impressões cresceu em minha mente — certa curiosidade e, com ela, certo temor — até que enfim tomaram completa posse de mim. Que estranhos desenvolvimentos da humanidade, que maravilhosos progressos sobre a nossa civilização rudimentar, pensei, não poderiam surgir quando eu viesse a olhar de perto o mundo vago e fugidio que corria e flutuava diante dos meus olhos! Vi uma arquitetura grandiosa e esplêndida erguer-se à minha volta, mais maciça que qualquer edifício do nosso tempo e, no entanto, ao que parecia, construída de cintilação e bruma. Vi um verde mais rico escorrer pela encosta e ali permanecer, sem nenhuma interrupção invernal. Mesmo através do véu da minha confusão, a terra parecia belíssima. E assim meu pensamento voltou à questão de parar.","thepeculiarrisklayinthepossibilityofmyfi~ungheadlongthroughtheair~1079":"“O risco peculiar estava na possibilidade de eu encontrar alguma substância no espaço que eu, ou a máquina, ocupasse. Enquanto eu viajava a grande velocidade através do tempo, isso mal importava; eu estava, por assim dizer, atenuado — deslizava como um vapor pelos interstícios das substâncias intermediárias! Mas parar implicava comprimir-me, molécula por molécula, contra o que quer que estivesse em meu caminho; significava pôr os meus átomos em contato tão íntimo com os do obstáculo que resultaria uma profunda reação química — possivelmente uma explosão de longo alcance — que lançaria a mim e ao meu aparelho para fora de todas as dimensões possíveis — no Desconhecido. Essa possibilidade me ocorrera repetidamente enquanto eu construía a máquina; mas então eu a aceitara alegremente como um risco inevitável — um dos riscos que um homem tem de correr! Agora que o risco era inevitável, já não o via sob a mesma luz alegre. O fato é que, insensivelmente, a absoluta estranheza de tudo, o balanço e o solavanco enjoativos da máquina e, sobretudo, a sensação de queda prolongada haviam abalado por completo os meus nervos. Disse a mim mesmo que jamais conseguiria parar e, num acesso de impaciência, resolvi parar de imediato. Como um tolo impaciente, puxei a alavanca com força e, no mesmo instante, a coisa tombou rodopiando e eu fui arremessado de cabeça pelos ares.","therewasthesoundofaclapofthunderinmyears~innumerableyearstoseeyou~574":"“Ouvi um estrondo como o de um trovão. Posso ter ficado atordoado por um momento. Um granizo impiedoso sibilava ao meu redor, e eu estava sentado sobre a relva macia, diante da máquina tombada. Tudo ainda parecia cinzento, mas logo notei que a confusão em meus ouvidos se dissipara. Olhei em volta. Estava no que parecia ser um pequeno gramado de um jardim, cercado de rododendros, e percebi que suas flores malvas e púrpuras caíam em chuva sob as pancadas das pedras de gelo. O granizo, saltando e dançando, pairava em nuvem sobre a máquina e rolava pelo chão como fumaça. Em um instante estava encharcado até os ossos. ‘Bela hospitalidade’, disse eu, ‘para um homem que viajou inúmeros anos para vê-los.’","presentlyithoughtwhatafooliwastogetwetis~seoftheworldwasinvisible~203":"“Logo pensei que tolice era molhar-me assim. Levantei-me e olhei em torno. Uma figura colossal, esculpida aparentemente em alguma pedra branca, assomava indistinta além dos rododendros, através do aguaceiro enevoado. Mas todo o resto do mundo estava invisível.","mysensationswouldbehardtodescribeastheco~ngwiththepromiseofthesun~759":"“Minhas sensações seriam difíceis de descrever. À medida que as colunas de granizo se rarefaziam, vi a figura branca com mais nitidez. Era muito grande, pois uma bétula prateada lhe tocava o ombro. Era de mármore branco, com a forma de uma esfinge alada, mas as asas, em vez de portadas verticalmente nos flancos, estavam abertas de modo que parecia pairar. O pedestal, pareceu-me, era de bronze, e estava coberto de azinhavre. Calhou de o rosto estar voltado para mim; os olhos cegos pareciam observar-me; havia a leve sombra de um sorriso nos lábios. Estava muito castigada pelo tempo, o que lhe dava uma desagradável sugestão de doença. Fiquei a olhá-la por um pequeno espaço — meio minuto, talvez, ou meia hora. Parecia avançar e recuar conforme o granizo, ao passar diante dela, se adensava ou rareava. Por fim arranquei por um momento os olhos da estátua e vi que a cortina de granizo se esgarçara e que o céu clareava, prometendo o sol.","ilookedupagainatthecrouchingwhiteshapean~retobeincontinentlyslain~448":"“Voltei a erguer os olhos para a forma branca e agachada, e toda a temeridade da minha viagem desabou de repente sobre mim. O que poderia surgir quando aquela cortina nebulosa fosse inteiramente retirada? O que não teria acontecido aos homens? E se a crueldade se tivesse tornado paixão comum? E se, nesse intervalo, a raça tivesse perdido a virilidade e se transformado em algo desumano, sem simpatia e de poder esmagador? Eu poderia parecer algum animal selvagem de um mundo antigo, tanto mais terrível e repugnante quanto mais semelhante a eles — uma criatura imunda a ser morta sem demora.","alreadyisawothervastshapeshugebuildingsw~lyinattitudetomountagain~914":"“Já via outras formas imensas — vastos edifícios de parapeitos intrincados e altas colunas, com uma encosta arborizada insinuando-se vagamente em minha direção através da tempestade que amainava. Fui tomado de um medo pânico. Voltei-me freneticamente para a Máquina do Tempo e esforcei-me com ardor para reajustá-la. Enquanto o fazia, os raios do sol romperam a tempestade. O aguaceiro cinzento foi varrido e desvaneceu-se como as vestes arrastadas de um fantasma. Acima de mim, no azul intenso do céu de verão, uns fracos fiapos marrons de nuvem rodopiaram até o nada. Os grandes edifícios à minha volta destacaram-se claros e nítidos, reluzindo com a umidade da tempestade e realçados em branco pelas pedras de granizo ainda intactas, amontoadas ao longo de suas cornijas. Senti-me nu num mundo estranho. Senti o que talvez sinta um pássaro no ar limpo, sabendo que o gavião plana acima e vai mergulhar. Meu medo cresceu até o frenesi. Tomei fôlego, cerrei os dentes e de novo me agarrei furiosamente à máquina, de pulso e joelho. Ela cedeu ao meu assalto desesperado e virou-se. Bateu-me violentamente no queixo. Com uma mão no selim, a outra na alavanca, fiquei arquejando fortemente, em atitude de montar outra vez.","butwiththisrecoveryofapromptretreatmycou~cesweredirectedtowardsme~251":"“Mas, com essa recuperação de uma pronta retirada, recuperou-se também a minha coragem. Olhei com mais curiosidade e menos temor para esse mundo do futuro remoto. Numa abertura circular, no alto da parede da casa mais próxima, vi um grupo de figuras vestidas de ricas e macias túnicas. Haviam-me visto, e seus rostos estavam voltados para mim.","theniheardvoicesapproachingmecomingthrou~irsttimehowwarmtheairwas~432":"“Então ouvi vozes que se aproximavam. Vindas através dos arbustos junto à Esfinge Branca, surgiam cabeças e ombros de homens que corriam. Um deles emergiu numa trilha que levava direto ao pequeno gramado onde eu estava com a minha máquina. Era uma criatura franzina — talvez de um metro e vinte de altura — vestida com uma túnica púrpura, cingida na cintura por um cinto de couro. Tinha nos pés sandálias ou botinas — não consegui distinguir bem —; as pernas estavam nuas até os joelhos, e a cabeça, descoberta. Ao reparar nisso, notei pela primeira vez como o ar estava quente.","hestruckmeasbeingaverybeautifulandgracef~ookmyhandsfromthemachine~239":"“Pareceu-me uma criatura muito bela e graciosa, mas indescritivelmente frágil. Seu rosto afogueado lembrou-me o dos tuberculosos mais belos — aquela beleza hética de que tanto se falava outrora. À sua vista, recobrei de repente a confiança. Tirei as mãos da máquina."}$tr$::jsonb, 115)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- h-g-wells_the-war-of-the-worlds (57 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('h-g-wells_the-war-of-the-worlds', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"theeveofthewar":"A véspera da guerra","thefallingstar":"A Estrela Cadente","onhorsellcommon":"Em Horsell Common"}$tr$::jsonb, $tr${"noonewouldhavebelievedinthelastyearsofth~ethegreatdisillusionment~1083":"Ninguém teria acreditado, nos últimos anos do século XIX, que este mundo estava sendo observado de perto e com atenção por inteligências superiores à do homem e, no entanto, tão mortais quanto ela; que, enquanto os homens se ocupavam de seus vários afazeres, eram examinados e estudados, talvez quase tão minuciosamente quanto um homem com um microscópio examinaria as criaturas transitórias que pululam e se multiplicam numa gota d’água. Com infinita complacência, os homens iam e vinham pelo globo cuidando de seus pequenos negócios, serenos na certeza de seu domínio sobre a matéria. É possível que os infusórios sob o microscópio façam o mesmo. Ninguém dava um pensamento aos mundos mais antigos do espaço como fontes de perigo para o homem, ou só pensava neles para descartar a ideia de vida ali como impossível ou improvável. É curioso recordar alguns dos hábitos mentais daqueles dias idos. No máximo, os homens terrestres imaginavam que pudesse haver outros homens em Marte, talvez inferiores a eles e dispostos a acolher uma empresa missionária. No entanto, do outro lado do abismo do espaço, mentes que estão para as nossas como as nossas para as das bestas que perecem, intelectos vastos, frios e impiedosos, contemplavam esta Terra com olhos invejosos e, lenta e seguramente, traçavam seus planos contra nós. E no início do século XX veio o grande desengano.","theplanetmarsiscarcelyneedremindthereade~pportofanimatedexistence~491":"O planeta Marte, mal preciso lembrar ao leitor, gira em torno do sol a uma distância média de 140.000.000 de milhas, e a luz e o calor que dele recebe mal chegam à metade do que recebe este mundo. Deve ser, se a hipótese nebular tem alguma verdade, mais velho que o nosso mundo; e muito antes de esta Terra deixar de ser incandescente, a vida em sua superfície deve ter começado seu curso. O fato de ter apenas um sétimo do volume da Terra deve ter acelerado seu resfriamento até a temperatura em que a vida pôde começar. Tem ar e água e tudo o que é necessário para sustentar a existência animada.","yetsovainismanandsoblindedbyhisvanitytha~beginningbutneareritsend~378":"Contudo, tão vaidoso é o homem, e tão cego pela vaidade, que nenhum escritor, até o fim do século XIX, exprimiu a ideia de que ali pudesse ter se desenvolvido uma vida inteligente muito além do nível terrestre, ou mesmo qualquer vida inteligente. Tampouco se compreendia em geral que, sendo Marte mais velho que a Terra, com pouco mais de um quarto de sua área superficial e mais afastado do sol, segue-se necessariamente que ele está não só mais distante do começo do tempo, mas mais próximo de seu fim.","thesecularcoolingthatmustsomedayovertake~andnarrownavycrowdedseas~977":"O resfriamento secular que um dia há de alcançar o nosso planeta já avançou muito em nosso vizinho. Seu estado físico ainda é em grande parte um mistério, mas sabemos agora que, mesmo na região equatorial, a temperatura do meio-dia mal se aproxima da de nosso inverno mais frio. Seu ar é muito mais rarefeito que o nosso, seus oceanos encolheram até cobrir apenas um terço da superfície e, à medida que suas lentas estações mudam, enormes calotas de neve se formam e derretem em torno de cada polo, inundando periodicamente suas zonas temperadas. Esse último estágio de exaustão, que para nós ainda é inacreditavelmente remoto, tornou-se um problema atual para os habitantes de Marte. A pressão imediata da necessidade aguçou-lhes o intelecto, ampliou-lhes os poderes e endureceu-lhes o coração. E, olhando através do espaço com instrumentos e inteligências como mal sonhamos, eles veem, à sua distância mínima de apenas 35.000.000 de milhas em direção ao sol, uma estrela da manhã de esperança, o nosso planeta mais quente, verde de vegetação e cinzento de água, com uma atmosfera nublada eloquente de fertilidade, e com vislumbres, por entre os farrapos de nuvens à deriva, de vastas extensões de terra populosa e de mares estreitos apinhados de navios.","andwementhecreatureswhoinhabitthisearthm~generationcreepsuponthem~452":"E nós, homens, as criaturas que habitam esta Terra, devemos ser para eles ao menos tão estranhos e inferiores quanto são para nós os macacos e os lêmures. O lado intelectual do homem já admite que a vida é uma luta incessante pela existência, e parece que esta é também a crença das mentes de Marte. O mundo deles está muito avançado em seu resfriamento, e este mundo ainda está repleto de vida, mas repleto apenas do que eles consideram animais inferiores. Levar a guerra em direção ao sol é, de fato, sua única fuga da destruição que, geração após geração, rasteja até eles.","andbeforewejudgeofthemtooharshlywemustre~answarredinthesamespirit~382":"E, antes de julgá-los com demasiada dureza, devemos lembrar que destruição implacável e total a nossa própria espécie produziu, não apenas entre os animais, como o extinto bisão e o dodô, mas entre as suas raças inferiores. Os tasmanianos, apesar da semelhança humana, foram inteiramente varridos da existência, numa guerra de extermínio movida por imigrantes europeus, no espaço de cinquenta anos. Seríamos nós tais apóstolos da misericórdia que nos queixássemos de que os marcianos guerreassem com o mesmo espírito?","themartiansseemtohavecalculatedtheirdesc~musthavebeengettingready~491":"Os marcianos parecem ter calculado a sua descida com espantosa sutileza — seu saber matemático é evidentemente muito superior ao nosso — e ter levado a cabo os preparativos com uma unanimidade quase perfeita. Se nossos instrumentos o permitissem, poderíamos ter visto a ameaça se acumular já bem atrás, no século XIX. Homens como Schiaparelli observaram o planeta vermelho — é curioso, aliás, que, durante inúmeros séculos, Marte tenha sido a estrela da guerra — mas não souberam interpretar as aparências cambiantes das marcas que tão bem mapearam. Durante todo esse tempo, os marcianos devem ter estado se preparando.","duringtheoppositionof1894agreatlightwass~ingthenexttwooppositions~417":"Durante a oposição de 1894, uma grande luz foi vista na parte iluminada do disco, primeiro no Observatório de Lick, depois por Perrotin, de Nice, e depois por outros observadores. Os leitores ingleses ouviram falar dela pela primeira vez no número da Nature datado de 2 de agosto. Inclino-me a pensar que esse clarão pode ter sido a fundição do enorme canhão, no vasto fosso aberto em seu planeta, de onde seus projéteis foram disparados contra nós. Marcas peculiares, até hoje inexplicadas, foram vistas perto do local daquela erupção durante as duas oposições seguintes.","thestormburstuponussixyearsagonowasmarsa~minggasesrushedoutofagun~518":"A tempestade desabou sobre nós há seis anos. Quando Marte se aproximava da oposição, Lavelle, de Java, pôs a palpitar os fios da central astronômica com a espantosa notícia de uma enorme erupção de gás incandescente no planeta. Ocorrera perto da meia-noite do dia doze; e o espectroscópio, a que ele recorreu de imediato, indicava uma massa de gás em chamas, principalmente hidrogênio, movendo-se com enorme velocidade em direção a esta Terra. Esse jato de fogo tornara-se invisível por volta de um quarto depois da meia-noite. Ele o comparou a uma colossal baforada de chamas, súbita e violentamente expelida do planeta, “como gases flamejantes saindo de um canhão”.","asingularlyappropriatephraseitprovedyett~nascrutinyoftheredplanet~402":"Singularmente apropriada, a expressão. Contudo, no dia seguinte não havia nada disso nos jornais, exceto uma pequena nota no Daily Telegraph, e o mundo seguiu na ignorância de um dos mais graves perigos que já ameaçaram a raça humana. Talvez eu nem tivesse ouvido falar da erupção se não houvesse encontrado Ogilvy, o conhecido astrônomo, em Ottershaw. Estava imensamente excitado com a notícia e, no excesso de seus sentimentos, convidou-me a subir com ele naquela noite para um exame do planeta vermelho.","inspiteofallthathashappenedsinceistillre~kthatkepttheplanetinview~671":"Apesar de tudo o que aconteceu desde então, ainda me lembro daquela vigília com muita nitidez: o observatório negro e silencioso, a lanterna velada lançando um fraco clarão no chão, a um canto, o tique-taque constante do mecanismo de relógio do telescópio, a pequena fenda no teto — uma profundeza oblonga riscada de poeira de estrelas. Ogilvy movia-se por ali, invisível mas audível. Olhando pelo telescópio, via-se um círculo de azul profundo e o pequeno planeta redondo flutuando no campo. Parecia coisa tão pequena, tão brilhante e minúscula e quieta, vagamente marcada de listras transversais e ligeiramente achatada em relação ao círculo perfeito. Mas tão pequeno, tão argênteo e cálido — uma cabeça de alfinete de luz! Era como se tremesse, mas na verdade era o telescópio que vibrava com a atividade do mecanismo que mantinha o planeta à vista.","asiwatchedtheplanetseemedtogrowlargerand~thematerialuniverseswims~243":"Enquanto eu observava, o planeta parecia crescer e diminuir, avançar e recuar, mas era simplesmente que meu olho estava cansado. Estava a quarenta milhões de milhas de nós — mais de quarenta milhões de milhas de vazio. Poucos percebem a imensidão do vácuo em que nada a poeira do universo material.","nearitinthefieldirememberwerethreefaintp~medofthatunerringmissile~541":"Perto dele, no campo, lembro-me, havia três fracos pontos de luz, três estrelas telescópicas infinitamente remotas, e em volta de tudo estava a insondável escuridão do espaço vazio. Sabem como é esse negrume numa noite gelada de luz estelar. No telescópio parece muito mais profundo. E, invisível para mim porque era tão remota e pequena, voando veloz e firme em minha direção através daquela distância incrível, aproximando-se a cada minuto tantos milhares de milhas, vinha a Coisa que nos enviavam, a Coisa que traria tanta luta e calamidade e morte à Terra. Nunca sonhei com isso então, enquanto observava; ninguém na Terra sonhou com aquele projétil infalível.","thatnighttootherewasanotherjettingoutofg~fgasthatcameouttowardsus~376":"Naquela noite, também, houve outra erupção de gás no planeta distante. Eu a vi. Um clarão avermelhado na borda, a mais leve saliência no contorno, justo quando o cronômetro bateu meia-noite; e então avisei Ogilvy, que tomou o meu lugar. A noite estava quente e eu tinha sede, e fui, esticando desajeitadamente as pernas e tateando no escuro, até a mesinha onde estava o sifão, enquanto Ogilvy exclamava diante do filete de gás que vinha em nossa direção.","thatnightanotherinvisiblemissilestartedo~sofpeoplesleepinginpeace~482":"Naquela noite outro projétil invisível partiu de Marte rumo à Terra, apenas um segundo ou pouco menos de vinte e quatro horas depois do primeiro. Lembro-me de como me sentei na mesa, no escuro, com manchas de verde e carmesim nadando diante dos olhos. Desejei ter uma luz para fumar, mal suspeitando do significado do minúsculo lampejo que eu vira e de tudo o que ele logo me traria. Ogilvy observou até a uma hora e depois desistiu; e acendemos a lanterna e fomos a pé até a casa dele. Lá embaixo, no escuro, estavam Ottershaw e Chertsey e todas as suas centenas de habitantes, dormindo em paz.","hewasfullofspeculationthatnightaboutthec~ninthetwoadjacentplanets~325":"Ele estava cheio de conjecturas, naquela noite, sobre a condição de Marte, e zombava da ideia vulgar de que haveria habitantes a nos fazer sinais. Pensava que talvez meteoritos estivessem caindo em forte chuva sobre o planeta, ou que uma enorme explosão vulcânica estivesse em curso. Mostrou-me quão improvável era que a evolução orgânica tivesse seguido a mesma direção nos dois planetas vizinhos.","thechancesagainstanythingmanlikeonmarsar~rsareamilliontoonehesaid~60":"— As chances contra qualquer coisa semelhante ao homem em Marte são de um milhão para um — disse ele.","hundredsofobserverssawtheflamethatnighta~ditsmorefamiliarfeatures~414":"Centenas de observadores viram a chama naquela noite e na noite seguinte, por volta da meia-noite, e de novo na noite depois dessa; e assim durante dez noites, uma chama por noite. Por que os disparos cessaram depois do décimo, ninguém na Terra tentou explicar. Pode ser que os gases do disparo causassem inconveniente aos marcianos. Densas nuvens de fumaça ou poeira, visíveis num poderoso telescópio da Terra como pequenas manchas cinzentas e flutuantes, espalharam-se pela limpidez da atmosfera do planeta e obscureceram os seus aspectos mais familiares.","eventhedailypaperswokeuptothedisturbance~ascivilisationprogressed~822":"Até os jornais diários acordaram, enfim, para as perturbações, e notas populares apareceram aqui, ali e por toda parte sobre os vulcões de Marte. O periódico sério-cômico Punch, lembro-me, fez dele um uso feliz na caricatura política. E, sem que ninguém suspeitasse, aqueles projéteis que os marcianos haviam disparado contra nós aproximavam-se da Terra, precipitando-se agora a muitas milhas por segundo através do abismo vazio do espaço, hora a hora e dia a dia, cada vez mais perto. Parece-me hoje quase inacreditavelmente maravilhoso que, com aquele destino veloz suspenso sobre nós, os homens pudessem tratar de suas pequenas preocupações como o faziam. Lembro-me de como Markham estava exultante por ter conseguido uma nova fotografia do planeta para o jornal ilustrado que então dirigia. As pessoas, nestes últimos tempos, mal percebem a abundância e o espírito de iniciativa dos nossos jornais do século XIX. De minha parte, eu estava muito ocupado em aprender a andar de bicicleta e atarefado numa série de artigos sobre os prováveis desenvolvimentos das ideias morais à medida que a civilização progredisse.","onenightthefirstmissilethencouldscarcely~tseemedsosafeandtranquil~633":"Uma noite (o primeiro projétil mal poderia estar então a 10.000.000 de milhas) saí para passear com minha mulher. Era noite de estrelas, e expliquei a ela os signos do Zodíaco e apontei Marte, um brilhante ponto de luz subindo para o zênite, para o qual tantos telescópios estavam voltados. Era uma noite quente. Na volta para casa, um grupo de excursionistas de Chertsey ou Isleworth passou por nós cantando e tocando música. Havia luzes nas janelas dos andares de cima das casas, enquanto as pessoas se recolhiam. Da estação ferroviária, ao longe, vinha o som dos trens em manobra, tinindo e retumbando, quase abrandado em melodia pela distância. Minha mulher chamou minha atenção para o brilho das luzes de sinal vermelhas, verdes e amarelas, penduradas numa armação contra o céu. Tudo parecia tão seguro e tranquilo.","thencamethenightofthefirstfallingstaritw~onehundredmileseastofhim~419":"Então veio a noite da primeira estrela cadente. Foi vista de manhã cedo, precipitando-se sobre Winchester rumo ao leste, uma linha de chama no alto da atmosfera. Centenas de pessoas devem tê-la visto e tomado por uma estrela cadente comum. Albin descreveu-a como deixando atrás de si um rastro esverdeado que brilhou por alguns segundos. Denning, nossa maior autoridade em meteoritos, afirmou que a altura de seu primeiro aparecimento era de uns noventa ou cem milhas. Pareceu-lhe que ela caiu na terra a cerca de cem milhas a leste dele.","iwasathomeatthathourandwritinginmystudya~orthefallenmassthatnight~540":"Eu estava em casa àquela hora, escrevendo em meu gabinete; e embora as minhas janelas francesas dêem para Ottershaw e a persiana estivesse levantada (pois eu gostava, naqueles dias, de olhar para o céu noturno), nada vi. No entanto, essa mais estranha de todas as coisas que já vieram do espaço exterior à Terra deve ter caído enquanto eu ali estava sentado, visível para mim se ao menos eu houvesse erguido os olhos quando passou. Alguns dos que viram o seu voo dizem que ela viajava com um sibilo. Eu mesmo nada ouvi. Muita gente em Berkshire, Surrey e Middlesex deve ter visto a sua queda e, no máximo, pensado que mais um meteorito descera. Ninguém parece ter se dado ao trabalho de procurar a massa caída naquela noite.","butveryearlyinthemorningpoorogilvywhohad~esmokeroseagainstthedawn~442":"Mas, bem cedo pela manhã, o pobre Ogilvy, que tinha visto a estrela cadente e estava persuadido de que um meteorito jazia em algum ponto do descampado entre Horsell, Ottershaw e Woking, levantou-se cedo com a ideia de encontrá-lo. Encontrou-o, de fato, logo depois da alvorada, e não longe dos areais. Um enorme buraco fora aberto pelo impacto do projétil, e a areia e o cascalho tinham sido lançados violentamente em todas as direções sobre a charneca, formando montes visíveis a uma milha e meia de distância. A urze ardia para o leste, e uma fina fumaça azul subia contra a aurora.","thethingitselflayalmostentirelyburiedins~tohimthatitmightbehollow~564":"A Coisa em si jazia quase inteiramente enterrada na areia, entre as lascas espalhadas de um pinheiro que ela estilhaçara na descida. A parte descoberta tinha o aspecto de um enorme cilindro, empastado, seu contorno suavizado por uma espessa incrustação escamosa de cor parda. Tinha um diâmetro de cerca de trinta jardas. Ele se aproximou da massa, surpreso com o tamanho e mais ainda com a forma, pois a maioria dos meteoritos é mais ou menos completamente arredondada. Estava, contudo, ainda tão quente do voo através do ar que lhe proibia chegar perto. Um ruído de agitação no interior do cilindro ele atribuiu ao resfriamento desigual da superfície; pois, naquela altura, não lhe ocorrera que pudesse ser oco.","heremainedstandingattheedgeofthepitthatt~hewasallaloneonthecommon~454":"Permaneceu de pé à beira da cova que a Coisa fizera para si, fitando o seu estranho aspecto, espantado principalmente com a forma e a cor incomuns, e percebendo vagamente, já então, alguma evidência de desígnio na sua chegada. A manhã estava maravilhosamente calma, e o sol, que acabava de despontar por cima dos pinheiros na direção de Weybridge, já era quente. Ele não se lembrava de ter ouvido pássaros naquela manhã, certamente não havia brisa, e os únicos sons eram os fracos movimentos dentro do cilindro cinzento de escória. Estava completamente só no descampado.","thensuddenlyhenoticedwithastartthatsomeo~ughthisheartintohismouth~261":"Então, de repente, notou com um sobressalto que parte da escória cinzenta, a incrustação cinérea que cobria o meteorito, se desprendia da borda circular da extremidade. Caía em flocos e chovia sobre a areia. Um grande pedaço soltou-se de súbito e caiu com um ruído seco que lhe pôs o coração na boca.","foraminutehescarcelyrealisedwhatthismean~yfromtheendofthecylinder~274":"Por um minuto mal percebeu o que isso significava e, embora o calor fosse excessivo, desceu penosamente à cova, junto ao vulto, para ver a Coisa com mais clareza. Imaginou ainda então que o resfriamento do corpo poderia explicar aquilo, mas o que perturbava essa ideia era o fato de que a cinza caía somente da extremidade do cilindro.","andthenheperceivedthatveryslowlythecircu~inderwasunscrewingthetop~470":"E então percebeu que, muito lentamente, o topo circular do cilindro girava sobre o corpo. Era um movimento tão gradual que ele só o descobriu ao notar que uma marca negra que estivera perto dele cinco minutos antes estava agora do outro lado da circunferência. Mesmo então mal compreendeu o que isso indicava, até ouvir um rangido abafado e ver a marca negra dar um solavanco para a frente, de uma polegada ou pouco mais. Então a coisa lhe veio num lampejo. O cilindro era artificial — oco — com uma extremidade que se desatarraxava! Algo dentro do cilindro estava desatarraxando a tampa!","goodheavenssaidogilvytheresamaninitmenin~tedtodeathtryingtoescape~74":"— Santo Deus! — disse Ogilvy. — Há um homem dentro! Homens dentro! Meio assados até a morte! Tentando escapar!","atoncewithaquickmentalleaphelinkedthethi~hingwiththeflashuponmars~62":"Imediatamente, com um rápido salto mental, ligou a Coisa ao clarão em Marte.","thethoughtoftheconfinedcreaturewassodrea~andmadehimselfunderstood~761":"O pensamento da criatura confinada era-lhe tão terrível que ele esqueceu o calor e avançou para o cilindro a fim de ajudar a girar. Mas, por sorte, a radiação surda o deteve antes que queimasse as mãos no metal ainda incandescente. Diante disso ficou irresoluto por um momento, depois se voltou, saiu da cova aos trambolhões e partiu correndo desvairadamente para Woking. Devia ser então por volta das seis horas. Encontrou um carroceiro e tentou fazê-lo compreender, mas a história que contou e o seu aspecto eram tão selvagens — o chapéu caíra na cova — que o homem simplesmente seguiu adiante. Teve igual insucesso com o garçom que estava abrindo as portas da taverna junto à ponte de Horsell. O sujeito julgou-o um lunático à solta e tentou, sem êxito, trancá-lo na sala do bar. Isso o sobriou um pouco; e quando viu Henderson, o jornalista de Londres, em seu jardim, chamou-o por sobre a cerca e fez-se entender.","hendersonhecalledyousawthatshootingstarl~hatshootingstarlastnight~48":"— Henderson — chamou —, você viu aquela estrela cadente ontem à noite?","wellsaidhenderson~wellsaidhenderson~17":"— E então? — disse Henderson.","itsoutonhorsellcommonnow~itsoutonhorsellcommonnow~24":"— Está agora em Horsell Common.","goodlordsaidhendersonfallenmeteoritethat~fallenmeteoritethatsgood~45":"— Santo Deus! — disse Henderson. — Um meteorito caído! Que bom.","butitssomethingmorethanameteoriteitsacyl~andtheressomethinginside~92":"— Mas é algo mais que um meteorito. É um cilindro — um cilindro artificial, homem! E há alguma coisa dentro.","hendersonstoodupwithhisspadeinhishand~dupwithhisspadeinhishand~37":"Henderson endireitou-se com a pá na mão.","whatsthathesaidhewasdeafinoneear~thesaidhewasdeafinoneear~32":"— O que é? — disse ele. Era surdo de um ouvido.","ogilvytoldhimallthathehadseenhendersonwa~imwithathinsizzlingsound~365":"Ogilvy contou-lhe tudo o que tinha visto. Henderson levou um minuto, mais ou menos, para assimilar. Então largou a pá, apanhou o paletó e saiu para a estrada. Os dois homens voltaram depressa ao descampado e encontraram o cilindro ainda na mesma posição. Mas agora os ruídos lá dentro tinham cessado, e um fino círculo de metal brilhante aparecia entre a tampa e o corpo do cilindro. O ar entrava ou escapava pela borda com um fino chiado.","theylistenedrappedonthescalyburntmetalwi~demustbeinsensibleordead~128":"Escutaram, bateram no metal queimado e escamoso com um bastão e, não obtendo resposta, ambos concluíram que o homem ou os homens lá dentro deviam estar inconscientes ou mortos.","ofcoursethetwowerequiteunabletodoanythin~forthereceptionoftheidea~427":"Claro que os dois eram totalmente incapazes de fazer alguma coisa. Gritaram consolos e promessas e voltaram à cidade em busca de ajuda. Pode-se imaginá-los, cobertos de areia, excitados e desgrenhados, correndo pela ruazinha sob o sol brilhante, justo quando os lojistas tiravam as venezianas e as pessoas abriam as janelas dos quartos. Henderson foi logo à estação ferroviária, para telegrafar a notícia a Londres. Os artigos dos jornais tinham preparado os espíritos para receber a ideia.","byeightoclockanumberofboysandunemployedm~rshawbridgetothesandpits~289":"Às oito horas, uma porção de meninos e desocupados já tinha partido para o descampado a fim de ver os “mortos de Marte”. Foi essa a forma que a história tomou. Ouvi falar dela pela primeira vez pelo meu entregador de jornais, por volta das nove menos um quarto, quando saí para pegar o meu Daily Chronicle. Fiquei naturalmente alarmado e não perdi tempo em sair e atravessar a ponte de Ottershaw até os areais.","ifoundalittlecrowdofperhapstwentypeoples~eakfastathendersonshouse~374":"Encontrei uma pequena multidão, talvez de vinte pessoas, em torno do enorme buraco onde jazia o cilindro. Já descrevi o aspecto daquele vulto colossal, encravado no solo. A relva e o cascalho em volta pareciam carbonizados, como por uma explosão súbita. Sem dúvida o impacto causara um clarão de fogo. Henderson e Ogilvy não estavam lá. Penso que perceberam que nada havia a fazer por ora e foram tomar o desjejum na casa de Henderson.","therewerefourorfiveboyssittingontheedgeo~utofthegroupofbystanders~216":"Havia quatro ou cinco meninos sentados à beira da Cova, com as pernas balançando, divertindo-se — até que os fiz parar — em atirar pedras na massa gigantesca. Depois que lhes falei a respeito, puseram-se a brincar de pega-pega entre o grupo de curiosos.","amongthesewereacoupleofcyclistsajobbingg~dcertainlyceasedtorotate~622":"Entre eles havia uns dois ciclistas, um jardineiro avulso que eu empregava às vezes, uma moça com um bebê no colo, Gregg, o açougueiro, com seu filhinho, e dois ou três vadios e carregadores de tacos de golfe que costumavam rondar a estação ferroviária. Falava-se muito pouco. Poucas pessoas do povo, na Inglaterra daqueles dias, tinham mais que as mais vagas noções de astronomia. A maioria olhava calada para a extremidade do cilindro, semelhante a uma grande mesa, que continuava como Ogilvy e Henderson a haviam deixado. Imagino que a expectativa popular de uma pilha de cadáveres carbonizados se frustrou diante daquele vulto inanimado. Alguns se foram enquanto eu estava lá, e outros chegaram. Desci à cova e julguei ouvir um fraco movimento sob os meus pés. A tampa decerto cessara de girar.","itwasonlywhenigotthusclosetoitthatthestr~ingformostoftheonlookers~450":"Foi apenas ao chegar assim perto que a estranheza do objeto se me tornou de algum modo evidente. À primeira vista não era realmente mais excitante que uma carruagem tombada ou uma árvore derrubada pelo vento na estrada. Menos, na verdade. Parecia uma boia de gasômetro enferrujada. Era preciso certa dose de instrução científica para perceber que a crosta cinzenta da Coisa não era óxido comum, que o metal branco-amarelado que luzia na fresta entre a tampa e o cilindro tinha um matiz desconhecido. “Extraterrestre” não tinha significado para a maioria dos espectadores.","atthattimeitwasquiteclearinmyownmindthat~myabstractinvestigations~581":"Naquela altura estava bem claro em minha mente que a Coisa viera do planeta Marte, mas julguei improvável que contivesse alguma criatura viva. Pensei que o desatarraxar poderia ser automático. Apesar de Ogilvy, eu ainda acreditava que havia homens em Marte. Minha mente corria fantasiosa sobre a possibilidade de que contivesse manuscritos, sobre as dificuldades de tradução que poderiam surgir, sobre se encontraríamos nele moedas e modelos, e assim por diante. Contudo, era um pouco grande demais para dar segurança a essa ideia. Senti impaciência por vê-lo aberto. Por volta das onze, como nada parecia acontecer, voltei, cheio de tais pensamentos, para minha casa em Maybury. Mas achei difícil pôr-me a trabalhar em minhas investigações abstratas.","intheafternoontheappearanceofthecommonha~donwithenormousheadlines~128":"À tarde, o aspecto do descampado havia mudado muito. As primeiras edições dos jornais vespertinos tinham assustado Londres com enormes manchetes:","amessagereceivedfrommars~amessagereceivedfrommars~24":"“Mensagem Recebida de Marte.”","remarkablestoryfromwoking~emarkablestoryfromwoking~25":"“Notável História de Woking”,","andsoforthinadditionogilvyswiretotheastr~vatoryinthethreekingdoms~99":"e assim por diante. Além disso, o telegrama de Ogilvy à Central Astronômica havia despertado todos os observatórios dos três reinos.","therewerehalfadozenfliesormorefromthewok~ssedladiesamongtheothers~343":"Havia meia dúzia ou mais de carruagens de aluguel da estação de Woking paradas na estrada junto aos areais, uma charrete de vime de Chobham e uma carruagem bastante senhorial. Além disso, havia um verdadeiro monte de bicicletas. Ademais, grande número de pessoas deve ter vindo a pé, apesar do calor do dia, de Woking e Chertsey, de modo que havia ao todo uma multidão considerável — uma ou duas damas garbosamente vestidas entre os demais.","itwasglaringlyhotnotacloudintheskynorabr~greenapplesandgingerbeer~341":"Fazia um calor escaldante, nem uma nuvem no céu nem um sopro de vento, e a única sombra era a dos poucos pinheiros esparsos. A urze em chamas fora extinta, mas o terreno plano em direção a Ottershaw estava enegrecido até onde a vista alcançava, e ainda soltava colunas verticais de fumaça. Um empreendedor vendedor de doces da estrada de Chobham mandara o filho com um carrinho de mão carregado de maçãs verdes e cerveja de gengibre.","goingtotheedgeofthepitifounditoccupiedby~seemedtohaveirritatedhim~378":"Indo até a beira da cova, encontrei-a ocupada por um grupo de cerca de meia dúzia de homens — Henderson, Ogilvy e um homem alto, de cabelos louros, que depois soube ser Stent, o Astrônomo Real, com vários operários manejando pás e picaretas. Stent dava ordens com voz clara e aguda. Estava em pé sobre o cilindro, que agora estava evidentemente muito mais frio; o rosto estava rubro e escorrendo de suor, e algo parecia tê-lo irritado.","alargeportionofthecylinderhadbeenuncover~dhiltonthelordofthemanor~216":"Grande parte do cilindro fora desenterrada, embora a extremidade inferior ainda estivesse encravada. Assim que Ogilvy me viu entre a multidão boquiaberta à beira da cova, chamou-me para descer e perguntou se eu me importaria de ir ver Lord Hilton, o senhor do solar.","thegrowingcrowdhesaidwasbecomingaserious~noisytumultintheinterior~381":"A multidão crescente, disse ele, estava se tornando um sério impedimento às escavações, especialmente os meninos. Queriam que se erguesse uma cerca leve e que se ajudasse a manter o povo afastado. Disse-me que um fraco movimento ainda era ocasionalmente audível dentro do invólucro, mas que os operários não haviam conseguido desatarraxar a tampa, pois ela não lhes oferecia onde segurar. O invólucro parecia ser enormemente espesso, e era possível que os fracos sons que ouvíamos representassem um ruidoso tumulto no interior.","iwasverygladtodoasheaskedandsobecomeoneo~ptothestationtowaylayhim~280":"Fiquei muito contente em fazer o que ele pedia e assim tornar-me um dos espectadores privilegiados dentro do recinto projetado. Não consegui encontrar Lord Hilton em casa, mas disseram-me que era esperado de Londres no trem das seis, vindo de Waterloo; e como eram então cerca de cinco e quinze, fui para casa, tomei um chá e subi até a estação para interceptá-lo."}$tr$::jsonb, 57)
