insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('jane-austen_pride-and-prejudice', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"chapteri":"Capítulo I","chapterii":"Capítulo II","chapteriii":"Capítulo III"}$tr$::jsonb, $tr${"itisatruthuniversallyacknowledgedthatasi~rtunemustbeinwantofawife~92":"É uma verdade universalmente reconhecida que um homem solteiro, possuidor de uma boa fortuna, deve estar necessitado de uma esposa.","howeverlittleknownthefeelingsorviewsofsu~eorotheroftheirdaughters~210":"Por menos conhecidos que sejam os sentimentos ou as intenções de tal homem ao chegar a uma vizinhança, essa verdade está tão firmemente fixada na mente das famílias circunvizinhas que ele é considerado propriedade legítima de uma ou outra de suas filhas.","mydearmrbennetsaidhisladytohimonedayhave~therfieldparkisletatlast~78":"— Meu caro Sr. Bennet — disse-lhe a esposa um dia —, já soube que Netherfield Park finalmente foi alugada?","mrbennetrepliedthathehadnot~ennetrepliedthathehadnot~27":"O Sr. Bennet respondeu que não.","butitisreturnedsheformrslonghasjustbeenh~reandshetoldmeallaboutit~65":"— Pois foi — retorquiu ela —, porque a Sra. Long acabou de estar aqui e me contou tudo.","mrbennetmadenoanswer~mrbennetmadenoanswer~20":"O Sr. Bennet não deu resposta.","donotyouwanttoknowwhohastakenitcriedhisw~tcriedhiswifeimpatiently~54":"— Não quer saber quem a alugou? — exclamou a esposa, impaciente.","youwanttotellmeandihavenoobjectiontohear~venoobjectiontohearingit~45":"— A senhora quer me contar, e não tenho objeção nenhuma a ouvir.","thiswasinvitationenough~thiswasinvitationenough~23":"Isso foi convite suficiente.","whymydearyoumustknowmrslongsaysthatnethe~ehousebytheendofnextweek~307":"— Pois bem, meu caro, fique sabendo que a Sra. Long diz que Netherfield foi alugada por um jovem de grande fortuna, do norte da Inglaterra; que ele veio na segunda-feira, numa carruagem de quatro cavalos, ver a propriedade, e ficou tão encantado que fechou negócio imediatamente com o Sr. Morris; que tomará posse antes do dia de São Miguel, e alguns de seus criados devem estar na casa até o fim da próxima semana.","whatishisname~whatishisname~13":"— Como se chama ele?","bingley~bingley~7":"— Bingley.","ishemarriedorsingle~ishemarriedorsingle~19":"— É casado ou solteiro?","ohsinglemydeartobesureasinglemanoflargef~hatafinethingforourgirls~94":"— Oh! Solteiro, meu caro, com certeza! Um homem solteiro e de grande fortuna; quatro ou cinco mil por ano. Que coisa boa para as nossas meninas!","howsohowcanitaffectthem~howsohowcanitaffectthem~23":"— Como assim? Em que isso pode afetá-las?","mydearmrbennetrepliedhiswifehowcanyoubes~ngofhismarryingoneofthem~97":"— Meu caro Sr. Bennet — respondeu a esposa —, como pode ser tão enfadonho! Deve saber que estou pensando em que ele se case com uma delas.","isthathisdesigninsettlinghere~thisdesigninsettlinghere~29":"— Foi esse o propósito dele ao se instalar aqui?","designnonsensehowcanyoutalksobutitisvery~tvisithimassoonashecomes~120":"— Propósito! Que bobagem, como pode falar assim! Mas é muito provável que ele se apaixone por uma delas, e portanto o senhor deve visitá-lo assim que ele chegar.","iseenooccasionforthatyouandthegirlsmaygo~likeyouthebestoftheparty~167":"— Não vejo necessidade disso. A senhora e as meninas podem ir, ou pode mandá-las sozinhas, o que talvez seja ainda melhor, pois, como a senhora é tão bonita quanto qualquer uma delas, o Sr. Bingley talvez goste mais da senhora do grupo todo.","mydearyouflattermeicertainlyhavehadmysha~erthinkingofherownbeauty~167":"— Meu caro, o senhor me lisonjeia. Certamente tive a minha parcela de beleza, mas não pretendo ser nada de extraordinário agora. Quando uma mulher tem cinco filhas já crescidas, deve deixar de pensar na própria beleza.","insuchcasesawomanhasnotoftenmuchbeautyto~oftenmuchbeautytothinkof~47":"— Nesses casos, uma mulher muitas vezes não tem muita beleza em que pensar.","butmydearyoumustindeedgoandseemrbingleyw~omesintotheneighbourhood~70":"— Mas, meu caro, o senhor realmente precisa ir ver o Sr. Bingley quando ele chegar à vizinhança.","itismorethaniengageforiassureyou~thaniengageforiassureyou~32":"— Isso eu lhe garanto que não prometo.","butconsideryourdaughtersonlythinkwhatane~orustovisithimifyoudonot~231":"— Mas pense em suas filhas. Pense só que partido seria para uma delas. Sir William e Lady Lucas estão decididos a ir, apenas por esse motivo, pois em geral, o senhor sabe, eles não visitam recém-chegados. Realmente deve ir, pois será impossível para nós visitá-lo se o senhor não for.","youareoverscrupuloussurelyidaresaymrbing~goodwordformylittlelizzy~203":"— A senhora é escrupulosa demais, sem dúvida. Atrevo-me a dizer que o Sr. Bingley ficará muito contente de vê-la; e eu lhe mandarei por seu intermédio algumas linhas para assegurar-lhe meu pleno consentimento a que se case com a que quiser dentre as meninas; embora eu deva acrescentar uma palavra em favor de minha pequena Lizzy.","idesireyouwilldonosuchthinglizzyisnotabi~ysgivingherthepreference~163":"— Peço-lhe que não faça tal coisa. Lizzy não é nem um pouco melhor que as outras; e tenho certeza de que não é metade tão bonita quanto Jane, nem metade tão bem-humorada quanto Lydia. Mas o senhor está sempre dando preferência a ela.","theyhavenoneofthemmuchtorecommendthemrep~fquicknessthanhersisters~135":"— Nenhuma delas tem muito que a recomende — replicou ele. — São todas tolas e ignorantes como as outras moças; mas Lizzy tem um pouco mais de vivacidade do que as irmãs.","mrbennethowcanyouabuseyourownchildrenins~compassiononmypoornerves~104":"“Sr. Bennet, como pode maltratar assim seus próprios filhos? Você tem prazer em me aborrecer. Não tem compaixão alguma pelos meus pobres nervos.”","youmistakememydearihaveahighrespectforyo~nthesetwentyyearsatleast~131":"“Engana-se, minha querida. Tenho grande respeito pelos seus nervos. São meus velhos amigos. Ouço-a mencioná-los com consideração há pelo menos vinte anos.”","ahyoudonotknowwhatisuffer~hyoudonotknowwhatisuffer~25":"“Ah! você não sabe o que eu sofro.”","butihopeyouwillgetoveritandlivetoseemany~comeintotheneighbourhood~91":"“Mas espero que se recupere e viva para ver muitos rapazes de quatro mil libras por ano virem morar na vizinhança.”","itwillbenousetousiftwentysuchshouldcomes~sinceyouwillnotvisitthem~63":"“De nada nos servirá, mesmo que venham vinte deles, já que você não os visitará.”","dependuponitmydearthatwhentherearetwenty~etwentyiwillvisitthemall~57":"“Pode estar certa, minha querida, de que, quando forem vinte, visitarei todos.”","mrbennetwassooddamixtureofquickpartssarc~solacewasvisitingandnews~378":"O Sr. Bennet era uma mistura tão estranha de vivacidade de espírito, humor sarcástico, reserva e capricho que a experiência de vinte e três anos não fora suficiente para que a esposa lhe compreendesse o caráter. O espírito dela era menos difícil de decifrar. Era mulher de entendimento medíocre, pouca instrução e temperamento instável. Quando estava descontente, imaginava-se nervosa. A ocupação de sua vida era casar as filhas; seu consolo, as visitas e as novidades.","mrbennetwasamongtheearliestofthosewhowai~suddenlyaddressedherwith~306":"O Sr. Bennet foi um dos primeiros a visitar o Sr. Bingley. Sempre tivera a intenção de fazê-lo, embora até o último momento continuasse assegurando à esposa que não iria; e, até a noite depois da visita, ela nada soube. Foi então revelado do seguinte modo. Ao ver a segunda filha ocupada em enfeitar um chapéu, ele lhe dirigiu de repente estas palavras:","ihopemrbingleywilllikeitlizzy~mrbingleywilllikeitlizzy~29":"“Espero que o Sr. Bingley goste dele, Lizzy.”","wearenotinawaytoknowwhatmrbingleylikessa~ullysincewearenottovisit~82":"“Não estamos em condições de saber de que o Sr. Bingley gosta,” disse a mãe, ressentida, “já que não vamos visitá-lo.”","butyouforgetmamasaidelizabeththatweshall~aspromisedtointroducehim~101":"“Mas a senhora se esquece, mamãe,” disse Elizabeth, “de que o encontraremos nos bailes públicos, e de que a Sra. Long prometeu apresentá-lo.”","idonotbelievemrslongwilldoanysuchthingsh~anandihavenoopinionofher~113":"“Não acredito que a Sra. Long faça tal coisa. Tem duas sobrinhas dela. É uma mulher egoísta e hipócrita, e não tenho a menor opinião dela.”","nomorehaveisaidmrbennetandiamgladtofindt~notdependonherservingyou~72":"“Nem eu,” disse o Sr. Bennet; “e fico contente em ver que você não conta com os serviços dela.”","mrsbennetdeignednottomakeanyreplybutunab~coldingoneofherdaughters~88":"A Sra. Bennet não se dignou responder; mas, incapaz de se conter, pôs-se a repreender uma das filhas.","dontkeepcoughingsokittyforheavenssakehav~ervesyoutearthemtopieces~87":"“Não fique tossindo assim, Kitty, pelo amor de Deus! Tenha um pouco de compaixão dos meus nervos. Você os despedaça.”","kittyhasnodiscretioninhercoughssaidherfa~herfathershetimesthemill~59":"“Kitty não tem discrição nas suas tosses,” disse o pai; “escolhe mal o momento.”","idonotcoughformyownamusementrepliedkitty~entrepliedkittyfretfully~49":"“Não tusso para meu próprio divertimento,” replicou Kitty, irritada.","whenisyournextballtobelizzy~nisyournextballtobelizzy~27":"“Quando é o seu próximo baile, Lizzy?”","tomorrowfortnight~tomorrowfortnight~17":"“Daqui a quinze dias, amanhã.”","ayesoitiscriedhermotherandmrslongdoesnot~shewillnotknowhimherself~131":"“Ah, é verdade,” exclamou a mãe, “e a Sra. Long só volta na véspera; assim, será impossível que ela o apresente, pois ela mesma não o conhecerá.”","thenmydearyoumayhavetheadvantageofyourfr~dintroducemrbingleytoher~70":"“Então, minha querida, você poderá levar vantagem sobre a sua amiga e apresentar-lhe o Sr. Bingley.”","impossiblemrbennetimpossiblewheniamnotac~selfhowcanyoubesoteasing~81":"“Impossível, Sr. Bennet, impossível, quando eu mesma não o conheço; como pode ser tão provocador?”","ihonouryourcircumspectionafortnightsacqu~fficeiwilltakeitonmyself~286":"“Honro a sua circunspecção. Quinze dias de conhecimento são certamente muito pouco. Não se pode saber o que um homem realmente é ao fim de quinze dias. Mas, se não nos aventurarmos, alguém o fará; e, afinal, a Sra. Long e as sobrinhas têm de correr o seu risco; e portanto, como ela julgará um ato de bondade, se você declinar do encargo, eu mesmo o tomarei a meu cargo.”","thegirlsstaredattheirfathermrsbennetsaid~saidonlynonsensenonsense~60":"As moças fitaram o pai. A Sra. Bennet disse apenas: “Absurdo, absurdo!”","whatcanbethemeaningofthatemphaticexclama~reatbooksandmakeextracts~239":"“Qual pode ser o sentido dessa exclamação enfática?” exclamou ele. “Considera as formalidades da apresentação, e a importância que se lhes dá, um absurdo? Não posso concordar inteiramente com você nisso. Que diz você, Mary? Pois é uma jovem de profunda reflexão, bem o sei, que lê grandes livros e faz extratos.”","marywishedtosaysomethingverysensiblebutk~erysensiblebutknewnothow~49":"Mary queria dizer algo muito sensato, mas não sabia como.","whilemaryisadjustingherideashecontinuedl~edletusreturntomrbingley~61":"“Enquanto Mary ajusta as suas ideias,” continuou ele, “voltemos ao Sr. Bingley.”","iamsickofmrbingleycriedhiswife~kofmrbingleycriedhiswife~30":"“Estou farta do Sr. Bingley,” exclamou a esposa.","iamsorrytohearthatbutwhydidnotyoutellmes~escapetheacquaintancenow~185":"“Lamento ouvir isso; mas por que não me disse antes? Se eu soubesse disso hoje de manhã, certamente não o teria visitado. É muito azar; mas, como de fato fiz a visita, já não podemos escapar à amizade.”","theastonishmentoftheladieswasjustwhathew~hehadexpectedallthewhile~175":"O espanto das senhoras foi exatamente o que ele desejava; o da Sra. Bennet talvez superou o das outras; embora, passado o primeiro tumulto de alegria, ela começasse a declarar que era o que havia esperado desde o princípio.","howgooditwasinyoumydearmrbennetbutiknewi~rsaidawordaboutittillnow~225":"“Que bondade a sua, meu caro Sr. Bennet! Mas eu sabia que acabaria por persuadi-lo. Tinha certeza de que amava demais suas filhas para negligenciar tal conhecimento. Ora, como estou contente! E que boa brincadeira também, ter ido esta manhã e não ter dito uma palavra até agora.”","nowkittyyoumaycoughasmuchasyouchoosesaid~withtherapturesofhiswife~105":"“Agora, Kitty, pode tossir quanto quiser,” disse o Sr. Bennet; e, ao falar, deixou a sala, fatigado com os arroubos da esposa.","whatanexcellentfatheryouhavegirlssaidshe~ancewithyouatthenextball~320":"“Que excelente pai vocês têm, meninas,” disse ela, quando a porta se fechou. “Não sei como poderão algum dia retribuir-lhe tanta bondade; nem a mim, aliás. Na nossa idade, não é tão agradável, posso dizer-lhes, fazer novos conhecimentos todos os dias; mas, por vocês, faríamos qualquer coisa. Lydia, meu amor, embora seja a mais nova, ouso dizer que o Sr. Bingley dançará com você no próximo baile.”","ohsaidlydiastoutlyiamnotafraidforthoughi~mtheyoungestimthetallest~65":"“Oh!” disse Lydia, resoluta, “não tenho medo; pois, embora seja a mais nova, sou a mais alta.”","therestoftheeveningwasspentinconjecturin~theyshouldaskhimtodinner~117":"O resto da noite passou-se em conjeturas sobre quão cedo ele retribuiria a visita do Sr. Bennet e em decidir quando o convidariam para jantar.","notallthatmrsbennethoweverwiththeassista~leysheartwereentertained~654":"Tudo, porém, o que a Sra. Bennet, com a ajuda das cinco filhas, pôde perguntar sobre o assunto não bastou para arrancar do marido qualquer descrição satisfatória do Sr. Bingley. Atacaram-no de várias maneiras: com perguntas descaradas, suposições engenhosas e conjeturas distantes; mas ele iludiu a habilidade de todas elas; e por fim foram obrigadas a aceitar a informação de segunda mão da vizinha Lady Lucas. O relato dela era altamente favorável. Sir William ficara encantado com ele. Era bem jovem, maravilhosamente bonito, extremamente agradável e, para coroar tudo, pretendia comparecer ao próximo baile com um grande grupo. Nada poderia ser mais delicioso! Gostar de dançar era um passo certo para se enamorar; e nutriam-se vivíssimas esperanças quanto ao coração do Sr. Bingley.","ificanbutseeoneofmydaughtershappilysettl~hallhavenothingtowishfor~139":"“Se eu puder ver ao menos uma de minhas filhas felizmente estabelecida em Netherfield,” disse a Sra. Bennet ao marido, “e todas as outras igualmente bem casadas, nada mais terei a desejar.”","inafewdaysmrbingleyreturnedmrbennetsvisi~uecoatandrodeablackhorse~313":"Poucos dias depois, o Sr. Bingley retribuiu a visita do Sr. Bennet e ficou cerca de dez minutos com ele na biblioteca. Tinha esperanças de ser admitido a ver as moças, de cuja beleza ouvira falar muito; mas viu apenas o pai. As senhoras tiveram um pouco mais de sorte, pois puderam verificar, de uma janela do andar de cima, que ele vestia um casaco azul e montava um cavalo preto.","aninvitationtodinnerwassoonafterwardsdis~eldestandanotheryoungman~965":"Logo depois foi despachado um convite para jantar; e a Sra. Bennet já planejara os pratos que honrariam sua administração doméstica quando chegou uma resposta que adiou tudo. O Sr. Bingley era obrigado a estar na cidade no dia seguinte e, consequentemente, não podia aceitar a honra do convite, etc. A Sra. Bennet ficou completamente desconcertada. Não conseguia imaginar que negócios ele poderia ter na cidade tão pouco depois de sua chegada a Hertfordshire; e começou a temer que ele estivesse sempre voando de um lugar a outro, e nunca fixado em Netherfield como devia. Lady Lucas acalmou-lhe um pouco os temores lançando a ideia de que ele fora a Londres apenas para arranjar um grande grupo para o baile; e logo se seguiu o boato de que o Sr. Bingley traria consigo doze damas e sete cavalheiros ao baile. As moças se afligiram com tamanho número de damas; mas se consolaram na véspera do baile ao saber que, em vez de doze, ele trouxera de Londres apenas seis, suas cinco irmãs e uma prima. E quando o grupo entrou no salão, compunha-se de apenas cinco pessoas ao todo: o Sr. Bingley, suas duas irmãs, o marido da mais velha e outro rapaz.","mrbingleywasgoodlookingandgentlemanlikeh~obecomparedwithhisfriend~790":"O Sr. Bingley era bem-parecido e de modos cavalheirescos; tinha um semblante agradável e maneiras fáceis e sem afetação. As irmãs eram belas mulheres, com um ar de decidida elegância. O cunhado, Sr. Hurst, tinha apenas o aspecto de cavalheiro; mas o amigo, Sr. Darcy, logo atraiu a atenção do salão por sua bela e alta figura, seus traços bonitos, seu porte nobre e pelo rumor, que circulou geralmente cinco minutos depois de sua entrada, de que tinha dez mil libras por ano. Os cavalheiros o proclamaram um belo exemplar de homem, as damas declararam que era muito mais bonito que o Sr. Bingley, e ele foi olhado com grande admiração durante cerca de metade da noite, até que suas maneiras causaram uma repulsa que virou a maré de sua popularidade; pois descobriram que era orgulhoso, que se julgava acima da companhia e acima de se deixar agradar; e nem toda a sua vasta propriedade em Derbyshire pôde então salvá-lo de ter um semblante extremamente severo e desagradável e de ser indigno de comparação com o amigo.","mrbingleyhadsoonmadehimselfacquaintedwit~lightedoneofherdaughters~700":"O Sr. Bingley logo travou conhecimento com todas as pessoas principais do salão; era vivo e franco, dançou todas as danças, zangou-se por o baile terminar tão cedo e falou em dar um ele mesmo em Netherfield. Tão amáveis qualidades falam por si. Que contraste entre ele e o amigo! O Sr. Darcy dançou apenas uma vez com a Sra. Hurst e uma vez com a Srta. Bingley, recusou ser apresentado a qualquer outra dama e passou o resto da noite a andar pelo salão, falando de vez em quando com alguém de seu grupo. Seu caráter estava decidido. Era o homem mais orgulhoso e mais desagradável do mundo, e todos esperavam que nunca mais voltasse ali. Entre os mais violentos contra ele estava a Sra. Bennet, cuja aversão ao seu comportamento em geral se aguçara em ressentimento particular por ele ter desprezado uma de suas filhas.","elizabethbennethadbeenobligedbythescarci~topresshisfriendtojoinit~237":"Elizabeth Bennet fora obrigada, pela escassez de cavalheiros, a ficar sentada durante duas danças; e, durante parte desse tempo, o Sr. Darcy estivera de pé perto o bastante para que ela ouvisse uma conversa entre ele e o Sr. Bingley, que viera da dança por alguns minutos para instar o amigo a juntar-se a ela.","comedarcysaidheimusthaveyoudanceihatetos~neryouhadmuchbetterdance~107":"“Vamos, Darcy,” disse ele, “preciso que você dance. Detesto vê-lo parado sozinho dessa maneira estúpida. É muito melhor dançar.”","icertainlyshallnotyouknowhowidetestitunl~ishmenttometostandupwith~224":"“Certamente não o farei. Você sabe como detesto isso, a menos que conheça particularmente a minha parceira. Num baile como este, seria insuportável. Suas irmãs estão comprometidas, e não há no salão outra mulher com quem não fosse um castigo para mim dançar.”","iwouldnotbesofastidiousasyouarecriedbing~emyouseeuncommonlypretty~170":"“Eu não seria tão exigente como você,” exclamou Bingley, “nem por um reino! Palavra de honra, nunca encontrei na vida tantas moças agradáveis como esta noite; e várias delas, como vê, são extraordinariamente bonitas.”","youaredancingwiththeonlyhandsomegirlinth~ingattheeldestmissbennet~84":"“Você está dançando com a única moça bonita do salão,” disse o Sr. Darcy, olhando para a Srta. Bennet mais velha.","ohsheisthemostbeautifulcreatureieverbehe~kmypartnertointroduceyou~163":"“Oh! ela é a criatura mais bela que já vi! Mas há uma de suas irmãs sentada logo atrás de você, que é muito bonita e, ouso dizer, muito agradável. Deixe que eu peça à minha parceira que o apresente.”","whichdoyoumeanandturningroundhelookedfor~arewastingyourtimewithme~305":"“A qual se refere?” e, voltando-se, olhou por um instante para Elizabeth, até que, encontrando-lhe o olhar, desviou o seu e disse friamente: “É tolerável; mas não bonita o bastante para me tentar; e não estou de humor, no momento, para dar importância a moças desprezadas por outros homens. É melhor você voltar à sua parceira e desfrutar de seus sorrisos, pois está perdendo tempo comigo.”","mrbingleyfollowedhisadvicemrdarcywalkedo~htedinanythingridiculous~217":"O Sr. Bingley seguiu o conselho. O Sr. Darcy afastou-se; e Elizabeth ficou com sentimentos pouco cordiais a seu respeito. Contou, porém, a história com grande verve entre as amigas; pois tinha um temperamento vivo e brincalhão, que se deleitava com tudo o que fosse ridículo.","theeveningaltogetherpassedoffpleasantlyt~verydifferentstorytohear~865":"A noite, em conjunto, transcorreu agradavelmente para toda a família. A Sra. Bennet vira a filha mais velha muito admirada pelo grupo de Netherfield. O Sr. Bingley dançara com ela duas vezes e ela fora distinguida pelas irmãs dele. Jane ficou tão gratificada com isso quanto a mãe, embora de modo mais sereno. Elizabeth sentiu o prazer de Jane. Mary ouvira-se mencionada à Srta. Bingley como a moça mais prendada da vizinhança; e Catherine e Lydia tiveram a sorte de nunca ficar sem par, o que era tudo com que haviam aprendido até então a se importar num baile. Voltaram, portanto, bem-dispostas a Longbourn, a aldeia onde moravam e da qual eram as principais habitantes. Encontraram o Sr. Bennet ainda acordado. Com um livro, ele esquecia as horas; e na presente ocasião tinha bastante curiosidade quanto ao desfecho de uma noite que suscitara tão esplêndidas expectativas. Esperara antes que todas as ilusões da esposa sobre o forasteiro fossem frustradas; mas logo viu que tinha uma história muito diferente para ouvir.","ohmydearmrbennetassheenteredtheroomwehav~withlizzyandtheboulanger~688":"“Oh! meu caro Sr. Bennet,” disse ela ao entrar na sala, “tivemos uma noite deliciosa, um baile excelente. Gostaria que você tivesse estado lá. Jane foi tão admirada que nada se lhe compara. Todos diziam como estava bem; e o Sr. Bingley a achou belíssima e dançou com ela duas vezes. Pense só nisso, meu caro; ele dançou mesmo com ela duas vezes; e ela foi a única criatura do salão a quem ele convidou uma segunda vez. Primeiro de tudo, convidou a Srta. Lucas. Fiquei tão vexada de vê-lo dançar com ela; mas, enfim, ele não a admirou nem um pouco: aliás, ninguém pode, você sabe; e pareceu muito impressionado com Jane quando ela descia a dança. Então perguntou quem ela era, fez-se apresentar e pediu-lhe as duas seguintes. Depois, as duas terceiras dançou com a Srta. King, as duas quartas com Maria Lucas, as duas quintas de novo com Jane, as duas sextas com Lizzy, e a Boulanger…”","ifhehadhadanycompassionformecriedherhusb~dhisankleinthefirstdance~159":"“Se ele tivesse tido alguma compaixão de mim,” exclamou o marido, impaciente, “não teria dançado nem metade! Pelo amor de Deus, não fale mais das parceiras dele. Oh! quem dera tivesse torcido o tornozelo na primeira dança!”","ohmydearcontinuedmrsbennetiamquitedeligh~thelaceuponmrshurstsgown~188":"“Oh! meu caro,” continuou a Sra. Bennet, “estou encantada com ele. É excessivamente bonito! e as irmãs são mulheres encantadoras. Nunca em minha vida vi nada mais elegante do que os vestidos delas. Ouso dizer que a renda do vestido da Sra. Hurst…”","hereshewasinterruptedagainmrbennetprotes~hockingrudenessofmrdarcy~208":"Aqui foi interrompida de novo. O Sr. Bennet protestou contra toda descrição de adornos. Foi, portanto, obrigada a buscar outro ramo do assunto e relatou, com muita amargura de espírito e alguma exageração, a chocante grosseria do Sr. Darcy.","buticanassureyousheaddedthatlizzydoesnot~tdownsiquitedetesttheman~324":"“Mas posso assegurar-lhe,” acrescentou, “que Lizzy não perde muito por não agradar ao gosto dele; pois é um homem desagradabilíssimo, horrível, que não vale de modo algum a pena agradar. Tão altivo e tão presunçoso que era impossível suportá-lo! Andava para cá, andava para lá, julgando-se tão grande! Não bonita o bastante para dançar! Gostaria que você tivesse estado lá, meu caro, para dar-lhe uma de suas lições. Detesto de todo o coração esse homem.”"}$tr$::jsonb, 82)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- jane-austen_sense-and-sensibility (64 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('jane-austen_sense-and-sensibility', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"chapteri":"Capítulo I","chapterii":"Capítulo II","chapteriii":"Capítulo III"}$tr$::jsonb, $tr${"thefamilyofdashwoodhadlongbeensettledins~dedarelishtohisexistence~955":"A família Dashwood estava havia muito estabelecida em Sussex. Sua propriedade era grande, e sua residência ficava em Norland Park, no centro de suas terras, onde, por muitas gerações, viveram de maneira tão respeitável que conquistaram a boa opinião geral de seus vizinhos e conhecidos. O último dono da propriedade era um homem solteiro, que viveu até idade muito avançada e que, durante muitos anos de sua vida, teve na irmã uma companheira constante e governanta da casa. Mas a morte dela, ocorrida dez anos antes da sua, produziu grande mudança em seu lar; pois, para suprir-lhe a perda, convidou e recebeu em casa a família de seu sobrinho, o Sr. Henry Dashwood, herdeiro legítimo da propriedade de Norland e a pessoa a quem pretendia legá-la. Na companhia do sobrinho, da sobrinha e dos filhos deles, os dias do velho cavalheiro transcorreram confortavelmente. Sua afeição por todos aumentou. A atenção constante do Sr. e da Sra. Henry Dashwood a seus desejos, que procedia não somente de interesse, mas de bondade de coração, deu-lhe todo o grau de sólido conforto que sua idade podia receber; e a alegria das crianças acrescentava sabor à sua existência.","byaformermarriagemrhenrydashwoodhadoneso~hadonlyalifeinterestinit~627":"De um casamento anterior, o Sr. Henry Dashwood tinha um filho; de sua atual esposa, três filhas. O filho, rapaz sério e respeitável, estava amplamente provido pela fortuna da mãe, que fora grande, e da qual metade lhe coube ao atingir a maioridade. Com o próprio casamento, ocorrido logo depois, aumentou também sua riqueza. Para ele, portanto, a sucessão da propriedade de Norland não era tão realmente importante quanto para as irmãs; pois a fortuna delas, independente do que lhes pudesse advir de o pai herdar aquela propriedade, não podia ser senão pequena. A mãe nada tinha, e o pai apenas sete mil libras à sua livre disposição; pois a metade restante da fortuna de sua primeira esposa também estava assegurada ao filho dela, e ele tinha sobre ela apenas o usufruto vitalício.","theoldgentlemandiedhiswillwasreadandlike~hemathousandpoundsapiece~993":"O velho cavalheiro morreu: seu testamento foi lido e, como quase todos os testamentos, deu tanta decepção quanto prazer. Não foi tão injusto nem tão ingrato a ponto de tirar a propriedade do sobrinho; mas deixou-a a ele em condições que destruíam metade do valor do legado. O Sr. Dashwood a desejara mais por causa da esposa e das filhas do que por si ou pelo filho; mas ao filho, e ao filho do filho, um menino de quatro anos, ela foi assegurada de tal modo que o deixava sem poder algum de prover aqueles que lhe eram mais caros, e que mais precisavam de provisão, seja por algum encargo sobre a propriedade, seja pela venda de seus valiosos bosques. Tudo foi vinculado em benefício dessa criança, que, em visitas ocasionais com o pai e a mãe a Norland, havia ganhado de tal modo a afeição do tio, por atrativos de modo algum incomuns em crianças de dois ou três anos — uma articulação imperfeita, um desejo ardente de fazer a própria vontade, muitas travessuras manhosas e muito barulho — que superou todo o valor de todas as atenções que, por anos, ele recebera da sobrinha e das filhas dela. Não pretendia, contudo, ser indelicado e, como prova de sua afeição pelas três meninas, deixou-lhes mil libras a cada uma.","mrdashwoodsdisappointmentwasatfirstsever~dforhiswidowanddaughters~407":"A decepção do Sr. Dashwood foi, a princípio, severa; mas seu temperamento era alegre e otimista; e ele podia razoavelmente esperar viver muitos anos e, vivendo com economia, juntar uma soma considerável com o rendimento de uma propriedade já grande e capaz de melhoramento quase imediato. Mas a fortuna, que tanto tardara a chegar, foi sua por apenas um ano. Não sobreviveu ao tio por mais tempo; e dez mil libras, incluindo os recentes legados, era tudo o que restava à viúva e às filhas.","hissonwassentforassoonashisdangerwasknow~hismotherinlawandsisters~159":"Mandou-se chamar o filho assim que se soube do perigo em que estava, e a ele o Sr. Dashwood recomendou, com toda a força e a urgência que a doença permitia, os interesses da madrasta e das irmãs.","mrjohndashwoodhadnotthestrongfeelingsoft~ybeinhispowertodoforthem~303":"O Sr. John Dashwood não tinha os fortes sentimentos do resto da família; mas comoveu-se com uma recomendação de tal natureza em tal momento e prometeu fazer tudo o que estivesse em seu poder para deixá-las confortáveis. O pai tranquilizou-se com essa garantia, e o Sr. John Dashwood teve então vagar para considerar quanto, prudentemente, lhe seria possível fazer por elas.","hewasnotanilldisposedyoungmanunlesstober~renarrowmindedandselfish~423":"Não era um rapaz de mau coração, a menos que ser bastante frio e bastante egoísta seja ter mau coração; mas era, em geral, bem-visto, pois se conduzia com decoro no cumprimento de seus deveres ordinários. Tivesse-se casado com uma mulher mais amável, poderia ter sido ainda mais respeitável do que era; poderia até ter-se tornado ele próprio amável, pois era muito jovem quando se casou e muito apegado à esposa. Mas a Sra. John Dashwood era uma forte caricatura dele mesmo: mais estreita de espírito e mais egoísta.","whenhegavehispromisetohisfatherhemeditat~ssivelyandhedidnotrepent~549":"Quando fez a promessa ao pai, meditou consigo mesmo em aumentar a fortuna das irmãs com o presente de mil libras a cada uma. Julgava-se então, realmente, à altura disso. A perspectiva de quatro mil por ano, além da renda de que já dispunha e da metade restante da fortuna da própria mãe, aqueceu-lhe o coração e fê-lo sentir-se capaz de generosidade. “Sim, daria a elas três mil libras: seria liberal e belo! Bastaria para deixá-las inteiramente à vontade. Três mil libras! poderia dispensar tão considerável quantia com pouco incômodo.” Pensou nisso o dia inteiro e por muitos dias seguidos, e não se arrependeu.","nosoonerwashisfathersfuneraloverthanmrsj~ctwhenoccasionrequiredit~695":"Mal terminara o funeral do pai, a Sra. John Dashwood, sem enviar à sogra qualquer aviso de sua intenção, chegou com o filho e os criados. Ninguém podia contestar-lhe o direito de vir; a casa era do marido desde o instante do falecimento do pai; mas tanto maior era a indelicadeza de sua conduta, que, para uma mulher na situação da Sra. Dashwood, com sentimentos apenas comuns, devia ter sido altamente desagradável; mas em seu espírito havia um senso de honra tão aguçado, uma generosidade tão romântica, que qualquer ofensa dessa espécie, por quem quer que a desse ou recebesse, era para ela fonte de uma repugnância inabalável. A Sra. John Dashwood nunca fora favorita de ninguém da família do marido; mas não tivera, até então, ocasião de lhes mostrar com quão pouca atenção ao conforto alheio podia agir quando a ocasião o exigia.","soacutelydidmrsdashwoodfeelthisungraciou~dabreachwiththeirbrother~350":"Tão agudamente sentiu a Sra. Dashwood esse comportamento descortês, e tão sinceramente desprezou por ele a nora, que, à chegada desta, teria deixado a casa para sempre, não a tivessem induzido primeiro o rogo da filha mais velha a refletir sobre a conveniência de partir, e depois o seu terno amor pelos três filhos a decidir ficar e, por amor deles, evitar uma ruptura com o irmão.","elinorthiseldestdaughterwhoseadvicewasso~dresolvednevertobetaught~484":"Elinor, essa filha mais velha, cujo conselho tinha tanta eficácia, possuía uma força de entendimento e uma frieza de juízo que a qualificavam, embora com apenas dezenove anos, para ser conselheira da mãe e a capacitavam a contrabalançar com frequência, em proveito de todos, aquela ânsia de espírito da Sra. Dashwood que geralmente a teria levado à imprudência. Tinha excelente coração; seu temperamento era afetuoso e seus sentimentos fortes; mas sabia governá-los: era um saber que a mãe ainda tinha de aprender e que uma das irmãs resolvera nunca aprender.","mariannesabilitieswereinmanyrespectsquit~motherwasstrikinglygreat~248":"Os talentos de Marianne eram, em muitos aspectos, bem iguais aos de Elinor. Era sensata e inteligente; mas ardorosa em tudo: suas tristezas e suas alegrias não podiam ter moderação. Era generosa, amável, interessante: era tudo, menos prudente. A semelhança entre ela e a mãe era notavelmente grande.","elinorsawwithconcerntheexcessofhersister~ehertosimilarforbearance~647":"Elinor via com preocupação o excesso de sensibilidade da irmã; mas a Sra. Dashwood o prezava e acalentava. Encorajavam-se agora mutuamente na violência da aflição. A agonia da dor que as dominara no início era voluntariamente renovada, era buscada, era criada de novo a cada vez. Entregavam-se por inteiro ao seu pesar, buscando aumento de desgraça em toda reflexão que pudesse proporcioná-lo, e resolvidas a nunca admitir consolo no futuro. Elinor também estava profundamente aflita; mas ainda assim podia lutar, podia esforçar-se. Podia consultar o irmão, receber a cunhada à sua chegada e tratá-la com a devida atenção; e podia empenhar-se em despertar a mãe para igual esforço e animá-la a igual tolerância.","margarettheothersisterwasagoodhumoredwel~moreadvancedperiodoflife~202":"Margaret, a outra irmã, era uma moça de bom humor e boa índole; mas, como já havia absorvido muito do romantismo de Marianne sem ter muito do seu juízo, não prometia, aos treze anos, igualar as irmãs em época mais avançada da vida.","mrsjohndashwoodnowinstalledherselfmistre~hisinvitationwasaccepted~463":"A Sra. John Dashwood instalou-se agora como senhora de Norland; e a sogra e as cunhadas foram rebaixadas à condição de visitas. Como tais, porém, eram tratadas por ela com discreta civilidade, e pelo marido com tanta bondade quanto ele podia sentir por alguém fora ele mesmo, a esposa e o filho. Instou-as realmente, com certo empenho, a considerar Norland como seu lar; e, como nenhum plano parecesse tão desejável à Sra. Dashwood quanto ficar ali até poder arranjar uma casa na vizinhança, o convite foi aceito.","acontinuanceinaplacewhereeverythingremin~leasureshewasbeyondalloy~329":"Permanecer num lugar em que tudo lhe recordava a antiga felicidade era exatamente o que convinha ao seu espírito. Nas épocas de alegria, nenhum temperamento podia ser mais alegre que o dela, nem possuir em maior grau aquela confiante expectativa de felicidade que é a própria felicidade. Mas na tristeza ela era igualmente arrebatada pela fantasia, e tão além do consolo quanto no prazer estava além de qualquer mistura de amargura.","mrsjohndashwooddidnotatallapproveofwhath~hismoneytohishalfsisters~623":"A Sra. John Dashwood não aprovava de modo algum o que o marido pretendia fazer pelas irmãs. Tirar três mil libras da fortuna do querido filhinho de ambos seria empobrecê-lo da maneira mais terrível. Pediu-lhe que pensasse de novo no assunto. Como poderia ele responder a si mesmo por roubar o filho, e filho único, de quantia tão grande? E que possível direito poderiam ter as Srtas. Dashwood, que só lhe eram aparentadas por meio-sangue, o que ela considerava como parentesco nenhum, à generosidade dele em soma tão grande? Era sabidíssimo que nunca se supunha existir afeição entre os filhos de um mesmo homem por casamentos diferentes; e por que haveria ele de arruinar-se, e ao pobre Harry, dando todo o seu dinheiro às meias-irmãs?","itwasmyfatherslastrequesttomerepliedherh~sisthiswidowanddaughters~83":"“Foi o último pedido de meu pai a mim,” respondeu o marido, “que eu auxiliasse a viúva e as filhas.”","hedidnotknowwhathewastalkingofidaresayte~rfortunefromyourownchild~185":"“Não sabia o que dizia, ouso afirmar; dez contra um que estava delirando na hora. Se estivesse em seu juízo, não poderia ter pensado em coisa tal como pedir-lhe que desse metade da sua fortuna, tirada do próprio filho.”","hedidnotstipulateforanyparticularsummyde~rlandandsettleinanewhome~432":"“Não estipulou nenhuma quantia em particular, minha cara Fanny; pediu-me apenas, em termos gerais, que as auxiliasse e tornasse a situação delas mais confortável do que estava em seu poder fazer. Talvez tivesse sido igualmente bom se tivesse deixado tudo a meu critério. Dificilmente poderia supor que eu as negligenciasse. Mas, como exigiu a promessa, não podia deixar de dá-la; pelo menos pensei assim na ocasião. A promessa, portanto, foi dada e deve ser cumprida. Algo deve ser feito por elas quando deixarem Norland e se estabelecerem numa nova casa.”","wellthenletsomethingbedoneforthembutthat~storedtoourpoorlittleboy~226":"“Pois bem, que se faça algo por elas; mas esse algo não precisa ser três mil libras. Considere,” acrescentou, “que, uma vez que o dinheiro sai das mãos, nunca mais volta. Suas irmãs se casarão, e ele estará perdido para sempre. Se ao menos pudesse ser restituído ao nosso pobre filhinho…”","whytobesuresaidherhusbandverygravelythat~eaveryconvenientaddition~197":"“Ora, é claro,” disse o marido, muito grave, “isso faria grande diferença. Pode chegar o tempo em que Harry se lamente de que tão grande soma tenha sido dada. Se tiver uma família numerosa, por exemplo, seria um acréscimo muito conveniente.”","tobesureitwould~tobesureitwould~15":"“É claro que seria.”","perhapsthenitwouldbebetterforallpartiesi~sincreasetotheirfortunes~126":"“Talvez, então, fosse melhor para todos se a quantia fosse reduzida à metade. Quinhentas libras seriam um aumento prodigioso à fortuna delas!”","ohbeyondanythinggreatwhatbrotheronearthw~uhavesuchagenerousspirit~142":"“Oh! além de qualquer expectativa! Que irmão na terra faria nem metade disso pelas irmãs, ainda que fossem realmente irmãs! E sendo como é, apenas meio-sangue!… Mas você tem um espírito tão generoso!”","iwouldnotwishtodoanythingmeanherepliedon~stheycanhardlyexpectmore~169":"“Não gostaria de fazer nada mesquinho,” respondeu ele. “Prefere-se, em tais ocasiões, fazer demais a fazer de menos. Ninguém, ao menos, poderá pensar que não fiz o bastante por elas; elas mesmas dificilmente esperarão mais.”","thereisnoknowingwhattheymayexpectsaidthe~oniswhatyoucanaffordtodo~114":"“Não se sabe o que podem esperar,” disse a dama, “mas não devemos pensar nas expectativas delas: a questão é o que você pode se permitir fazer.”","certainlyandithinkimayaffordtogivethemfi~efortuneforanyyoungwoman~189":"“Certamente; e creio poder me permitir dar-lhes quinhentas libras a cada uma. Como estão as coisas, sem qualquer acréscimo meu, terão cada uma cerca de três mil libras por morte da mãe, fortuna muito confortável para qualquer moça.”","tobesureitisandindeeditstrikesmethatthey~erestoftenthousandpounds~228":"“Sem dúvida; e, na verdade, parece-me que não precisam de acréscimo algum. Terão dez mil libras divididas entre si. Se se casarem, estarão certas de se dar bem, e se não se casarem, poderão viver todas muito confortavelmente juntas com os juros de dez mil libras.”","thatisverytrueandthereforeidonotknowwhet~mallperfectlycomfortable~267":"“Isso é muito verdade e, portanto, não sei se, no conjunto, não seria mais aconselhável fazer algo pela mãe enquanto viver, em vez de por elas; algo da espécie de uma pensão vitalícia, quero dizer. Minhas irmãs sentiriam os bons efeitos tanto quanto ela. Cem por ano deixariam todas perfeitamente confortáveis.”","hiswifehesitatedalittlehoweveringivinghe~vingherconsenttothisplan~58":"A esposa hesitou um pouco, contudo, em dar consentimento a esse plano.","tobesuresaidsheitisbetterthanpartingwith~shallbecompletelytakenin~134":"“É verdade,” disse ela, “que é melhor do que desfazer-se de mil e quinhentas libras de uma vez. Mas, então, se a Sra. Dashwood viver quinze anos, seremos completamente enganados.”","fifteenyearsmydearfannyherlifecannotbewo~tbeworthhalfthatpurchase~59":"“Quinze anos! minha cara Fanny; a vida dela não pode valer nem metade dessa compra.”","certainlynotbutifyouobservepeoplealwaysl~ymentofoneforalltheworld~863":"“Certamente não; mas, se reparar, as pessoas vivem sempre eternamente quando há uma pensão a pagar-lhes; e ela é muito robusta e saudável, e mal chegou aos quarenta. Uma pensão vitalícia é coisa muito séria; volta uma e outra vez a cada ano, e não há como se livrar dela. Você não sabe o que está fazendo. Conheço muito dos aborrecimentos das pensões; pois minha mãe ficou onerada com o pagamento de três a velhos criados aposentados, pelo testamento de meu pai, e é espantoso como achou isso desagradável. Duas vezes por ano essas pensões tinham de ser pagas; e depois havia o trabalho de fazê-las chegar aos beneficiários; e depois disseram que um deles tinha morrido, e mais tarde descobriu-se que nada disso. Minha mãe ficou completamente enjoada. Sua renda não era sua, dizia ela, com tais reivindicações perpétuas sobre ela; e foi tanto mais cruel da parte de meu pai porque, sem isso, o dinheiro estaria inteiramente à disposição de minha mãe, sem restrição alguma. Isso me deu tal horror às pensões vitalícias que tenho certeza de que não me prenderia ao pagamento de uma por nada deste mundo.”","itiscertainlyanunpleasantthingrepliedmrd~akesawayonesindependence~235":"“É certamente desagradável,” respondeu o Sr. Dashwood, “ter esse tipo de sangria anual na renda. A fortuna da gente, como diz com justiça sua mãe, não é da gente. Estar preso ao pagamento regular de tal soma em cada dia de aluguel não é de modo algum desejável: tira a independência.”","undoubtedlyandafterallyouhavenothanksfor~poundsfromourownexpenses~308":"“Sem dúvida; e, afinal, você não recebe agradecimento por isso. Elas se julgam seguras, você não faz mais do que se espera, e não desperta gratidão alguma. Se eu fosse você, tudo o que fizesse seria inteiramente a meu arbítrio. Não me obrigaria a lhes dar coisa alguma anualmente. Pode ser muito inconveniente, em certos anos, poupar cem, ou mesmo cinquenta libras das nossas próprias despesas.”","ibelieveyouarerightmyloveitwillbebettert~rgingmypromisetomyfather~435":"“Creio que tem razão, meu amor; será melhor que não haja pensão no caso; o que eu lhes der ocasionalmente será de ajuda muito maior do que uma mesada anual, porque só ampliariam seu padrão de vida se se sentissem seguras de uma renda maior, e não ficariam um vintém mais ricas ao fim do ano. Será certamente o melhor caminho. Um presente de cinquenta libras, de vez em quando, impedirá que jamais se vejam aflitas por dinheiro e cumprirá, penso eu, amplamente a minha promessa a meu pai.”","tobesureitwillindeedtosaythetruthiamconv~reabletogiveyousomething~1126":"“Claro que cumprirá. Na verdade, para dizer a verdade, estou convencida no íntimo de que seu pai não tinha ideia alguma de que você lhes desse dinheiro. A ajuda em que pensava, ouso dizer, era apenas a que razoavelmente se esperaria de você; por exemplo, procurar para elas uma casinha confortável, ajudá-las a levar suas coisas e enviar-lhes presentes de peixe e caça, e assim por diante, sempre que for a estação. Aposto a minha vida que não quis dizer nada mais; aliás, seria muito estranho e despropositado se quisesse. Considere apenas, meu caro Sr. Dashwood, quão excessivamente confortavelmente sua sogra e as filhas podem viver com os juros de sete mil libras, além das mil libras pertencentes a cada uma das moças, que lhes rendem cinquenta libras por ano cada uma, e de que, naturalmente, pagarão à mãe a pensão. Ao todo, terão quinhentas por ano entre si, e que diabo podem querer quatro mulheres além disso? Viverão tão barato! Sua despesa doméstica será nada. Não terão carruagem, nem cavalos, e quase nenhum criado; não receberão visitas e não podem ter despesas de espécie alguma! Imagine só como estarão confortáveis! Quinhentas por ano! Tenho certeza de que não imagino como gastarão metade; e quanto a você dar-lhes mais, é absurdo pensar nisso. Elas é que terão muito mais condições de lhe dar alguma coisa.”","uponmywordsaidmrdashwoodibelieveyouarepe~retoomaybeacceptablethen~374":"“Por minha palavra,” disse o Sr. Dashwood, “creio que tem perfeita razão. Meu pai certamente não podia querer dizer, com seu pedido a mim, nada mais do que você diz. Entendo-o claramente agora e cumprirei estritamente o meu compromisso com tais atos de auxílio e bondade para com elas, como descreveu. Quando minha mãe se mudar para outra casa, meus serviços lhe serão prontamente dados para acomodá-la quanto eu possa. Um pequeno presente de mobília também poderá ser bem-vindo então.”","certainlyreturnedmrsjohndashwoodbuthowev~ttedupassoonasshetakesit~259":"“Certamente,” retornou a Sra. John Dashwood. “Mas há uma coisa a considerar. Quando seu pai e sua mãe se mudaram para Norland, embora a mobília de Stanhill tenha sido vendida, toda a porcelana, a prataria e a roupa de casa foram salvas e agora estão legadas à sua mãe. A casa dela ficará, portanto, quase completamente guarnecida assim que a tomar.”","thatisamaterialconsiderationundoubtedlya~dditiontoourownstockhere~131":"“Essa é uma consideração material, sem dúvida. Um legado valioso, de fato! E, no entanto, parte da prataria teria sido um acréscimo muito agradável à nossa própria aqui.”","yesandthesetofbreakfastchinaistwiceashan~erythingintheworldtothem~331":"“Sim; e o aparelho de café da manhã é duas vezes mais bonito que o desta casa. Bonito demais, na minha opinião, para qualquer lugar em que elas possam jamais ter meios de viver. Mas, enfim, é assim. Seu pai só pensou nelas. E devo dizer isto: que você não deve gratidão particular a ele, nem atenção aos seus desejos; pois sabemos muito bem que, se pudesse, teria deixado quase tudo o que há no mundo para elas.”","thisargumentwasirresistibleitgavetohisin~tsashisownwifepointedout~249":"Esse argumento era irresistível. Deu às intenções dele o que lhes faltava de decisão; e ele resolveu, afinal, que seria absolutamente desnecessário, se não altamente indecoroso, fazer mais pela viúva e pelos filhos de seu pai do que o gênero de gentilezas de boa vizinhança que a própria esposa indicara.","mrsdashwoodremainedatnorlandseveralmonth~rmotherwouldhaveapproved~641":"A Sra. Dashwood permaneceu em Norland vários meses; não por qualquer má vontade em mudar-se depois que a vista de cada lugar conhecido deixou de suscitar a violenta emoção que causara por algum tempo; pois, quando seu ânimo começou a reviver e seu espírito se tornou capaz de outro esforço que não o de aumentar a aflição com lembranças melancólicas, ficou impaciente por partir e infatigável em suas indagações por uma moradia adequada na vizinhança de Norland; pois mudar-se para longe daquele lugar querido era impossível. Mas não conseguia ouvir falar de nenhuma situação que correspondesse ao mesmo tempo às suas noções de conforto e comodidade e à prudência da filha mais velha, cujo juízo mais firme rejeitava várias casas como grandes demais para a renda delas, que a mãe teria aprovado.","mrsdashwoodhadbeeninformedbyherhusbandof~iberalityofhisintentions~629":"A Sra. Dashwood fora informada pelo marido da solene promessa do filho em favor delas, que lhe dera conforto nas últimas reflexões terrenas. Não duvidava da sinceridade dessa garantia mais do que ele próprio duvidara, e pensava nela com satisfação por amor das filhas, embora quanto a si mesma estivesse persuadida de que uma provisão muito menor do que sete mil libras a sustentaria na abastança. Pelo irmão também, por causa de seu próprio coração, regozijava-se; e censurava-se por ter sido injusta antes com o mérito dele, ao julgá-lo incapaz de generosidade. O comportamento atencioso dele para consigo e as irmãs convencia-a de que o bem-estar delas lhe era caro e, por longo tempo, confiou firmemente na liberalidade de suas intenções.","thecontemptwhichshehadveryearlyintheirac~terscontinuanceatnorland~457":"O desprezo que ela sentira pela nora, bem cedo no conhecimento mútuo, foi muito aumentado pelo maior conhecimento do caráter dela que meio ano de residência em sua família proporcionou; e talvez, a despeito de toda consideração de polidez ou afeição materna da parte da primeira, as duas damas tivessem achado impossível viver juntas por tanto tempo, não houvesse ocorrido uma circunstância particular que tornou ainda mais desejável, na opinião da Sra. Dashwood, a permanência das filhas em Norland.","thiscircumstancewasagrowingattachmentbet~eatestpartofhistimethere~244":"Essa circunstância era uma afeição crescente entre a filha mais velha e o irmão da Sra. John Dashwood, um jovem cavalheiresco e agradável, que lhes fora apresentado logo depois do estabelecimento da irmã em Norland e que desde então passara ali a maior parte do tempo.","somemothersmighthaveencouragedtheintimac~rcomprehensionimpossible~605":"Algumas mães teriam encorajado a intimidade por motivos de interesse, pois Edward Ferrars era o filho mais velho de um homem que morrera muito rico; e algumas a teriam reprimido por motivos de prudência, pois, exceto uma quantia insignificante, toda a sua fortuna dependia da vontade da mãe. Mas a Sra. Dashwood não era influenciada por nenhuma das duas considerações. Bastava-lhe que ele parecesse amável, que amasse sua filha e que Elinor correspondesse à preferência. Era contrário a toda a sua doutrina que a diferença de fortuna mantivesse separados dois que se sentiam atraídos pela semelhança de temperamento; e que o mérito de Elinor não fosse reconhecido por todos os que a conheciam era, para a sua compreensão, impossível.","edwardferrarswasnotrecommendedtotheirgoo~otherwhowasmorepromising~946":"Edward Ferrars não se recomendava à boa opinião delas por quaisquer graças peculiares de pessoa ou de trato. Não era bonito, e suas maneiras exigiam intimidade para serem agradáveis. Era tímido demais para fazer justiça a si mesmo; mas, vencida a timidez natural, seu comportamento dava todos os indícios de um coração franco e afetuoso. Seu entendimento era bom, e a educação lhe dera sólido aprimoramento. Mas não estava preparado, nem por capacidade nem por feitio, para corresponder aos desejos da mãe e da irmã, que ansiavam por vê-lo distinto — como — mal sabiam o quê. Queriam que ele fizesse bela figura no mundo de uma maneira ou de outra. A mãe desejava interessá-lo em assuntos políticos, pô-lo no Parlamento ou vê-lo ligado a alguns dos grandes homens do dia. A Sra. John Dashwood desejava o mesmo; mas, entretanto, até que uma dessas bênçãos superiores pudesse ser alcançada, teria sossegado sua ambição vê-lo conduzindo um landau. Mas Edward não tinha queda por grandes homens nem por landaus. Todos os seus desejos se concentravam no conforto doméstico e na tranquilidade da vida privada. Felizmente tinha um irmão mais novo que era mais promissor.","edwardhadbeenstayingseveralweeksinthehou~mmostforciblytohermother~460":"Edward estava havia várias semanas na casa antes de ocupar muito a atenção da Sra. Dashwood; pois ela se achava, na época, em tal aflição que a tornava descuidada com os objetos ao redor. Via apenas que ele era quieto e discreto, e gostava dele por isso. Não perturbava a infelicidade de seu espírito com conversa fora de hora. Foi chamada pela primeira vez a observá-lo mais e a aprová-lo por uma reflexão que Elinor fez por acaso um dia sobre a diferença entre ele e a irmã. Era um contraste que o recomendava com a maior força à mãe.","itisenoughsaidshetosaythatheisunlikefann~ngamiableilovehimalready~90":"“Basta,” disse ela; “dizer que ele não é como Fanny basta. Implica tudo o que é amável. Já o amo.”","ithinkyouwilllikehimsaidelinorwhenyoukno~inorwhenyouknowmoreofhim~50":"“Creio que gostará dele,” disse Elinor, “quando o conhecer melhor.”","likehimrepliedhermotherwithasmileifeelno~pprobationinferiortolove~76":"“Gostar dele!” replicou a mãe com um sorriso. “Não sinto nenhum sentimento de aprovação inferior ao amor.”","youmayesteemhim~youmayesteemhim~15":"“A senhora pode estimá-lo.”","ihaveneveryetknownwhatitwastoseparateest~stoseparateesteemandlove~50":"“Nunca soube ainda o que era separar estima e amor.”","mrsdashwoodnowtookpainstogetacquaintedwi~andhistemperaffectionate~401":"A Sra. Dashwood tratou então de conhecê-lo. Suas maneiras eram cativantes e logo baniram a reserva dele. Logo compreendeu todos os seus méritos; a persuasão de que ele estimava Elinor talvez ajudasse sua penetração; mas sentiu-se realmente segura do valor dele: e até aquela quietude de maneiras, que militava contra todas as suas ideias estabelecidas sobre como deveria ser o trato de um jovem, deixou de ser desinteressante quando soube que seu coração era caloroso e seu gênio afetuoso.","nosoonerdidsheperceiveanysymptomoflovein~iageasrapidlyapproaching~159":"Assim que percebeu qualquer sintoma de amor no comportamento dele para com Elinor, considerou certa a séria ligação entre os dois e esperou o casamento como próximo.","inafewmonthsmydearmariannesaidsheelinorw~missherbutshewillbehappy~106":"“Em poucos meses, minha querida Marianne,” disse ela, “Elinor estará, com toda probabilidade, estabelecida para a vida. Sentiremos sua falta; mas ela será feliz.”","ohmamahowshallwedowithouther~mahowshallwedowithouther~28":"“Oh! Mamãe, como faremos sem ela?”","myloveitwillbescarcelyaseparationweshall~approveyoursisterschoice~244":"“Meu amor, mal será uma separação. Viveremos a poucas milhas uma da outra e nos encontraremos todos os dias da vida. Você ganhará um irmão, um verdadeiro irmão afetuoso. Tenho a mais alta opinião do mundo sobre o coração de Edward. Mas você está séria, Marianne; desaprova a escolha de sua irmã?”","perhapssaidmarianneimayconsideritwithsom~suchdreadfulindifference~1080":"“Talvez,” disse Marianne, “eu a considere com alguma surpresa. Edward é muito amável, e eu o amo ternamente. Mas, ainda assim… ele não é o tipo de rapaz… falta algo… sua figura não é marcante; não tem nada daquela graça que eu esperaria no homem que pudesse seriamente prender minha irmã. Seus olhos carecem de todo aquele espírito, aquele fogo, que anunciam de imediato virtude e inteligência. E, além de tudo isso, receio, Mamãe, que ele não tenha verdadeiro gosto. A música mal parece atraí-lo e, embora admire muito os desenhos de Elinor, não é a admiração de uma pessoa que possa entender o seu valor. É evidente, a despeito da frequente atenção que lhe dá enquanto ela desenha, que na verdade nada entende do assunto. Admira como amante, não como conhecedor. Para me satisfazer, essas qualidades têm de estar unidas. Eu não poderia ser feliz com um homem cujo gosto não coincidisse em todos os pontos com o meu. Ele deve entrar em todos os meus sentimentos; os mesmos livros, a mesma música devem encantar a ambos. Oh! mamãe, como foi sem ânimo, como foi insípido o modo de Edward ler para nós ontem à noite! Senti por minha irmã da maneira mais dolorosa. Contudo ela suportou com tanta compostura que mal parecia notar. Eu mal conseguia ficar sentada. Ouvir aqueles belos versos que tantas vezes quase me enlouqueceram pronunciados com tão impenetrável calma, tão terrível indiferença!”","hewouldcertainlyhavedonemorejusticetosim~butyouwouldgivehimcowper~101":"“Ele certamente teria feito mais justiça à prosa simples e elegante. Pensei assim na hora; mas você quis dar-lhe Cowper.”","naymamaifheisnottobeanimatedbycowperbutw~sswitheverypossiblecharm~404":"“Ora, Mamãe, se ele não se anima com Cowper!… mas devemos admitir diferença de gosto. Elinor não tem os meus sentimentos e, portanto, pode relevar isso e ser feliz com ele. Mas teria me partido o coração, se o amasse, ouvi-lo ler com tão pouca sensibilidade. Mamãe, quanto mais conheço o mundo, mais me convenço de que nunca verei um homem a quem possa realmente amar. Exijo tanto! Ele deve ter todas as virtudes de Edward, e sua pessoa e maneiras devem ornar sua bondade com todos os encantos possíveis.”","remembermylovethatyouarenotseventeenitis~stinybedifferentfromhers~187":"“Lembre-se, meu amor, de que você não tem ainda dezessete anos. É cedo demais na vida para desesperar de tal felicidade. Por que haveria você de ser menos afortunada que sua mãe? Numa só circunstância, minha Marianne, possa o seu destino ser diferente do dela!”"}$tr$::jsonb, 64)
on conflict (texto_slug, idioma) do update set cobertura = excluded.cobertura, credito = excluded.credito, titulos = excluded.titulos, paragrafos = excluded.paragrafos, total_paragrafos = excluded.total_paragrafos, atualizado_em = now();

-- jonathan-swift_gullivers-travels (65 parágrafos)
insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('jonathan-swift_gullivers-travels', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"chapteri":"Capítulo I","chapterii":"Capítulo II","chapteriii":"Capítulo III"}$tr$::jsonb, $tr${"theauthorgivessomeaccountofhimselfandfam~erandcarriedupthecountry~177":"O autor dá algumas informações sobre si e sua família. Os primeiros motivos que o levaram a viajar. Naufraga e nada para salvar a vida. Chega são e salvo à praia do país de Lilliput; é feito prisioneiro e levado para o interior.","myfatherhadasmallestateinnottinghamshire~uldbeusefulinlongvoyages~767":"Meu pai tinha uma pequena propriedade em Nottinghamshire: eu era o terceiro de cinco filhos. Aos catorze anos mandou-me para o Emanuel College, em Cambridge, onde residi três anos e me apliquei com afinco aos estudos; mas, sendo o custo de me manter, embora minha mesada fosse bem escassa, grande demais para uma fortuna estreita, fui posto como aprendiz do Sr. James Bates, eminente cirurgião de Londres, com quem permaneci quatro anos. Meu pai, enviando-me de vez em quando pequenas somas, empreguei-as em aprender navegação e outros ramos da matemática, úteis a quem pretende viajar, como sempre acreditei que seria, mais cedo ou mais tarde, o meu destino. Ao deixar o Sr. Bates, fui ter com meu pai, onde, com a ajuda dele, de meu tio John e de alguns outros parentes, consegui quarenta libras e a promessa de trinta libras por ano para me manter em Leiden; ali estudei medicina por dois anos e sete meses, sabendo que seria útil em longas viagens.","soonaftermyreturnfromleydeniwasrecommend~hundredpoundsforaportion~496":"Logo depois de meu regresso de Leiden, fui recomendado por meu bom mestre, o Sr. Bates, para cirurgião do Swallow, sob o comando do Capitão Abraham Pannel, com quem permaneci três anos e meio, fazendo uma ou duas viagens ao Levante e a outras partes. Ao voltar, resolvi estabelecer-me em Londres, o que o Sr. Bates, meu mestre, me incentivou a fazer, e por ele fui recomendado a vários pacientes. Aluguei parte de uma pequena casa em Old Jewry; e, aconselhado a mudar de estado, casei-me com a Sra. Mary Burton, segunda filha do Sr. Edmund Burton, meeiro, da Newgate Street, com quem recebi quatrocentas libras de dote.","butmygoodmasterbatesdyingintwoyearsafter~ybythestrengthofmymemory~605":"Mas, morrendo meu bom mestre Bates dois anos depois, e tendo eu poucos amigos, meu consultório começou a declinar; pois minha consciência não me permitia imitar a má prática de tantos entre meus colegas. Tendo, portanto, consultado minha mulher e alguns conhecidos, determinei-me a voltar ao mar. Fui cirurgião, sucessivamente, em dois navios, e fiz várias viagens, durante seis anos, às Índias Orientais e Ocidentais, com o que obtive algum acréscimo à minha fortuna. Passava as horas de lazer lendo os melhores autores, antigos e modernos, sempre provido de bom número de livros; e, quando estava em terra, observando os costumes e as disposições do povo, bem como aprendendo-lhe a língua, na qual tinha grande facilidade, graças à força de minha memória.","thelastofthesevoyagesnotprovingveryfortu~wasatfirstveryprosperous~435":"Não tendo sido muito afortunada a última dessas viagens, cansei-me do mar e tencionei ficar em casa com minha mulher e família. Mudei-me de Old Jewry para Fetter Lane, e dali para Wapping, esperando conseguir clientela entre os marinheiros; mas isso não deu resultado. Depois de três anos na expectativa de que as coisas melhorassem, aceitei uma oferta vantajosa do Capitão William Prichard, comandante do Antelope, que ia fazer uma viagem ao Mar do Sul. Zarpamos de Bristol a 4 de maio de 1699, e nossa viagem foi a princípio muito próspera.","itwouldnotbeproperforsomereasonstotroubl~teightoclockintheevening~1333":"Não seria conveniente, por certas razões, incomodar o leitor com os pormenores de nossas aventuras naqueles mares; baste informá-lo de que, na travessia dali para as Índias Orientais, fomos arrastados por uma violenta tempestade a noroeste da Terra de Van Diemen. Por observação, achamo-nos na latitude de 30 graus e 2 minutos sul. Doze de nossos tripulantes estavam mortos de trabalho excessivo e má alimentação; os demais estavam muito debilitados. A 5 de novembro, que era o início do verão naquelas partes, estando o tempo muito enevoado, os marinheiros avistaram um rochedo a meio cabo de distância do navio; mas o vento era tão forte que fomos lançados diretamente contra ele, e o navio logo se partiu. Seis da tripulação, entre os quais eu, tendo baixado o bote ao mar, conseguimos livrar-nos do navio e do rochedo. Remamos, segundo meu cálculo, cerca de três léguas, até não podermos mais trabalhar, já exaustos do esforço feito a bordo. Entregamo-nos, pois, à mercê das ondas, e em cerca de meia hora o bote foi virado por uma súbita rajada vinda do norte. O que foi de meus companheiros no bote, bem como dos que escaparam no rochedo ou ficaram na embarcação, não sei dizer; mas concluo que todos se perderam. Quanto a mim, nadei conforme a sorte me guiava, empurrado pelo vento e pela maré. Muitas vezes deixei as pernas caírem e não senti fundo; mas, quando estava quase vencido e incapaz de lutar mais, achei-me em águas onde dava pé; e a essa altura a tempestade havia amainado muito. O declive era tão pequeno que andei quase uma milha antes de alcançar a praia, o que calculei ser por volta das oito horas da noite.","ithenadvancedforwardnearhalfamilebutcoul~heniknewnotwhattheymeant~1512":"Avancei então cerca de meia milha, mas não pude descobrir sinal de casas ou de habitantes; ou, pelo menos, estava em condição tão fraca que não os observei. Estava extremamente cansado e, com isso, o calor do tempo e cerca de meio quartilho de aguardente que bebera ao deixar o navio, senti-me muito inclinado a dormir. Deitei-me na relva, que era muito curta e macia, e ali dormi mais profundamente do que me lembrava de jamais ter dormido na vida, por umas nove horas, segundo calculei; pois, quando acordei, mal amanhecia. Tentei levantar-me, mas não consegui mexer-me: porque, estando deitado de costas, descobri que meus braços e pernas estavam firmemente presos ao chão de cada lado, e meu cabelo, que era longo e espesso, atado da mesma maneira. Senti também várias ligaduras delgadas atravessando-me o corpo, das axilas às coxas. Só podia olhar para cima; o sol começava a esquentar e a luz ofendia-me os olhos. Ouvi um ruído confuso à minha volta; mas, na postura em que me achava, nada via além do céu. Em pouco tempo senti algo vivo movendo-se na minha perna esquerda, que, avançando suavemente sobre o peito, chegou quase até o meu queixo; quando, baixando os olhos o mais que pude, percebi ser uma criatura humana de menos de seis polegadas de altura, com arco e flecha nas mãos e uma aljava às costas. Entretanto, senti pelo menos mais quarenta da mesma espécie (como conjeturei) seguindo o primeiro. Fiquei no maior assombro e rugi tão alto que todos recuaram aterrorizados; e alguns deles, como depois me contaram, machucaram-se nas quedas que sofreram ao saltar dos meus flancos para o chão. Logo, porém, voltaram, e um deles, que se aventurou até obter plena vista do meu rosto, erguendo as mãos e os olhos em sinal de admiração, gritou com voz aguda, mas distinta: “Hekinah degul”; os outros repetiram as mesmas palavras várias vezes, mas então eu não sabia o que significavam.","ilayallthiswhileasthereadermaybelieveing~elycoveredwithmylefthand~790":"Fiquei deitado todo esse tempo, como o leitor poderá crer, em grande desconforto. Por fim, debatendo-me para me soltar, tive a sorte de romper as cordas e arrancar as estacas que prendiam o meu braço esquerdo ao chão; pois, ao levantá-lo até o rosto, descobri os métodos de que se haviam valido para me atar, e ao mesmo tempo, com um puxão violento, que me causou dor excessiva, afrouxei um pouco as cordas que prendiam o meu cabelo do lado esquerdo, de modo que pude virar a cabeça cerca de duas polegadas. Mas as criaturas fugiram uma segunda vez, antes que eu pudesse apanhá-las; ouviu-se então um grande grito em sotaque muito agudo e, depois que cessou, ouvi um deles bradar: “Tolgo phonac”; e num instante senti mais de cem flechas disparadas contra a minha mão esquerda, que me picaram como outras tantas agulhas; e, além disso, lançaram outra salva ao ar, como fazemos com as bombas na Europa, das quais muitas, suponho, caíram sobre o meu corpo (embora eu não as sentisse), e algumas sobre o rosto, que logo cobri com a mão esquerda.","whenthisshowerofarrowswasoverifellagroan~nwhichtheycouldnotpierce~238":"Passada essa chuva de flechas, pus-me a gemer de pesar e de dor; e, tentando de novo soltar-me, descarregaram outra salva maior que a primeira, e alguns tentaram com lanças espetar-me os flancos; mas, por boa sorte, eu vestia um gibão de couro de búfalo, que não conseguiram transpassar.","ithoughtitthemostprudentmethodtoliestill~unedisposedotherwiseofme~296":"Pensei ser o método mais prudente ficar quieto, e meu plano era continuar assim até a noite, quando, estando a mão esquerda já solta, eu poderia facilmente libertar-me; e quanto aos habitantes, tinha razões para crer que me bastaria para o maior exército que pudessem trazer contra mim, se fossem todos do mesmo tamanho que o que eu vira. Mas a fortuna dispôs de outro modo a meu respeito.","whenthepeopleobservediwasquiettheydischa~understoodnotonesyllable~469":"Quando o povo observou que eu estava quieto, não disparou mais flechas; mas, pelo ruído que ouvia, soube que seus números aumentavam; e a cerca de quatro jardas de mim, defronte do meu ouvido direito, ouvi por mais de uma hora um bater como o de gente trabalhando; quando, virando a cabeça para aquele lado, tanto quanto as estacas e as cordas me permitiam, vi um estrado erguido a pé e meio do chão, capaz de abrigar quatro dos habitantes, com duas ou três escadas para subir a ele: de onde um deles, que parecia pessoa de qualidade, me fez longo discurso, do qual não entendi uma só sílaba.","butishouldhavementionedthatbeforetheprin~fpromisespityandkindness~645":"Mas devia ter mencionado que, antes de começar a oração, a pessoa principal gritou três vezes: “Langro dehul san” (essas palavras e as anteriores foram depois repetidas e explicadas a mim); depois do que, imediatamente, cerca de cinquenta dos habitantes vieram e cortaram as cordas que prendiam o lado esquerdo da minha cabeça, o que me deu a liberdade de voltá-la para a direita e de observar a pessoa e o gesto de quem ia falar. Parecia de meia-idade e mais alto que qualquer dos outros três que o acompanhavam, dos quais um era um pajem que lhe sustentava a cauda da veste e parecia ser um pouco mais comprido que o meu dedo médio; os outros dois ficavam um de cada lado para ampará-lo. Desempenhava todos os papéis de um orador, e pude observar muitos períodos de ameaças e outros de promessas, de piedade e de bondade.","iansweredinafewwordsbutinthemostsubmissi~tosignifythatiwantedfood~368":"Respondi em poucas palavras, mas da maneira mais submissa, erguendo a mão esquerda e ambos os olhos para o sol, como a tomá-lo por testemunha; e, quase faminto, não tendo comido um bocado por algumas horas antes de deixar o navio, achei as exigências da natureza tão fortes que não pude deixar de mostrar minha impaciência (talvez contra as estritas regras da decência), levando o dedo com frequência à boca, para significar que queria alimento.","thehurgoforsotheycallagreatlordasiafterw~hmentatmybulkandappetite~684":"O hurgo (pois assim chamam um grande senhor, como depois aprendi) entendeu-me muito bem. Desceu do estrado e mandou que se encostassem várias escadas aos meus flancos, pelas quais mais de cem habitantes subiram e caminharam na direção da minha boca, carregados de cestos cheios de carne, que fora providenciada e enviada para lá por ordem do rei, à primeira notícia que tivera de mim. Observei que havia carne de vários animais, mas não pude distingui-los pelo gosto. Havia pás, pernas e lombos, de forma semelhante aos de carneiro e muito bem preparados, mas menores que as asas de uma cotovia. Comia-os de dois ou três por bocado e tomava três pães de cada vez, do tamanho de balas de mosquete. Serviam-me tão depressa quanto podiam, mostrando mil sinais de pasmo e assombro ante meu volume e meu apetite.","ithenmadeanothersignthatiwanteddrinkthey~rebuttheyhadnonetogiveme~424":"Fiz então outro sinal, de que queria beber. Perceberam, pelo meu comer, que uma pequena quantidade não me bastaria; e, sendo povo engenhosíssimo, ergueram com grande destreza um dos seus maiores barris, rolaram-no até minha mão e arrancaram-lhe o tampo; bebi-o de um trago, o que bem podia fazer, pois não continha meio quartilho, e tinha sabor de um vinho leve da Borgonha, mas muito mais delicioso. Trouxeram-me um segundo barril, que bebi do mesmo modo, e fiz sinais pedindo mais; mas não tinham mais para me dar.","whenihadperformedthesewonderstheyshouted~atureasimustappeartothem~959":"Quando realizei essas maravilhas, gritaram de alegria e dançaram sobre meu peito, repetindo várias vezes, como no início, “Hekinah degul”. Fizeram-me sinal de que eu devia atirar os dois barris ao chão, mas antes avisando o povo embaixo para que saísse do caminho, gritando alto: “Borach mevolah”; e, quando viram os vasos no ar, ergueu-se um brado universal de “Hekinah degul”. Confesso que muitas vezes fui tentado, enquanto passavam e repassavam sobre o meu corpo, a agarrar quarenta ou cinquenta dos primeiros que me ficassem ao alcance e lançá-los contra o chão. Mas a lembrança do que eu sentira, que provavelmente não seria o pior que podiam fazer, e a promessa de honra que lhes fiz — pois assim interpretei meu comportamento submisso — logo expulsaram tais imaginações. Além disso, considerava-me agora obrigado pelas leis da hospitalidade a um povo que me tratara com tanta despesa e magnificência. No entanto, em meus pensamentos não podia admirar suficientemente a intrepidez daqueles diminutos mortais, que ousavam subir e andar sobre o meu corpo, enquanto uma das minhas mãos estava livre, sem tremer à própria vista de criatura tão prodigiosa como devo ter-lhes parecido.","aftersometimewhentheyobservedthatimadeno~ifythatidesiredmyliberty~710":"Algum tempo depois, quando observaram que eu não fazia mais pedidos de carne, apareceu diante de mim uma pessoa de alta posição enviada por sua majestade imperial. Sua excelência, tendo subido na parte fina da minha perna direita, avançou até o meu rosto, com cerca de uma dúzia de seu séquito; e, apresentando suas credenciais sob o sinete real, que pôs rente aos meus olhos, falou por uns dez minutos sem sinais de cólera, mas com uma espécie de resolução determinada, apontando muitas vezes para a frente, o que, como depois descobri, era na direção da capital, a cerca de meia milha de distância, para onde sua majestade em conselho decidira que eu devia ser transportado. Respondi em poucas palavras, mas sem proveito, e fiz sinal com a mão solta, levando-a à outra (mas por cima da cabeça de sua excelência, por medo de feri-lo ou ao seu séquito) e depois à minha cabeça e ao corpo, para significar que desejava a liberdade.","itappearedthatheunderstoodmewellenoughfo~yandcheerfulcountenances~580":"Pareceu que me entendeu bastante bem, pois balançou a cabeça em sinal de desaprovação e manteve a mão em postura que mostrava que eu devia ser levado como prisioneiro. Fez, contudo, outros sinais para me dar a entender que eu teria comida e bebida em abundância e muito bom tratamento. Por isso pensei uma vez mais em tentar romper as minhas ligaduras; mas, de novo, quando senti o ardor de suas flechas no rosto e nas mãos, que estavam todos em bolhas, com muitos dardos ainda cravados, e observando também que o número dos meus inimigos aumentava, dei sinais para que soubessem que podiam fazer de mim o que quisessem. Com isso, o hurgo e seu séquito retiraram-se, com muita civilidade e semblantes alegres.","soonafteriheardageneralshoutwithfrequent~tioninthehogsheadsofwine~786":"Logo depois ouvi um grito geral, com frequentes repetições das palavras “Peplom selan”; e senti grande número de pessoas, do meu lado esquerdo, afrouxando as cordas a tal ponto que pude virar-me para a direita e aliviar-me urinando; o que fiz copiosamente, para grande assombro do povo, que, conjeturando pelo meu movimento o que eu ia fazer, abriu-se imediatamente à direita e à esquerda daquele lado, para evitar a torrente, que caía de mim com tamanho ruído e violência. Mas, antes disso, haviam untado meu rosto e ambas as mãos com uma espécie de unguento, de cheiro muito agradável, que em poucos minutos tirou todo o ardor das flechas. Essas circunstâncias, somadas ao refrigério que eu recebera de sua comida e bebida, que eram muito nutritivas, dispuseram-me ao sono. Dormi cerca de oito horas, como depois me asseguraram; e não era de admirar, pois os médicos, por ordem do imperador, haviam misturado uma poção sonífera nos barris de vinho.","itseemsthatuponthefirstmomentiwasdiscove~ocarrymetothecapitalcity~294":"Parece que, no primeiro momento em que fui descoberto dormindo no chão, após o meu desembarque, o imperador teve cedo aviso por um mensageiro e decidiu em conselho que eu devia ser atado da maneira que relatei (o que foi feito durante a noite, enquanto eu dormia); que se me enviasse abundância de comida e bebida; e que se preparasse uma máquina para me levar à capital.","thisresolutionperhapsmayappearveryboldan~sotheycouldexpectnomercy~468":"Esta resolução talvez pareça muito ousada e perigosa, e estou confiante de que não seria imitada por nenhum príncipe da Europa em ocasião semelhante. Contudo, em minha opinião, foi extremamente prudente, além de generosa: pois, supondo que essa gente tivesse tentado matar-me com lanças e flechas enquanto eu dormia, certamente teria acordado à primeira sensação de dor, o que poderia ter despertado minha fúria e minha força a ponto de capacitar-me a romper as cordas com que fora atado; depois do que, como não seriam capazes de resistir, tampouco poderiam esperar misericórdia.","thesepeoplearemostexcellentmathematician~fourhundredyardstothesea~384":"Esse povo é composto de excelentes matemáticos e chegou a grande perfeição na mecânica, pelo favor e encorajamento do imperador, que é um renomado protetor das letras. Esse príncipe possui várias máquinas montadas sobre rodas, para o transporte de árvores e outros grandes pesos. Constrói muitas vezes seus maiores navios de guerra, dos quais alguns têm nove pés de comprimento, nas florestas onde cresce a madeira, e os faz levar por essas engenhocas três ou quatrocentas jardas até o mar.","fivehundredcarpentersandengineerswereimm~roughtparalleltomeasilay~307":"Quinhentos carpinteiros e engenheiros foram imediatamente postos a trabalhar para preparar a maior máquina que possuíam. Era uma armação de madeira erguida três polegadas do chão, com cerca de sete pés de comprimento e quatro de largura, movendo-se sobre vinte e duas rodas. O grito que ouvi foi à chegada dessa máquina, que, ao que parece, partiu quatro horas depois do meu desembarque. Foi trazida paralela a mim, enquanto eu jazia.","buttheprincipaldifficultywastoraiseandpl~isaidwashalfamiledistant~669":"Mas a principal dificuldade era erguer-me e colocar-me nesse veículo. Oitenta postes, cada um de um pé de altura, foram erguidos para esse fim, e cordas muito fortes, da grossura de barbante, foram presas por ganchos a muitas faixas que os operários haviam cingido em torno do meu pescoço, das mãos, do corpo e das pernas. Novecentos dos homens mais fortes foram empregados em puxar essas cordas, por meio de muitas roldanas fixadas nos postes; e assim, em menos de três horas, fui içado e lançado na máquina, e ali amarrado com firmeza. Tudo isso me foi contado; pois, enquanto a operação se realizava, eu jazia em sono profundo, pela força daquele remédio soporífero infundido no meu licor. Mil e quinhentos dos maiores cavalos do imperador, cada um com cerca de quatro polegadas e meia de altura, foram empregados em puxar-me em direção à metrópole, que, como disse, estava a meia milha de distância.","aboutfourhoursafterwebeganourjourneyiawa~auseofmywakingsosuddenly~485":"Cerca de quatro horas depois de iniciada a viagem, acordei por um acidente muito ridículo; pois, tendo o carro parado um pouco para ajustar algo que estava fora de ordem, dois ou três jovens nativos tiveram a curiosidade de ver como eu ficava dormindo; subiram à máquina e, avançando muito suavemente até o meu rosto, um deles, oficial da guarda, meteu a ponta aguda de sua meia-pique bastante fundo na minha narina esquerda, o que me fez cócegas no nariz como uma palha e me fez espirrar violentamente; e então escaparam sem ser percebidos, e passaram-se três semanas antes que eu soubesse a causa de meu súbito despertar.","wemadealongmarchtheremainingpartoftheday~softhecitygatesaboutnoon~260":"Fizemos longa marcha pelo resto do dia e repousamos à noite com quinhentos guardas de cada lado de mim, metade com tochas e metade com arcos e flechas, prontos a atirar em mim se eu fizesse menção de me mexer. Na manhã seguinte, ao nascer do sol, continuamos a marcha e chegamos a duzentas jardas das portas da cidade por volta do meio-dia.","theemperorandallhiscourtcameouttomeetusb~personbymountingonmybody~125":"O imperador e toda a sua corte saíram ao nosso encontro; mas seus grandes oficiais de modo algum permitiram que sua majestade pusesse em risco a pessoa subindo no meu corpo.","attheplacewherethecarriagestoppedtherest~asdeterminedishouldlodge~325":"No lugar onde o carro parou havia um antigo templo, tido como o maior de todo o reino; o qual, tendo sido poluído alguns anos antes por um assassinato desnaturado, era, segundo o zelo daquele povo, olhado como profano e por isso fora destinado a uso comum, e todos os ornamentos e móveis levados dali. Neste edifício ficou determinado que eu me alojasse.","thegreatgatefrontingtothenorthwasaboutfo~oforbidituponpainofdeath~799":"O grande portão, voltado para o norte, tinha cerca de quatro pés de altura e quase dois de largura, e por ele eu podia facilmente rastejar. De cada lado do portão havia uma pequena janela, a não mais de seis polegadas do chão: pela da esquerda, o ferreiro do rei introduziu noventa e uma correntes, como as que pendem do relógio de uma dama na Europa, e quase tão grandes, que foram trancadas à minha perna esquerda com trinta e seis cadeados. Defronte desse templo, do outro lado da grande estrada, a vinte pés de distância, havia uma torrinha de pelo menos cinco pés de altura. Nela subiu o imperador, com muitos dos principais senhores da corte, para ter oportunidade de ver-me, como me disseram, pois eu não podia vê-los. Calculou-se que mais de cem mil habitantes saíram da cidade com o mesmo fim; e, apesar de meus guardas, creio que não podiam ser menos de dez mil, em várias ocasiões, os que subiram no meu corpo com a ajuda de escadas. Mas logo foi emitida uma proclamação para proibi-lo sob pena de morte.","whentheworkmenfounditwasimpossibleformet~tmyfulllengthinthetemple~423":"Quando os operários viram que me era impossível romper as ligaduras, cortaram todas as cordas que me prendiam; levantei-me então, com a disposição mais melancólica que jamais tivera na vida. Mas o ruído e o assombro do povo, ao ver-me levantar e andar, não se podem exprimir. As correntes que prendiam a minha perna esquerda tinham cerca de duas jardas de comprimento e davam-me não só a liberdade de andar para a frente e para trás num semicírculo, mas, estando fixadas a quatro polegadas do portão, permitiam-me rastejar para dentro e deitar-me em todo o meu comprimento no templo.","theemperoroflilliputattendedbyseveraloft~rdandpistolstakenfromhim~254":"O imperador de Lilliput, acompanhado de vários nobres, vem ver o autor em seu confinamento. Descrevem-se a pessoa e o traje do imperador. Homens doutos são designados para ensinar ao autor a sua língua. Ele conquista favor por sua índole branda. Revistam-lhe os bolsos e tiram-lhe a espada e as pistolas.","whenifoundmyselfonmyfeetilookedaboutmean~edsceneofacityinatheatre~391":"Quando me vi de pé, olhei à minha volta e devo confessar que jamais contemplei perspectiva mais divertida. A região em redor parecia um jardim contínuo, e os campos cercados, que em geral tinham quarenta pés quadrados, assemelhavam-se a outros tantos canteiros de flores. Esses campos misturavam-se com bosques de meio stang, e as árvores mais altas, a julgar por mim, pareciam ter sete pés. Contemplei a cidade à minha esquerda, que parecia o cenário pintado de uma cidade num teatro.","ihadbeenforsomehoursextremelypressedbyth~ccasionstocallinquestion~1015":"Havia algumas horas que eu estava extremamente premido pelas necessidades da natureza; o que não era de admirar, pois fazia quase dois dias que eu me aliviara pela última vez. Via-me em grandes dificuldades entre a urgência e a vergonha. O melhor expediente que pude imaginar foi rastejar para dentro da minha casa, o que fiz; e, fechando o portão atrás de mim, fui até onde o comprimento da corrente permitia e descarreguei o corpo daquele fardo incômodo. Mas foi esta a única vez em que me tornei culpado de ação tão imunda; pela qual não posso deixar de esperar que o leitor cândido me dê alguma tolerância, depois de ter considerado com maturidade e imparcialidade o meu caso e o aperto em que me achava. Desde então minha prática constante foi, logo ao levantar-me, fazer aquele serviço ao ar livre, no máximo alcance da minha corrente; e tomava-se o devido cuidado, toda manhã, antes que chegasse visita, de que a matéria ofensiva fosse removida em carrinhos de mão por dois criados designados para tal fim. Não me teria detido tanto numa circunstância que, talvez, à primeira vista, pareça de pouca importância, se não julgasse necessário justificar perante o mundo meu caráter em matéria de limpeza; o qual, segundo me dizem, alguns de meus detratores têm-se comprazido, nesta e em outras ocasiões, em pôr em dúvida.","whenthisadventurewasatanendicamebackouto~muchtomyadvantageatcourt~3556":"Terminada essa aventura, saí de novo de minha casa, precisando de ar fresco. O imperador já descera da torre e avançava a cavalo em minha direção, o que quase lhe custou caro; pois o animal, embora muito bem treinado, mas inteiramente desacostumado a tal visão, que lhe parecia uma montanha movendo-se diante de si, empinou-se nas patas traseiras: mas aquele príncipe, que é excelente cavaleiro, manteve-se na sela, até que seus criados correram e seguraram a rédea, enquanto sua majestade tinha tempo de apear. Ao desmontar, examinou-me em redor com grande admiração; mas manteve-se além do comprimento da minha corrente. Ordenou aos cozinheiros e copeiros, que já estavam preparados, que me dessem comida e bebida, as quais empurraram para a frente numa espécie de veículos sobre rodas, até que eu as pudesse alcançar. Tomei esses veículos e logo os esvaziei todos; vinte deles estavam cheios de carne e dez de bebida; cada um dos primeiros me dava dois ou três bons bocados; e esvaziei a bebida de dez vasos, contida em frascos de barro, num só veículo, bebendo-a de um trago; e assim fiz com o resto. A imperatriz e os jovens príncipes do sangue, de ambos os sexos, acompanhados de muitas damas, sentavam-se a certa distância em suas cadeiras; mas, com o acidente que sucedeu ao cavalo do imperador, apearam e chegaram perto da pessoa dele, que vou agora descrever. É mais alto, quase pela largura de minha unha, do que qualquer de sua corte; o que só basta para infundir respeito nos que o contemplam. Seus traços são fortes e viris, com lábio austríaco e nariz arqueado, a tez azeitonada, o semblante erguido, o corpo e os membros bem proporcionados, todos os movimentos graciosos e o porte majestoso. Estava então passada a flor da idade, tendo vinte e oito anos e três quartos, dos quais reinara cerca de sete em grande felicidade e geralmente vitorioso. Para maior comodidade de contemplá-lo, deitei-me de lado, de modo que meu rosto ficou paralelo ao dele, que se achava a apenas três jardas; contudo, tive-o depois muitas vezes na minha mão e portanto não me posso enganar na descrição. Seu traje era muito simples e singelo, e a moda dele entre a asiática e a europeia; mas trazia na cabeça um leve capacete de ouro, adornado de joias, e um penacho na cimeira. Segurava a espada desembainhada na mão para defender-se, caso eu conseguisse soltar-me; tinha quase três polegadas de comprimento; o punho e a bainha eram de ouro enriquecido de diamantes. Sua voz era aguda, mas muito clara e articulada; e eu a ouvia distintamente quando me punha de pé. As damas e os cortesãos estavam todos magnificamente vestidos; de modo que o lugar em que se achavam parecia uma anágua estendida no chão, bordada de figuras de ouro e prata. Sua majestade imperial falou-me muitas vezes e eu lhe dei respostas: mas nenhum de nós entendia uma sílaba. Havia vários de seus sacerdotes e juristas presentes (como conjeturei por suas vestes), que receberam ordem de dirigir-se a mim; e falei-lhes em tantas línguas quantas eu tinha o mais leve conhecimento, que eram o alto e o baixo holandês, latim, francês, espanhol, italiano e língua franca, mas tudo em vão. Passadas cerca de duas horas, a corte retirou-se e fiquei com forte guarda, para evitar a impertinência, e provavelmente a malícia, da ralé, que estava impaciente por se aglomerar em torno de mim o mais perto que ousasse; e alguns tiveram o descaramento de disparar flechas contra mim, enquanto eu estava sentado no chão junto à porta de minha casa, e uma delas passou por muito pouco do meu olho esquerdo. Mas o coronel mandou prender seis dos cabeças e julgou que nenhum castigo era tão adequado quanto entregá-los atados em minhas mãos; o que alguns de seus soldados fizeram, empurrando-os com as coronhas das piques ao meu alcance. Peguei-os todos na mão direita, meti cinco deles no bolso do casaco; e, quanto ao sexto, fiz uma cara como se fosse comê-lo vivo. O pobre homem guinchou terrivelmente, e o coronel e seus oficiais ficaram muito aflitos, sobretudo quando me viram tirar o canivete: mas logo os livrei do medo; pois, olhando com brandura e cortando de imediato as cordas com que ele estava atado, pu-lo suavemente no chão, e lá se foi ele correndo. Tratei os demais da mesma maneira, tirando-os um a um do bolso; e observei que tanto os soldados quanto o povo ficaram muito encantados com essa mostra de clemência, que foi representada muito a meu favor na corte.","towardsnightigotwithsomedifficultyintomy~nsolonginuredtohardships~517":"Pela noite consegui, com alguma dificuldade, entrar em minha casa, onde me deitei no chão, e assim continuei por cerca de quinze dias; durante os quais o imperador deu ordens para que se preparasse uma cama para mim. Seiscentas camas da medida comum foram trazidas em carros e armadas em minha casa; cento e cinquenta das camas deles, cosidas juntas, formavam a largura e o comprimento; e eram quatro dobradas: o que, contudo, mal me protegia da dureza do piso, que era de pedra lisa. Pelo mesmo cálculo, forneceram-me lençóis, cobertores e colchas, toleráveis o bastante para quem estivera tanto tempo acostumado a asperezas.","asthenewsofmyarrivalspreadthroughtheking~stategotconsiderablefees~462":"Ao espalhar-se pelo reino a notícia de minha chegada, trouxe prodigioso número de ricos, ociosos e curiosos para ver-me; de modo que as aldeias ficaram quase vazias; e grande negligência da lavoura e dos negócios domésticos teria resultado, se sua majestade imperial não houvesse providenciado, por várias proclamações e ordens de Estado, contra esse inconveniente. Determinou que os que já me haviam contemplado voltassem para casa e não ousassem chegar a menos de cinquenta jardas de minha casa sem licença da corte; do que os secretários de Estado auferiram consideráveis emolumentos.","inthemeantimetheemperorheldfrequentcounc~ndiswordforwordasfollows~3501":"Entrementes o imperador realizava frequentes conselhos, para debater que rumo se devia tomar comigo; e depois me assegurou um amigo particular, pessoa de grande qualidade, tão inteirado do segredo quanto qualquer outro, que a corte estava em muitas dificuldades a meu respeito. Receavam que eu me soltasse; que meu sustento fosse muito dispendioso e pudesse causar uma fome. Às vezes decidiam matar-me à fome; ou ao menos atirar-me no rosto e nas mãos flechas envenenadas, que logo me despachariam; mas, de novo, consideravam que o fedor de tão grande carcaça poderia produzir uma peste na metrópole e provavelmente espalhar-se por todo o reino. No meio dessas consultas, vários oficiais do exército foram à porta da grande câmara do conselho e, sendo dois deles admitidos, deram conta de meu comportamento para com os seis criminosos acima mencionados; o que causou tão favorável impressão no peito de sua majestade e de toda a mesa, a meu favor, que se expediu uma comissão imperial obrigando todas as aldeias, num raio de novecentas jardas em volta da cidade, a entregar toda manhã seis bois, quarenta carneiros e outras vitualhas para meu sustento; juntamente com quantidade proporcional de pão, vinho e outros licores; para o devido pagamento dos quais sua majestade concedeu ordens de pagamento sobre o seu tesouro — pois esse príncipe vive principalmente de seus próprios domínios, raramente, a não ser em grandes ocasiões, lançando subsídios sobre seus súditos, que são obrigados a acompanhá-lo nas guerras à sua própria custa. Fez-se também o estabelecimento de seiscentas pessoas para serem meus domésticos, às quais se concedeu ajuda de custo para o sustento, e construíram-se-lhes tendas muito convenientemente de cada lado de minha porta. Ordenou-se igualmente que trezentos alfaiates me fizessem um traje à moda do país; que seis dos maiores eruditos de sua majestade fossem empregados em instruir-me na língua deles; e, por último, que os cavalos do imperador, os da nobreza e das tropas da guarda fossem frequentemente exercitados à minha vista, para se acostumarem a mim. Todas essas ordens foram devidamente executadas; e em cerca de três semanas fiz grande progresso no aprendizado da língua; durante o qual tempo o imperador me honrou frequentemente com suas visitas e se dignou ajudar meus mestres a ensinar-me. Já começávamos a conversar de alguma maneira; e as primeiras palavras que aprendi foram para exprimir meu desejo de “que ele se dignasse dar-me a liberdade”; o que eu repetia todo dia de joelhos. Sua resposta, tanto quanto pude compreender, era “que isso devia ser obra do tempo, não se podendo pensar nisso sem o conselho de seu conselho, e que primeiro eu devia lumos kelmin pesso desmar lon emposo”; isto é, jurar paz com ele e com o seu reino. Contudo, que eu seria tratado com toda a bondade. E aconselhou-me a “adquirir, pela minha paciência e comportamento discreto, a boa opinião dele e de seus súditos”. Pediu-me que “não levasse a mal se desse ordens a certos oficiais competentes para me revistarem; pois provavelmente eu trazia comigo várias armas, que deviam ser coisas perigosas, se correspondessem ao volume de tão prodigiosa pessoa”. Disse eu que “sua majestade seria satisfeita; pois estava pronto a despir-me e a virar os bolsos diante dele”. Disse isto em parte por palavras, em parte por sinais. Respondeu “que, pelas leis do reino, eu devia ser revistado por dois de seus oficiais; que sabia que isso não podia ser feito sem meu consentimento e ajuda; e que tinha tão boa opinião de minha generosidade e justiça que confiava suas pessoas às minhas mãos; que tudo o que me tomassem seria devolvido quando eu deixasse o país, ou pago pelo preço que eu fixasse”. Tomei os dois oficiais nas mãos, pus-los primeiro nos bolsos do casaco e depois em todos os outros bolsos que trazia, exceto os dois bolsos de relógio e outro bolso secreto, que eu não queria que fosse revistado, onde trazia algumas coisinhas necessárias que não tinham importância para ninguém além de mim. Num dos bolsos de relógio havia um relógio de prata e, no outro, uma pequena quantidade de ouro numa bolsa. Esses senhores, tendo consigo pena, tinta e papel, fizeram um inventário exato de tudo o que viram; e, quando terminaram, pediram que eu os pusesse no chão, para que o entregassem ao imperador. Este inventário traduzi depois para o inglês, e é, palavra por palavra, o seguinte:","imprimisintherightcoatpocketofthegreatma~goldmustbeofimmensevalue~3021":"Primeiramente: No bolso direito do casaco do grande Homem-Montanha [pois assim interpreto as palavras quinbus flestrin], depois da mais estrita busca, encontramos apenas uma grande peça de pano grosseiro, bastante grande para servir de tapete à principal sala de Estado de vossa majestade. No bolso esquerdo vimos um enorme cofre de prata, com tampa do mesmo metal, que nós, os revistadores, não fomos capazes de levantar. Pedimos que fosse aberto e um de nós, entrando nele, viu-se até a meia perna numa espécie de pó, parte do qual, voando-nos ao rosto, fez-nos espirrar ambos várias vezes seguidas. No bolso direito do colete achamos um prodigioso maço de substâncias brancas e finas, dobradas umas sobre as outras, do tamanho de três homens, atado com um forte cabo e marcado com figuras negras; as quais humildemente concebemos ser escritos, quase cada letra tão grande quanto a palma de nossas mãos. No esquerdo havia uma espécie de engenho, de cujas costas se estendiam vinte longos postes, semelhantes às paliçadas diante da corte de vossa majestade: com o qual conjeturamos que o Homem-Montanha penteia a cabeça; pois nem sempre o incomodávamos com perguntas, porque achávamos grande dificuldade em fazê-lo entender-nos. No bolso grande, do lado direito de sua cobertura do meio [assim traduzo a palavra ranfulo, com a qual queriam dizer as minhas calças], vimos um pilar oco de ferro, do comprimento de um homem, preso a uma forte peça de madeira maior que o pilar; e, de um lado do pilar, havia enormes peças de ferro salientes, talhadas em figuras estranhas, das quais não sabemos o que pensar. No bolso esquerdo, outro engenho da mesma espécie. No bolso menor do lado direito havia várias peças redondas e chatas de metal branco e vermelho, de volumes diferentes; algumas das brancas, que pareciam ser de prata, eram tão grandes e pesadas que meu camarada e eu mal as conseguíamos levantar. No bolso esquerdo havia dois pilares negros de forma irregular: não alcançávamos o topo deles sem dificuldade, estando no fundo do bolso. Um deles era coberto e parecia inteiriço; mas na extremidade superior do outro aparecia uma substância branca e redonda, cerca de duas vezes o tamanho de nossas cabeças. Dentro de cada um estava encerrada uma prodigiosa lâmina de aço; as quais, por nossas ordens, obrigamo-lo a mostrar-nos, porque receávamos que fossem engenhos perigosos. Tirou-as dos estojos e disse-nos que em seu país o costume era barbear-se com uma delas e cortar a carne com a outra. Havia dois bolsos em que não podíamos entrar: chamava-os de seus bolsos de relógio; eram duas grandes fendas cortadas na parte superior de sua cobertura do meio, mas apertadas pela pressão do ventre. Do bolso direito pendia uma grande corrente de prata, com uma espécie de engenho maravilhoso na ponta. Mandamos que tirasse o que estava no fim dessa corrente; o que parecia ser um globo, metade de prata e metade de algum metal transparente; pois, do lado transparente, vimos certas figuras estranhas traçadas em círculo, e pensamos poder tocá-las, até que achamos nossos dedos detidos pela substância lúcida. Pôs esse engenho em nossos ouvidos, que fazia um ruído incessante, como o de um moinho de água: e conjeturamos que é algum animal desconhecido ou o deus que ele adora; mas inclinamo-nos mais à segunda opinião, porque nos assegurou (se o entendemos bem, pois exprimia-se muito imperfeitamente) que raramente fazia qualquer coisa sem o consultar. Chamava-o seu oráculo e dizia que ele indicava o momento de cada ação de sua vida. Do bolso esquerdo tirou uma rede quase grande o bastante para um pescador, mas feita para abrir e fechar como uma bolsa, e que lhe servia ao mesmo uso: achamos nela várias peças maciças de metal amarelo, que, se forem de ouro verdadeiro, devem ter imenso valor.","havingthusinobediencetoyourmajestyscomma~theminthepalmsofourhands~525":"Tendo assim, em obediência às ordens de vossa majestade, diligentemente revistado todos os seus bolsos, observamos um cinturão em torno da cintura, feito do couro de algum animal prodigioso, do qual, do lado esquerdo, pendia uma espada do comprimento de cinco homens; e, do direito, um saco ou bolsa dividido em dois compartimentos, cada um capaz de conter três súditos de vossa majestade. Num desses compartimentos havia vários globos, ou bolas, de um metal pesadíssimo, do tamanho de nossas cabeças, e que exigiam mão forte para levantá-los; o outro compartimento continha um monte de certos grãos negros, mas de não grande volume ou peso, pois podíamos segurar mais de cinquenta deles nas palmas das mãos.","thisisanexactinventoryofwhatwefoundabout~rmajestysauspiciousreign~204":"Este é um inventário exato do que encontramos no corpo do Homem-Montanha, que nos tratou com grande civilidade e devido respeito à comissão de vossa majestade. Assinado e selado no quarto dia da octogésima nona lua do auspicioso reinado de vossa majestade.","clefrinfrelockmarsifrelock~efrinfrelockmarsifrelock~26":"Clefrin Frelock\nMarsi Frelock","whenthisinventorywasreadovertotheemperor~tofmygoodswerereturnedme~2221":"Quando este inventário foi lido ao imperador, ordenou-me, embora em termos muito gentis, que entregasse os vários itens. Pediu primeiro meu alfanje, que tirei com bainha e tudo. Entrementes mandou que três mil de suas tropas escolhidas (que então o acompanhavam) me cercassem à distância, com seus arcos e flechas prontos para disparar; mas não o percebi, pois meus olhos estavam inteiramente fixos em sua majestade. Pediu-me então que sacasse o alfanje, o qual, embora tivesse apanhado alguma ferrugem da água do mar, estava, na maior parte, extremamente brilhante. Assim fiz, e imediatamente todas as tropas deram um grito entre terror e surpresa; pois o sol brilhava claro e o reflexo lhes ofuscava os olhos, enquanto eu agitava o alfanje de lá para cá na mão. Sua majestade, que é príncipe magnanimíssimo, foi menos intimidado do que eu esperava: mandou-me tornar a metê-lo na bainha e lançá-lo ao chão tão gentilmente quanto pudesse, a cerca de seis pés do fim da minha corrente. A segunda coisa que exigiu foi um dos pilares ocos de ferro; com o que queria dizer as minhas pistolas de bolso. Saquei uma e, a seu desejo, expliquei-lhe o melhor que pude o uso dela; e, carregando-a só de pólvora, que, pelo fechamento da minha bolsa, acontecera escapar de molhar-se no mar (inconveniente contra o qual todos os marinheiros prudentes tomam especial cuidado), primeiro adverti o imperador de que não se assustasse e depois a disparei no ar. O espanto foi aqui muito maior do que à vista do alfanje. Centenas caíram como se tivessem sido fulminados; e até o imperador, embora se mantivesse firme, não pôde recobrar-se por algum tempo. Entreguei as duas pistolas do mesmo modo que fizera com o alfanje, e depois a bolsa de pólvora e balas; rogando-lhe que a primeira fosse mantida longe do fogo, pois se acenderia com a menor faísca e faria voar pelos ares o seu palácio imperial. Entreguei também o meu relógio, que o imperador estava muito curioso de ver, e mandou dois de seus mais altos guardas que o carregassem num pau sobre os ombros, como os carroceiros na Inglaterra levam um barril de cerveja. Ficou pasmo com o ruído contínuo que fazia e o movimento do ponteiro dos minutos, que podia facilmente discernir; pois a vista deles é muito mais aguda que a nossa: perguntou a opinião dos doutos a respeito, que foram várias e remotas, como o leitor bem pode imaginar sem que eu as repita; embora, de fato, eu não as pudesse entender muito perfeitamente. Entreguei então minhas moedas de prata e de cobre, minha bolsa com nove grandes peças de ouro e algumas menores; meu canivete e navalha, meu pente e tabaqueira de prata, meu lenço e diário. Meu alfanje, pistolas e bolsa foram levados em carros aos depósitos de sua majestade; mas o resto de meus bens me foi devolvido.","ihadasibeforeobservedoneprivatepocketwhi~redthemoutofmypossession~331":"Eu tinha, como antes observei, um bolso particular, que escapou à revista, onde havia um par de óculos (que uso às vezes para a fraqueza dos olhos), uma luneta de bolso e algumas outras pequenas comodidades; as quais, não tendo importância para o imperador, não me julguei obrigado por honra a revelar, e receei que se perdessem ou estragassem se as arriscasse fora de minha posse.","theauthordivertstheemperorandhisnobility~himuponcertainconditions~167":"O autor diverte o imperador e sua nobreza de ambos os sexos de maneira muito incomum. Descrevem-se os divertimentos da corte de Lilliput. O autor obtém a liberdade sob certas condições.","mygentlenessandgoodbehaviourhadgainedsof~patiencetoenlargealittle~791":"Minha brandura e bom comportamento haviam ganhado tanto o imperador e sua corte, e de fato o exército e o povo em geral, que comecei a conceber esperanças de obter a liberdade em breve. Empreguei todos os métodos possíveis para cultivar essa disposição favorável. Os nativos foram, aos poucos, ficando menos receosos de qualquer perigo vindo de mim. Eu às vezes me deitava e deixava cinco ou seis deles dançarem na minha mão; e por fim os meninos e meninas se aventuravam a vir brincar de esconde-esconde no meu cabelo. Já fizera bom progresso em entender e falar a língua. O imperador teve a ideia, um dia, de me entreter com vários espetáculos do país, nos quais superam todas as nações que conheci, tanto em destreza quanto em magnificência. Nenhum me divertiu tanto como o dos dançarinos de corda, executado sobre um fio branco e delgado, estendido a cerca de dois pés e doze polegadas do chão. Sobre o qual peço licença, com a paciência do leitor, para me estender um pouco.","thisdiversionisonlypractisedbythoseperso~tofficersaremuchuponapar~885":"Este divertimento é praticado apenas por aquelas pessoas que são candidatas a grandes empregos e alto favor na corte. São treinadas nessa arte desde a juventude e nem sempre são de nobre nascimento ou educação liberal. Quando um grande cargo fica vago, seja por morte ou por desgraça (o que muitas vezes acontece), cinco ou seis desses candidatos peticionam ao imperador que divirta sua majestade e a corte com uma dança na corda; e quem pula mais alto, sem cair, sucede no cargo. Muitíssimas vezes os próprios ministros principais recebem ordem de mostrar sua habilidade e de convencer o imperador de que não perderam a faculdade. Flimnap, o tesoureiro, tem licença para dar uma cabriola na corda esticada pelo menos uma polegada acima de qualquer outro senhor de todo o império. Vi-o fazer o salto mortal várias vezes seguidas, sobre um prato fixado a uma corda não mais grossa que um barbante comum na Inglaterra. Meu amigo Reldresal, secretário principal dos assuntos privados, é, em minha opinião, se não sou parcial, o segundo depois do tesoureiro; o resto dos grandes oficiais está mais ou menos em pé de igualdade.","thesediversionsareoftenattendedwithfatal~eakenedtheforceofhisfall~502":"Esses divertimentos são frequentemente acompanhados de acidentes fatais, dos quais há grande número registrado. Eu mesmo vi dois ou três candidatos quebrarem um membro. Mas o perigo é muito maior quando os próprios ministros recebem ordem de mostrar sua destreza; pois, esforçando-se por superar a si mesmos e os colegas, forçam-se tanto que dificilmente haverá um deles que não tenha sofrido uma queda, e alguns duas ou três. Asseguraram-me que, um ano ou dois antes de minha chegada, Flimnap infalivelmente teria quebrado o pescoço, se uma das almofadas do rei, que por acaso estava no chão, não houvesse amortecido a força da queda.","thereislikewiseanotherdiversionwhichison~nedwithoneofthesegirdles~1116":"Há também outro divertimento, que só se mostra diante do imperador, da imperatriz e do primeiro-ministro, em ocasiões particulares. O imperador põe sobre a mesa três finos fios de seda, de seis polegadas de comprimento; um é azul, outro vermelho e o terceiro verde. Esses fios são propostos como prêmios para as pessoas que o imperador deseja distinguir com uma marca peculiar de seu favor. A cerimônia realiza-se na grande câmara de Estado de sua majestade, onde os candidatos sofrem uma prova de destreza muito diferente da anterior, e tal que não observei a menor semelhança dela em nenhum outro país do Novo ou do Velho Mundo. O imperador segura uma vara nas mãos, com ambas as pontas paralelas ao horizonte, enquanto os candidatos, avançando um a um, ora saltam por cima da vara, ora rastejam por baixo dela, para a frente e para trás, várias vezes, conforme a vara é erguida ou abaixada. Às vezes o imperador segura uma ponta da vara e seu primeiro-ministro a outra; às vezes o ministro a tem inteiramente para si. Quem desempenha sua parte com mais agilidade e resiste mais tempo no saltar e rastejar é recompensado com a seda azul; a vermelha é dada ao seguinte e a verde ao terceiro, que todos usam cingida duas vezes em volta da cintura; e vêem-se poucas pessoas importantes nesta corte que não estejam adornadas com um desses cintos.","thehorsesofthearmyandthoseoftheroyalstab~suchdangerousenterprises~2230":"Os cavalos do exército e os das estrebarias reais, tendo sido levados diariamente à minha frente, já não eram ariscos e vinham até os meus pés sem se assustar. Os cavaleiros os faziam saltar por cima da minha mão, enquanto eu a mantinha no chão; e um dos caçadores do imperador, num grande corcel, tomou o meu pé, sapato e tudo, o que foi de fato um salto prodigioso. Tive a boa sorte de divertir o imperador um dia de maneira extraordinária. Pedi que mandasse trazer-me várias varas de dois pés de altura e da grossura de uma bengala comum; ao que sua majestade ordenou ao mestre de suas florestas que desse as instruções, e na manhã seguinte chegaram seis lenhadores com outros tantos carros, puxados cada um por oito cavalos. Tomei nove dessas varas e, fixando-as firmemente no chão em figura quadrangular, de dois pés e meio de lado, tomei outras quatro varas e atei-as paralelamente em cada canto, a cerca de dois pés do chão; depois prendi meu lenço às nove varas erguidas e estendi-o por todos os lados, até ficar tenso como o couro de um tambor; e as quatro varas paralelas, elevando-se cerca de cinco polegadas acima do lenço, serviam de bordas em cada lado. Quando terminei a obra, pedi ao imperador que deixasse uma tropa de seus melhores cavalos, em número de vinte e quatro, vir exercitar-se nessa planície. Sua majestade aprovou a proposta e eu os tomei, um a um, nas mãos, já montados e armados, com os oficiais competentes para exercitá-los. Assim que se puseram em ordem, dividiram-se em dois partidos, executaram escaramuças simuladas, dispararam flechas sem ponta, sacaram as espadas, fugiram e perseguiram, atacaram e recuaram e, em suma, mostraram a melhor disciplina militar que já contemplei. As varas paralelas os protegiam, a eles e aos cavalos, de cair do palco; e o imperador ficou tão encantado que mandou repetir esse divertimento por vários dias, e uma vez se dignou ser erguido para dar a voz de comando; e com grande dificuldade persuadiu até a própria imperatriz a deixar que eu a segurasse em sua cadeira fechada a duas jardas do palco, de onde ela pôde ter plena vista de todo o espetáculo. Foi minha boa sorte que nenhum acidente funesto ocorresse nessas diversões; só uma vez um cavalo fogoso, que pertencia a um dos capitães, escavando com o casco, abriu um buraco em meu lenço, e escorregando-lhe o pé, derrubou o cavaleiro e a si mesmo; mas socorri imediatamente a ambos e, cobrindo o buraco com uma das mãos, pus no chão a tropa com a outra, do mesmo modo que a tomara. O cavalo que caiu torceu o ombro esquerdo, mas o cavaleiro não se feriu; e consertei meu lenço o melhor que pude: não quis, contudo, confiar mais em sua resistência em empreendimentos tão perigosos.","abouttwoorthreedaysbeforeiwassetatlibert~dlessdamagethaniexpected~1532":"Cerca de dois ou três dias antes de ser posto em liberdade, enquanto eu entretinha a corte com esse gênero de proezas, chegou um mensageiro para informar sua majestade de que alguns de seus súditos, cavalgando perto do lugar onde fui primeiro apanhado, haviam visto uma grande substância negra jazendo no chão, de forma muito estranha, estendendo as bordas em redor, tão larga quanto o quarto de dormir de sua majestade, e elevando-se no meio tão alto quanto um homem; que não era criatura viva, como a princípio receavam, pois jazia na relva sem movimento; e que alguns deles haviam dado voltas em torno dela várias vezes; que, subindo uns aos ombros dos outros, haviam chegado ao topo, que era plano e liso, e, batendo os pés nele, descobriram que era oco por dentro; que humildemente concebiam que podia ser algo pertencente ao Homem-Montanha; e que, se sua majestade assim aprouvesse, se encarregariam de trazê-la com apenas cinco cavalos. Logo soube o que queriam dizer e fiquei contente no coração ao receber essa informação. Parece que, ao chegar pela primeira vez à praia depois do naufrágio, eu estava em tal confusão que, antes de chegar ao lugar onde fui dormir, meu chapéu, que eu prendera com um cordão à cabeça enquanto remava e que se mantivera o tempo todo em que nadei, caiu depois que cheguei a terra; o cordão, conjeturo, tendo-se rompido por algum acidente que nunca observei, mas pensei que o chapéu se perdera no mar. Roguei a sua majestade imperial que desse ordens para que mo trouxessem o mais depressa possível, descrevendo-lhe o uso e a natureza dele: e no dia seguinte chegaram os carroceiros com ele, mas não em muito bom estado; haviam furado dois buracos na aba, a uma polegada e meia da borda, e fixado dois ganchos nos buracos; esses ganchos estavam atados por uma longa corda ao arreio, e assim meu chapéu foi arrastado por mais de meia milha inglesa; mas, sendo o chão naquele país extremamente liso e plano, sofreu menos dano do que eu esperava.","twodaysafterthisadventuretheemperorhavin~forlaughterandadmiration~829":"Dois dias depois dessa aventura, o imperador, tendo ordenado que a parte de seu exército que se aquartela dentro e em torno da metrópole ficasse a postos, teve a fantasia de se divertir de maneira muito singular. Pediu que eu ficasse de pé como um Colosso, com as pernas tão afastadas quanto eu pudesse comodamente. Mandou então seu general (que era um velho e experiente comandante e grande protetor meu) pôr as tropas em ordem cerrada e fazê-las marchar por baixo de mim; a infantaria de vinte e quatro em fila e a cavalaria de dezesseis, com tambores rufando, bandeiras desfraldadas e piques em riste. Esse corpo compunha-se de três mil de infantaria e mil de cavalaria. Sua majestade deu ordens, sob pena de morte, de que cada soldado em sua marcha observasse a mais estrita decência com respeito à minha pessoa; o que, contudo, não pôde impedir alguns dos oficiais mais jovens de revirar os olhos ao passar por baixo de mim: e, para confessar a verdade, minhas calças estavam então em tão mau estado que ofereciam algumas ocasiões de riso e admiração.","ihadsentsomanymemorialsandpetitionsformy~ichihereoffertothepublic~1168":"Eu enviara tantos memoriais e petições pela minha liberdade que sua majestade finalmente mencionou o assunto, primeiro no gabinete e depois em pleno conselho; onde ninguém se opôs, exceto Skyresh Bolgolam, que se comprazia, sem provocação alguma, em ser meu inimigo mortal. Mas a decisão foi tomada contra ele por toda a mesa e confirmada pelo imperador. Esse ministro era galbet, ou almirante do reino, muito da confiança do amo e pessoa bem versada nos negócios, mas de compleição morosa e azeda. Foi, contudo, por fim persuadido a anuir; mas conseguiu que os artigos e condições sob os quais eu seria posto em liberdade, e que devia jurar, fossem redigidos por ele mesmo. Esses artigos me foram trazidos por Skyresh Bolgolam em pessoa, acompanhado de dois subsecretários e várias pessoas de distinção. Depois de lidos, exigiram-me que jurasse cumpri-los; primeiro à maneira de meu próprio país e depois pelo método prescrito por suas leis; que era segurar o pé direito com a mão esquerda e pôr o dedo médio da mão direita no alto da cabeça e o polegar na ponta da orelha direita. Mas, porque o leitor poderá ter curiosidade de ter alguma ideia do estilo e da maneira de expressão peculiares àquele povo, e de conhecer o artigo pelo qual recuperei minha liberdade, fiz uma tradução de todo o instrumento, palavra por palavra, o mais próximo que pude, que aqui ofereço ao público.","golbastomomaremevlamegurdiloshefinmullyu~eshallbeobligedtoperform~565":"Golbasto Momarem Evlame Gurdilo Shefin Mully Ully Gue, potentíssimo Imperador de Lilliput, delícia e terror do universo, cujos domínios se estendem por cinco mil blustrugs [cerca de doze milhas de circunferência] até os extremos do globo; monarca de todos os monarcas, mais alto que os filhos dos homens; cujos pés pressionam até o centro e cuja cabeça bate contra o sol; a cujo aceno os príncipes da terra tremem os joelhos; agradável como a primavera, confortável como o verão, fecundo como o outono, terrível como o inverno: sua sublimíssima majestade propõe ao Homem-Montanha, recém-chegado aos nossos domínios celestiais, os seguintes artigos, que, por solene juramento, será obrigado a cumprir:","1stthemanmountainshallnotdepartfromourdo~licenseunderourgreatseal~81":"1º, O Homem-Montanha não deixará os nossos domínios sem a nossa licença sob o nosso grande selo.","2ndheshallnotpresumetocomeintoourmetropo~warningtokeepwithindoors~131":"2º, Não ousará entrar em nossa metrópole sem a nossa expressa ordem; ocasião em que os habitantes terão duas horas de aviso para ficarem dentro de casa.","3rdthesaidmanmountainshallconfinehiswalk~wninameadoworfieldofcorn~112":"3º, O dito Homem-Montanha limitará seus passeios às nossas principais estradas reais e não tentará andar ou deitar-se num prado ou campo de trigo.","4thashewalksthesaidroadsheshalltaketheut~dswithouttheirownconsent~176":"4º, Ao andar pelas ditas estradas, terá o máximo cuidado de não pisar o corpo de nenhum de nossos amados súditos, de seus cavalos ou carros, nem tomará nas mãos nenhum de nossos súditos sem o consentimento deles.","5thifanexpressrequiresextraordinarydespa~afetoourimperialpresence~205":"5º, Se um mensageiro exigir despacho extraordinário, o Homem-Montanha será obrigado a levar no bolso, uma vez a cada lua, o mensageiro e o cavalo, numa viagem de seis dias, e a trazer de volta o dito mensageiro (se assim for requerido) são e salvo à nossa presença imperial.","6thheshallbeourallyagainstourenemiesinth~isnowpreparingtoinvadeus~119":"6º, Será nosso aliado contra os nossos inimigos na ilha de Blefuscu e fará o máximo para destruir sua frota, que agora se prepara para nos invadir.","7ththatthesaidmanmountainshallathistimes~ndotherourroyalbuildings~180":"7º, O dito Homem-Montanha, nas horas de lazer, auxiliará e assistirá nossos operários, ajudando a erguer certas grandes pedras para cobrir o muro do parque principal e outros edifícios reais nossos.","8ththatthesaidmanmountainshallintwomoons~hisownpacesroundthecoast~138":"8º, O dito Homem-Montanha, no prazo de duas luas, entregará um levantamento exato da circunferência de nossos domínios, por cômputo de seus próprios passos em redor da costa.","lastlythatuponhissolemnoathtoobserveallt~andothermarksofourfavour~207":"Por último, que, mediante seu solene juramento de observar todos os artigos acima, o dito Homem-Montanha receberá uma ração diária de carne e bebida suficiente para o sustento de 1724 de nossos súditos, com livre acesso à nossa pessoa real e outras marcas do nosso favor.","givenatourpalaceatbelfaboracthetwelfthda~inetyfirstmoonofourreign~71":"Dado em nosso palácio de Belfaborac, no décimo segundo dia da nonagésima primeira lua de nosso reinado.","isworeandsubscribedtothesearticleswithgr~nmeormightdoforthefuture~583":"Jurei e subscrevi esses artigos com grande alegria e contentamento, embora alguns deles não fossem tão honrosos quanto eu poderia desejar; o que procedia inteiramente da malícia de Skyresh Bolgolam, o alto-almirante: ao que minhas correntes foram imediatamente destrancadas e fiquei em plena liberdade. O próprio imperador, em pessoa, fez-me a honra de estar presente em toda a cerimônia. Apresentei meus agradecimentos prostrando-me aos pés de sua majestade: mas ele mandou que me levantasse; e, depois de muitas expressões graciosas, que, para evitar a censura de vaidade, não repetirei, acrescentou “que esperava que eu viesse a ser um servidor útil e merecesse bem todos os favores que já me conferira, ou que pudesse conferir no futuro”.","thereadermaypleasetoobservethatinthelast~teconomyofsogreataprince~648":"O leitor poderá observar que, no último artigo da recuperação de minha liberdade, o imperador estipula conceder-me uma quantidade de carne e bebida suficiente para o sustento de 1724 lilliputianos. Algum tempo depois, perguntando a um amigo da corte como haviam chegado a fixar aquele número determinado, ele me disse que os matemáticos de sua majestade, tendo tomado a altura do meu corpo com a ajuda de um quadrante e achando que excedia a deles na proporção de doze para um, concluíram, pela semelhança dos corpos, que o meu devia conter pelo menos 1724 dos deles e, consequentemente, exigiria tanta comida quanto fosse necessária para sustentar esse número de lilliputianos. Pelo que o leitor poderá fazer ideia da engenhosidade daquele povo, bem como da prudente e exata economia de tão grande príncipe."}$tr$::jsonb, 65)
